function canonical(spec: Spec): CanonicalProcedure {
  const legal = spec.authority.includes("LEI");
  return canonicalProcedureSchema.parse({
    id:`${spec.id.toLowerCase()}-${spec.slug}`,version:VERSION,maturity:"candidate",title:{pt:spec.title,en:`${spec.id} governed red-flag procedure`},role:"independent_quality_control",blueprintStage:spec.id<"RF-18"?6:7,
    owner:{role:"Head de DCM e Quality Control"},objective:`Detectar, investigar e tratar ${spec.id} sem converter sinal em veredito automático.`,product:`Finding ${spec.id} versionado com evidência, severidade, falsos positivos, tratamento e efeito.`,
    procedure:[
      {id:"detect",title:"Executar detector",instructions:[spec.trigger,"Se o parâmetro governado estiver ausente, emitir not_computable em vez de estimar um limiar."],mode:"deterministic",tools:["red_flag_truth"],evidenceInputs:["facts reconciliados","truth sets financeiros, de dívida, operação e estrutura","parâmetros versionados"]},
      {id:"investigate",title:"Controlar falso positivo",instructions:spec.investigate,mode:"deterministic",tools:["red_flag_truth"],evidenceInputs:["evidências do gatilho","respostas e documentos de confirmação"]},
      {id:"treat",title:"Definir tratamento e efeito",instructions:[spec.treatment,spec.untreatedEffect,"Tratamento e decisão precisam apontar para o fingerprint exato da flag."],mode:"human_judgment",tools:["red_flag_review"],evidenceInputs:["finding corrente","evidência de remediação","decisão humana persistida"]},
      {id:"record",title:"Registrar sem emitir parecer",instructions:["Persistir estado, evidências, perguntas, falsos positivos, tratamento e efeito a jusante.","Nunca afirmar aprovação, reprovação de crédito ou compromisso de capital."],mode:"deterministic",tools:["red_flag_truth"],evidenceInputs:["resultado completo do procedimento"]},
    ],
    output:{schemaId:`offroad.${spec.id.toLowerCase().replace("-","_")}.v1`,fields:[
      {id:"status",type:"enum",required:true,description:"Estado do detector e de sua revisão.",evidenceRequired:false,allowedValues:["clear","candidate","confirmed","false_positive","treated","not_computable","not_applicable"]},
      {id:"severity",type:"enum",required:true,description:"Severidade governada sem score médio.",evidenceRequired:false,allowedValues:["information","low","medium","high","critical"]},
      {id:"evidence_links",type:"array",required:true,description:"Evidências mínimas do gatilho e da investigação.",evidenceRequired:true},
      {id:"confirmation_questions",type:"array",required:true,description:"Perguntas necessárias para separar sinal e falso positivo.",evidenceRequired:false},
      {id:"treatment",type:"object",required:false,description:"Tratamento, comprovação e efeito a jusante.",evidenceRequired:true},
    ]},
    evidence:{hierarchy:["Fonte primária conciliada e ancorada","Calculation trace governado","Documento ou resposta datada de confirmação","Julgamento humano registrado para o fingerprint exato"],rules:["Sinal sem evidência mínima não vira flag confirmada.","Ausência de parâmetro governado produz not_computable.","Revisão stale não trata finding novo."],materialClaimsRequireSupport:true},
    tests:{unit:[`Executar ${spec.id} em clear, candidate e not_computable.`],gold:[`Detectar ${spec.id}, confirmar a evidência e aplicar tratamento no gold case aplicável.`],adversarial:[`Produzir falso positivo plausível de ${spec.id} e provar que a investigação o encerra.`],acceptance:["Reason code estável e evidência mínima presente.","Severidade composta nunca é elevada por modelo.","Declínio depende de decisão humana corrente."]},
    source:{path:`${SOURCE}#${spec.id}`,effectiveDate:"2026-08-25"},knowledge:{houseProcedureIds:[spec.id],authorities:spec.authority,referenceDataKeys:spec.referenceKeys??["policy.red-flags.detectors"],legalReviewRequired:legal},
    prerequisites:["Case truth sets correntes","Parâmetros de detector e materialidade vigentes"],dependencies:spec.id==="RF-19"?["rf-18-composite-families"]:spec.id==="RF-20"?["rf-19-mandate-decline-criteria"]:[],decisionRules:[spec.trigger,spec.treatment,spec.untreatedEffect],redFlags:[spec.title,"Evidência contraditória","Revisão vencida"],stopConditions:["Evidência mínima ausente para confirmar","Parâmetro obrigatório ausente","Decisão humana necessária e pendente"],exceptions:["Falso positivo exige razão e evidência persistidas; nunca apaga o finding original."],templates:[],examples:{positive:[spec.treatment],negative:["Converter o gatilho em veto ou parecer automático."]},runtime:{orchestration:"deterministic_pipeline",peerHandoffs:false,maxModelCalls:0,modelPurpose:[],allowedTools:["red_flag_truth","red_flag_review"]},
  });
