  feesPaidFromCash: Decimal.Value;
  cashContribution: Decimal.Value;
  adjustedEbitda?: Decimal.Value;
}) {
  const proFormaGrossDebt = decimal(input.grossDebt).plus(input.newDebt).minus(input.refinancedDebt);
