export function createCvmOpenDataEntityResolver(input: {
  fetch?: typeof fetch;
  now?: () => Date;
  cadastroUrl?: string;
} = {}): OfficialEntityResolver {
  const request = input.fetch ?? fetch;
  const now = input.now ?? (() => new Date());
