    ? `Company=${ordered[0].DENOM_CIA ?? ""} | reference=${ordered[0].DT_REFER ?? ""} | currency=${ordered[0].MOEDA ?? ""} | scale=${ordered[0].ESCALA_MOEDA ?? ""}`
