    ["short_term_debt", "2.01.04"],
    ["long_term_debt", "2.02.01"],
    ["revenue", "3.01"],
    ["ebit", "3.05"],
    ["net_income", "3.11"],
    ["operating_cash_flow", "6.01"],
  ] as const;
