      form,
      filingDate: recent.filingDate[index] ?? "",
      reportDate: recent.reportDate[index] ?? "",
      description: recent.primaryDocDescription[index] ?? "",
      url: `https://www.sec.gov/Archives/edgar/data/${Number(cik)}/${accessionPath}/${primaryDocument}`,
