    const fact = gaap[tag];
    if (!fact) continue;
    for (const [unit, observations] of Object.entries(fact.units)) {
      const selected = [...observations]
        .filter((item) => item.form === "10-K" || item.form === "10-Q")
        .sort((left, right) => String(right.filed).localeCompare(String(left.filed)))
        .slice(0, 4);
