        lines.push([
          `${tag} (${fact.label || tag})`,
          `value=${item.val}`,
          `unit=${unit}`,
          item.end ? `period_end=${item.end}` : null,
          item.filed ? `filed=${item.filed}` : null,
          item.form ? `form=${item.form}` : null,
          item.accn ? `accession=${item.accn}` : null,
