      evidenceCount: procedure.id === "Q-06" ? customerShares.length : statements.reduce((sum, item) => sum + item.lines.length, 0),
      missingInputs: procedure.missing,
      exceptionIds: relatedExceptions.map((item) => item.id),
    };
