packages/instrument-catalogue/src/assess.content:
import Decimal from "decimal.js";

import {catalogue} from "./catalogue";
import type {Instrument, InstrumentProfile, IssuerProfile} from "./types";

/**
 * Which instruments this company can actually use, which it cannot, and why.
 *
 * This answers the question the company came here unable to answer, and the shape of the answer
 * matters as much as the answer. A list of eligible instruments is a menu. What a desk gives is a
 * recommendation with the alternatives priced: "CCB. A debênture alcançaria mais investidores mas
 * exige virar S.A.; o CRA não se aplica porque o lastro não é agro." The blocked ones carry more
 * information than the eligible ones, because each blocked instrument tells the company something
 * true about itself that it can sometimes change.
 *
 * ## Two underwritings, not one
 *
 * Everything in the classic catalogue is repaid by cash generation, and this system sizes it with
 * DSCR and leverage over EBITDA. The venture track is repaid by the next round, and both of those
 * metrics are undefined or meaningless for a company burning cash on purpose. A desk that applies
 * one to the other tells a good startup it is uninvestable, which is not analysis but a category
 * error.
 *
 * So the assessment names which track it is on, and `capacityApplies` tells the caller whether
 * our capacity engine has anything useful to say. When it is false, the honest output is the
 * venture underwriting (round size, runway, recurring revenue) rather than a DSCR of zero
 * presented as a finding.
 */

export type Track = "cash_generation" | "venture";

export type BlockedReason = {
  eligibilityId: string;
  labels: {pt: string; en: string};
  explanation: {pt: string; en: string};
};

export type InstrumentVerdict = {
  instrument: Instrument;
  labels: {pt: string; en: string};
  status: "eligible" | "blocked";
  profile: InstrumentProfile;
  /** Every condition that failed. All of them, not the first: each one is a separate fact. */
  blockedBy: BlockedReason[];
  /** Weeks to funding, so the reader can weigh reach against urgency. */
  weeksToFunding: {min: number; max: number};
};

export type InstrumentAssessment = {
  track: Track;
  /**
   * Whether the DSCR and leverage machinery has anything to say about this company.
   *
   * False on the venture track. The caller must not present a coverage ratio computed from
   * negative EBITDA as though it were a finding.
   */
  capacityApplies: boolean;
  /** The recommendation, when one can be made. */
  recommended: Instrument | null;
  /** Why that one and not the others, written for the company to read. */
  rationale: {pt: string; en: string} | null;
  eligible: InstrumentVerdict[];
  blocked: InstrumentVerdict[];
  /**
   * What the company could change to unlock an instrument, most valuable first.
   *
   * Only conditions that are actually changeable appear here. "Your credit is not agribusiness"
   * is a fact about the company; "you are a limitada" is a decision it could revisit, and saying
   * which is which is the difference between advice and a list of rejections.
   */
  unlockable: Array<{instrument: Instrument; change: {pt: string; en: string}}>;
};

/** Conditions a company can act on, as opposed to facts about what it is. */
const CHANGEABLE = new Set(["legal_form", "minimum_size", "runway", "round_proportion"]);

/**
 * Ranking among the eligible.
 *
 * Reach first, because reaching more buyers is what produces competition and competition is what
 * produces tenor and price. Then speed, because a transaction that arrives after the need has
 * passed helped nobody. Deliberately not a score: the caller sees the order and the reasons.
 */
const REACH_ORDER: readonly Instrument[] = [
  "debenture_incentivada",
  "debenture",
  "cri",
  "cra",
  "nota_comercial",
  "fidc",
  "cdca",
  "venture_debt",
  "ccb",
  "finame",
  "project_finance",
  "cpr",
  "revenue_based_financing",
  "leasing",
  "receivables_purchase",
  "mutuo_conversivel",
  "direct_loan",
  "equity_kicker_debt",
];

const reachRank = (id: Instrument) => {
  const index = REACH_ORDER.indexOf(id);
  return index === -1 ? REACH_ORDER.length : index;
};

const VENTURE: readonly Instrument[] = ["venture_debt", "mutuo_conversivel", "revenue_based_financing"];

const money = (value: string) =>
  `R$ ${Number(value).toLocaleString("pt-BR", {maximumFractionDigits: 0})}`;

export function assessInstruments(issuer: IssuerProfile): InstrumentAssessment {
  // Venture-backed is the signal, not sector or size: a profitable software company raises like
  // any other company, and a capital-intensive startup with a round behind it does not.
  const track: Track = issuer.venturebacked === true ? "venture" : "cash_generation";

  const verdicts: InstrumentVerdict[] = catalogue.map((profile) => {
    const blockedBy = profile.eligibility
      .filter((condition) => !condition.test(issuer))
      .map((condition) => ({
        eligibilityId: condition.id,
        labels: condition.labels,
        explanation: condition.whenUnmet,
      }));

    return {
      instrument: profile.id,
      labels: profile.labels,
      status: blockedBy.length === 0 ? ("eligible" as const) : ("blocked" as const),
      profile,
      blockedBy,
      weeksToFunding: profile.weeksToFunding,
    };
  });

  // On the venture track the classic instruments are not wrong, they are simply not the
  // conversation: a startup can technically sign a CCB, and the lender who would sign it is
  // looking at the round, which is what venture debt already is.
  const relevant = verdicts.filter((verdict) =>
    track === "venture" ? true : !VENTURE.includes(verdict.instrument),
  );

  const eligible = relevant
    .filter((verdict) => verdict.status === "eligible")
    .sort(
      (a, b) =>
        reachRank(a.instrument) - reachRank(b.instrument) ||
        a.weeksToFunding.max - b.weeksToFunding.max,
    );

  const blocked = relevant
    .filter((verdict) => verdict.status === "blocked")
    // Nearly-eligible first: one failed condition is a conversation, four is a different company.
    .sort((a, b) => a.blockedBy.length - b.blockedBy.length || reachRank(a.instrument) - reachRank(b.instrument));

  const recommended = eligible[0]?.instrument ?? null;

  const unlockable = blocked
    .filter((verdict) => verdict.blockedBy.length === 1 && CHANGEABLE.has(verdict.blockedBy[0]!.eligibilityId))
    .map((verdict) => ({instrument: verdict.instrument, change: verdict.blockedBy[0]!.explanation}));

  return {
    track,
    capacityApplies: track === "cash_generation",
    recommended,
    rationale: recommended ? buildRationale(eligible, blocked, issuer, track) : null,
    eligible,
    blocked,
    unlockable,
  };
}

/**
 * The sentence a banker would say, assembled from what is actually true.
 *
 * It names the recommendation, the runner-up and why it lost, and the nearest blocked instrument
 * with what would unlock it. Three clauses, because that is what somebody can hold in their head
 * walking into a meeting.
 */
function buildRationale(
  eligible: InstrumentVerdict[],
  blocked: InstrumentVerdict[],
  issuer: IssuerProfile,
  track: Track,
): {pt: string; en: string} {
  const first = eligible[0]!;
  const second = eligible[1];
  const nearest = blocked.find((verdict) => verdict.blockedBy.length === 1);

  const opening = {
    pt: `Recomendamos ${first.labels.pt.toLowerCase()}${issuer.amount ? ` para os ${money(issuer.amount)} pretendidos` : ""}: entre o que a companhia pode usar hoje, é o que alcança o conjunto mais amplo de compradores, com montagem em ${first.weeksToFunding.min} a ${first.weeksToFunding.max} semanas.`,
    en: `We recommend ${first.labels.en.toLowerCase()}${issuer.amount ? ` for the ${money(issuer.amount)} sought` : ""}: among what the company can use today, it reaches the widest set of buyers, assembled in ${first.weeksToFunding.min} to ${first.weeksToFunding.max} weeks.`,
  };

  const runnerUp = second
    ? {
        pt: ` A alternativa seria ${second.labels.pt.toLowerCase()}, mais rápida em alguns casos e com alcance menor.`,
        en: ` The alternative would be ${second.labels.en.toLowerCase()}, faster in some cases and with narrower reach.`,
      }
    : {pt: "", en: ""};

  const unlock = nearest
    ? {
        pt: ` ${nearest.labels.pt} não está disponível: ${nearest.blockedBy[0]!.explanation.pt}`,
        en: ` ${nearest.labels.en} is not available: ${nearest.blockedBy[0]!.explanation.en}`,
      }
    : {pt: "", en: ""};

  const trackNote =
    track === "venture"
      ? {
          pt: " Como a companhia tem rodada institucional, a análise segue a régua de venture: tamanho da última rodada, receita recorrente e meses de caixa, e não cobertura por EBITDA.",
          en: " Because the company has an institutional round, the analysis follows the venture yardstick: last round size, recurring revenue and months of cash, rather than EBITDA coverage.",
        }
      : {pt: "", en: ""};

  return {
    pt: opening.pt + runnerUp.pt + unlock.pt + trackNote.pt,
    en: opening.en + runnerUp.en + unlock.en + trackNote.en,
  };
}

/**
 * How much venture debt the market would size against the last round.
 *
 * Separate from the eligibility test because a company under the ceiling still benefits from
 * being told where the ceiling is: the number is the negotiation, and arriving at it already
 * knowing the convention is worth more than being told no afterwards.
 */
export function ventureDebtCeiling(lastRoundAmount: string, proportion = "0.30"): string {
  return new Decimal(lastRoundAmount).times(proportion).toDecimalPlaces(2).toFixed();
}

packages/instrument-catalogue/src/types..content:
import {z} from "zod";

/**
 * Every way a Brazilian mid-market company can raise debt, and what each one actually costs it.
 *
 * This is the answer to a question the company came here unable to answer: "essa operação sai
 * como o quê?" Nobody running a R$ 80 million supermarket chain should be expected to know that
 * a debênture requires becoming a sociedade anônima, that a CRA needs the credit to qualify as
 * agribusiness, or that a nota comercial became available to limitadas only in 2021. That is the
 * expertise they are buying, and asking them for it is handing the problem back.
 *
 * **The instrument is usually the first thing that eliminates a lender, and it eliminates by
 * rule rather than by taste.** An FIDC buys credit rights and cannot hold a debenture. A CRI has
 * to be issued by a securitisation company, not by the borrower. A limitada cannot issue a
 * debenture at all, whatever its numbers look like. Modelling this as a preference would erase
 * the constraint that most often decides who can even look at a transaction.
 *
 * ## The taxonomy that explains the rest
 *
 * The instruments do not all put the company in the same position, and `issuerRole` is what makes
 * the pros and cons fall out rather than having to be memorised:
 *
 * - `issues` — the company itself is the issuer and the debtor. Debenture, nota comercial, CPR.
 *   It reaches investors directly and it carries the issuance machinery.
 * - `originates` — the company originates a credit that somebody else turns into a security.
 *   CRI and CRA are issued exclusively by a companhia securitizadora (Lei 14.430/2022), so the
 *   company's counterparty is the securitisation company, not the final investor.
 * - `assigns` — the company sells a receivable and the buyer's risk moves toward the payer.
 *   FIDC, receivables discounting. This is why a concentrated or already-pledged receivables book
 *   changes everything here and matters much less elsewhere.
 * - `borrows` — a bilateral contract with a single counterparty. CCB, bank loan, leasing, FINAME.
 *   Fastest and simplest, reaches the fewest buyers.
 *
 * ## Honesty about this file
 *
 * The legal claims here were checked against primary sources, and the ones that decide eligibility
 * carry `legalBasis` so a lawyer can verify us rather than trust us. It is still a working
 * reference and not legal advice: the rite, the exemptions and the required parties must be
 * confirmed for each transaction with counsel, which is exactly what `disclaimer` says and what
 * any material generated from this has to repeat.
 */

export const instrumentSchema = z.enum([
  // The company issues
  "debenture",
  "debenture_incentivada",
  "nota_comercial",
  "cpr",
  // Somebody else issues against credit the company originated
  "cri",
  "cra",
  "cdca",
  // The company assigns a receivable
  "fidc",
  "receivables_purchase",
  // Bilateral
  "ccb",
  "direct_loan",
  "leasing",
  "finame",
  "project_finance",
  "equity_kicker_debt",
  // Backed by a round rather than by EBITDA
  "venture_debt",
  "mutuo_conversivel",
  "revenue_based_financing",
]);
export type Instrument = z.infer<typeof instrumentSchema>;

export const issuerRoleSchema = z.enum(["issues", "originates", "assigns", "borrows"]);
export type IssuerRole = z.infer<typeof issuerRoleSchema>;

/**
 * The legal form of the company that will owe the money.
 *
 * Modelled as an explicit enum rather than a boolean because the difference between an S.A.
 * fechada and an S.A. aberta decides which offer rites are available, and the difference between
 * a limitada and either of them decides whether half the catalogue exists at all.
 */
export const legalFormSchema = z.enum([
  "sa_aberta",
  "sa_fechada",
  "ltda",
  "cooperativa",
  "produtor_rural",
  "outro",
]);
export type LegalForm = z.infer<typeof legalFormSchema>;

/** A condition that must hold or the instrument is impossible, not merely unattractive. */
export type Eligibility = {
  id: string;
  labels: {pt: string; en: string};
  /** Evaluated against the issuer profile. Returning false means the instrument is out. */
  test: (issuer: IssuerProfile) => boolean;
  /** What to say when it fails, including what would change it when anything can. */
  whenUnmet: {pt: string; en: string};
};

export type IssuerProfile = {
  legalForm: LegalForm;
  /** Audited statements exist for at least the last full year. */
  auditedStatements?: boolean;
  /** The credit being financed qualifies as agribusiness under the CRA/CDCA rules. */
  agribusinessCredit?: boolean;
  /** The credit being financed qualifies as real estate under the CRI rules. */
  realEstateCredit?: boolean;
  /** The company has a receivables book that could be assigned. */
  hasAssignableReceivables?: boolean;
  /** The company is a rural producer or a cooperative of them. */
  ruralProducer?: boolean;
  /** The use of proceeds is an infrastructure project under Lei 12.431. */
  infrastructureProject?: boolean;
  /** The purchase being financed is machinery or equipment. */
  financingEquipment?: boolean;
  /** Amount sought, decimal string. Decides whether fixed structuring costs are bearable. */
  amount?: string;

  // ---- the venture track -----------------------------------------------------------------
  //
  // A startup fails every test the rest of this system applies. Leverage over EBITDA is
  // undefined when EBITDA is negative, and DSCR is meaningless when the cash that repays comes
  // from the next round rather than from operations. That is not a gap in the company: it is a
  // different underwriting, and the instruments below are underwritten on the size of the last
  // round, the recurring revenue and the months of runway.

  /** Closed an institutional equity round. The precondition for venture debt in practice. */
  venturebacked?: boolean;
  /** Size of the last round, decimal string. Venture debt is typically sized against it. */
  lastRoundAmount?: string;
  /** Annual recurring revenue, decimal string. The base for recurring-revenue lending. */
  arr?: string;
  /** Months of cash at the current burn. Below roughly six, a lender is funding the fall. */
  runwayMonths?: number;
  /** Revenue is recurring and contracted rather than transactional. */
  recurringRevenue?: boolean;
};

export type InstrumentProfile = {
  id: Instrument;
  labels: {pt: string; en: string};
  issuerRole: IssuerRole;
  /** One sentence a non-technical reader understands, with no jargon left undefined. */
  what: {pt: string; en: string};
  /** The statute or regulation that governs it, so a lawyer can check this file. */
  legalBasis: string;
  eligibility: readonly Eligibility[];
  /** Which kinds of buyer this reaches. Wider is not automatically better; it costs more. */
  reaches: readonly {pt: string; en: string}[];
  /** Who has to be involved. Every party is a fee and a week. */
  parties: readonly {pt: string; en: string}[];
  pros: readonly {pt: string; en: string}[];
  cons: readonly {pt: string; en: string}[];
  /**
   * Below this amount the fixed costs of structuring usually eat the benefit.
   *
   * A range rather than a number, and deliberately conservative: it is the desk's read of where
   * the economics stop working in the Brazilian mid-market, not a rule, and a transaction below
   * it is discouraged rather than refused.
   */
  economicFloor?: {amount: string; note: {pt: string; en: string}};
  /** Weeks from mandate to money, when nothing goes wrong. */
  weeksToFunding: {min: number; max: number};
};

export const CATALOGUE_DISCLAIMER = {
  pt: "Referência de trabalho da mesa, não parecer jurídico. O rito aplicável, as dispensas de registro e os participantes obrigatórios precisam ser confirmados com assessoria legal na data da operação.",
  en: "The desk's working reference, not legal advice. The applicable rite, registration exemptions and required parties must be confirmed with counsel at the date of the transaction.",
} as const;

packages/financial-model/src/adopted-cap.content:
import {createHash} from "node:crypto";
import {z} from "zod";
import {buildCapitalPeriodCash, financialCoreVersion, type CapitalMovement, type CapitalPeriodCashInput} from "@offroad/financial-core";
import {readContextualBasis, type AdoptionBasisEntry} from "@offroad/reconciliation";
import {adoptedValueSelectionSchema as selection} from "./adopted-debt-inputs";
import {adoptedFinancingInputSchema, calculateAdoptedFinancingLiquidity} from "./adopted-financing-costs";
import {adoptedOperatingProjectionInputSchema, calculateAdoptedOperatingProjection} from "./adopted-operating-projection";
import {resolveAdoptedCurrencyValues} from "./adopted-numeric-representation";
import {hasUnitScale} from "./adopted-input-scale";

export const adoptedCapitalPeriodCashInputSchema = z.strictObject({
  operating: adoptedOperatingProjectionInputSchema,
  funding: z.discriminatedUnion("kind", [
    z.strictObject({kind: z.literal("debt"), input: adoptedFinancingInputSchema}),
    z.strictObject({kind: z.literal("no_debt"), inventory: selection, openingAvailable: selection, openingRestricted: selection}),
  ]),
  operatingCashAccount: selection, capitalMovementInventory: selection,
  capitalMovements: z.strictObject({ids: selection, economicIds: selection, dates: selection,
    amounts: selection, accounts: selection, kinds: selection, reasons: selection}).nullable(),
});
const next = (value: string) => {const d = new Date(`${value}T00:00:00Z`); d.setUTCDate(d.getUTCDate() + 1); return d.toISOString().slice(0, 10);};
const money = z.string().regex(/^-?\d{1,24}(?:\.\d{1,8})?$/);
const positive = z.string().regex(/^\d{1,24}(?:\.\d{1,8})?$/);

/** Binds operating, debt and capital cash to one immutable basis. Partial budgets do not
 * certify completeness, a market quote or execution authority. No direct cash-flow overlay
 * can be mixed with the accrual-to-cash budget and counted twice. */
export function calculateAdoptedCapitalPeriodCash(raw: unknown) {
  const input = adoptedCapitalPeriodCashInputSchema.parse(raw); const context = input.operating;
  const operation = calculateAdoptedOperatingProjection(context);
  let funded: ReturnType<typeof calculateAdoptedFinancingLiquidity> | null = null;
  if (input.funding.kind === "debt") {
    const f = input.funding.input;
    for (const field of ["entityId", "perimeter", "currency", "scenario", "openingScenario", "openingDate", "endDate"] as const) {
      if (f[field] !== context[field]) throw new Error("capital_basis_context_mismatch");
    }
    if (f.envelope.canonical !== context.envelope.canonical || f.envelope.fingerprint !== context.envelope.fingerprint
      || f.scope.workId !== context.scope.workId || f.scope.purpose !== context.scope.purpose || f.scope.versionId !== context.scope.versionId) throw new Error("capital_basis_snapshot_mismatch");
    if (f.operatingEvents.length) throw new Error("capital_basis_duplicate_direct_operating_cash");
    funded = calculateAdoptedFinancingLiquidity(f);
  }
  const basis = readContextualBasis(context.envelope, context.scope); const entries = new Map(basis.entries.map(e => [e.decisionId, e]));
  const used = new Map<string, AdoptionBasisEntry>(); const observations = new Map<string, string>();
  function retain(e: AdoptionBasisEntry) {
    const prior = e.observationId ? observations.get(e.observationId) : undefined;
    if (prior && prior !== e.decisionId) throw new Error("capital_basis_reused_observation");
    if (e.observationId) observations.set(e.observationId, e.decisionId);
    used.set(e.decisionId, e);
  }
  [...operation.contributions, ...(funded?.contributions ?? [])].forEach(retain);
  const gaps = [...operation.gaps, ...(funded?.gaps ?? [])];
  const bindings: {operand: string; decisionId: string | null; interpretationDecisionIds: string[]}[] = [];
  const numericIds = [...(input.capitalMovements ? [input.capitalMovements.amounts] : []),
    ...(input.funding.kind === "no_debt" ? [input.funding.openingAvailable, input.funding.openingRestricted] : [])].flatMap(s => s.decisionId ? [s.decisionId] : []);
  const normalization = numericIds.length ? resolveAdoptedCurrencyValues({envelope: context.envelope, scope: context.scope, decisionIds: numericIds, groups: context.numericInterpretations}) : null;
  const normalized = new Map(normalization?.values.map(v => [v.decisionId, v]) ?? []);
  function read<T>(s: z.infer<typeof selection>, path: string, unit: string, type: "number" | "text" | "list", schema: z.ZodType<T>, opening = false): T | null {
    const numeric = s.decisionId ? normalized.get(s.decisionId) : undefined;
    bindings.push({operand: path, decisionId: s.decisionId, interpretationDecisionIds: numeric?.interpretationDecisionIds ?? []});
    if (!s.decisionId) {gaps.push({operand: path, reason: s.missingReason!}); return null;}
    const e = entries.get(s.decisionId); const d = e?.dimensions;
    if (!e || used.has(e.decisionId)) throw new Error("capital_basis_reused_or_missing_contribution");
    if (e.fieldPath !== path || e.value.type !== type || e.definitionKind !== s.definitionKind
      || d!.definitionVersionId !== s.definitionVersionId || d!.entityId !== context.entityId || d!.perimeter !== context.perimeter
      || d!.currency !== context.currency || d!.unit !== unit || d!.periodStart !== (opening ? null : next(context.openingDate))
      || d!.periodEnd !== (opening ? context.openingDate : context.endDate) || d!.scenario !== (opening ? context.openingScenario : context.scenario)
      || (unit !== "currency" && !hasUnitScale(d!.scale))) throw new Error("capital_basis_context_mismatch");
    retain(e);
    if (unit === "currency") {
      if (!numeric?.trace) {gaps.push({operand: path, reason: "Numeric representation has not been adopted"}); return null;}
      numeric.interpretationDecisionIds.forEach(id => retain(entries.get(id)!));
      return schema.parse(type === "number" ? numeric.trace.values[0] : numeric.trace.values);
    }
    return schema.parse(e.value.value);
  }
  read(input.operatingCashAccount, "capital.operatingCashAccount", "convention", "text", z.literal("available"));
  const inventory = read(input.capitalMovementInventory, "capital.movementInventory", "convention", "text", z.enum(["declared_complete", "unknown"]));
  const inventoryReason = input.capitalMovementInventory.decisionId ? entries.get(input.capitalMovementInventory.decisionId)!.reason : input.capitalMovementInventory.missingReason!;
  if (inventory === "unknown") gaps.push({operand: "capital.movementInventory", reason: inventoryReason});
  let openingAvailable = funded?.liquidity?.opening.available ?? null; let openingRestricted = funded?.liquidity?.opening.restricted ?? null;
  let noDebtReason: string | null = null;
  if (input.funding.kind === "no_debt") {
    const declaration = read(input.funding.inventory, "capital.financingInventory", "convention", "text", z.literal("no_debt_or_financing"));
    noDebtReason = declaration && input.funding.inventory.decisionId ? entries.get(input.funding.inventory.decisionId)!.reason : null;
    openingAvailable = read(input.funding.openingAvailable, "liquidity.available_cash", "currency", "number", money, true);
    openingRestricted = read(input.funding.openingRestricted, "liquidity.restricted_cash", "currency", "number", positive, true);
  }
  const movements: CapitalMovement[] = [];
  if (input.capitalMovements) {
    const selections = input.capitalMovements;
    const list = <T>(name: keyof typeof selections, unit: string, schema: z.ZodType<T>) => read(selections[name], `capital.movements.${name}`, unit, "list", z.array(schema).min(1).max(2000));
    const ids = list("ids", "identity", z.string().trim().min(1).max(160)); const economicIds = list("economicIds", "identity", z.string().trim().min(1).max(160));
    const dates = list("dates", "date", z.iso.date()); const amounts = list("amounts", "currency", positive);
    const accounts = list("accounts", "convention", z.enum(["available", "restricted"]));
    const kinds = list("kinds", "convention", z.enum(["equity_contribution", "distribution", "asset_sale", "acquisition"]));
    const reasons = list("reasons", "explanation", z.string().trim().min(1).max(2000));
    if (ids && economicIds && dates && amounts && accounts && kinds && reasons) {
      if ([economicIds, dates, amounts, accounts, kinds, reasons].some(v => v.length !== ids.length)) throw new Error("capital_basis_series_length_mismatch");
      ids.forEach((id, n) => movements.push({id, economicId: economicIds[n]!, date: dates[n]!, amount: amounts[n]!, account: accounts[n]!, kind: kinds[n]!, reason: reasons[n]!}));
    }
  }
  let cash: ReturnType<typeof buildCapitalPeriodCash> | null = null;
  if (!gaps.length && operation.projection) {
    const op = operation.projection;
    const financing: CapitalPeriodCashInput["financing"] = input.funding.kind === "no_debt"
      ? {status: "no_debt_or_financing", reason: noDebtReason!} : {status: "provided", input: funded!.financing!.operands};
    cash = buildCapitalPeriodCash({operating: {currency: op.currency, openingDate: op.openingDate, endDate: op.endDate, convention: op.convention,
      openingWorkingCapital: op.rows[0]!.operands.openingWorkingCapital, periods: op.rows.map(row => row.operands)},
      financing, openingAvailable, openingRestricted, operatingCashAccount: "available", capitalMovements: movements,
      capitalMovementInventory: {status: inventory!, reason: inventoryReason}});
  }
  const payload = {schemaVersion: "adopted-capital-period-cash.v1" as const, financialCoreVersion,
    scope: context.scope, entityId: context.entityId, perimeter: context.perimeter, currency: context.currency,
    scenario: context.scenario, openingScenario: context.openingScenario, openingDate: context.openingDate, endDate: context.endDate,
    basisFingerprint: context.envelope.fingerprint, status: cash?.status === "calculated" ? "partial_composition" as const : "missing_inputs" as const,
    operation, funding: funded, cash, gaps, bindings, normalization, contributions: [...used.values()],
    classification: [...used.values()].some(e => e.kind === "hypothesis") ? "working_hypothesis" as const : "working_selection" as const,
    derivedDependencies: cash?.rows?.map(row => ({periodId: row.periodId, decisionIds: [...used.keys()]})) ?? [], grantsExecution: false as const};
  return {...payload, fingerprint: createHash("sha256").update(JSON.stringify(payload)).digest("hex")};
}

packages/market-reference/src/decision-r.content:
/** Metadata sufficiency for a decision reference, not a quote, price calculation or permission.
 * The caller supplies an authorized source-version snapshot and revalidates rights at use. */
export type DecisionMarketReference = {
  id: string; sourceVersionId: string; observationIds: string[];
  observedOn: string; validUntil: string; instrument: string; currency: string; indexer: string;
  subjectEntityId: string | null;
  kind: "market_context" | "indicative_terms" | "contracted_terms";
  rightsState: "eligible" | "unknown" | "revoked";
  qualifier: string;
};
export function reviewDecisionMarketReference(reference: DecisionMarketReference, target: {
  asOf: string; entityId: string; instrument: string; currency: string; indexer: string;
  selectedObservationIds: readonly string[];
}) {
  const date = (value: string) => {
    const parsed = new Date(`${value}T00:00:00Z`);
    return /^\d{4}-\d{2}-\d{2}$/.test(value) && Number.isFinite(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value;
  };
  if (!date(target.asOf) || !date(reference.observedOn) || !date(reference.validUntil)
    || reference.observedOn > reference.validUntil || !reference.id?.trim() || !reference.sourceVersionId?.trim()
    || !reference.qualifier?.trim() || !Array.isArray(reference.observationIds) || reference.observationIds.length > 256
    || new Set(reference.observationIds).size !== reference.observationIds.length
    || !["market_context", "indicative_terms", "contracted_terms"].includes(reference.kind)
    || !["eligible", "unknown", "revoked"].includes(reference.rightsState)) throw new Error("decision_market_reference_invalid");
  const reasons: string[] = [];
  if (reference.rightsState !== "eligible") reasons.push("rights_not_eligible");
  if (reference.observedOn > target.asOf) reasons.push("future_observation");
  if (reference.validUntil < target.asOf) reasons.push("expired_reference");
  for (const field of ["instrument", "currency", "indexer"] as const) if (reference[field] !== target[field]) reasons.push(`${field}_mismatch`);
  if (reference.kind !== "market_context" && reference.subjectEntityId !== target.entityId) reasons.push("entity_specific_terms_required");
  if (!reference.observationIds.length || reference.observationIds.some(id => !target.selectedObservationIds.includes(id))) reasons.push("selected_observation_missing");
  return {version: "decision-market-reference.v1", reference: structuredClone(reference), target: structuredClone(target),
    status: reasons.length ? "unusable_for_comparison" as const : reference.kind === "market_context" ? "context_only" as const : "terms_for_review" as const,
    reasons, grantsAccess: false as const, confirmsFundingAvailability: false as const,
    requiresLiveRightsCheck: true as const};
}

packages/market-reference/src/pricing-tr.content:
import Decimal from "decimal.js";

import type {IndicativePrice, PriceAdjustment, PricedInstrument, RatingBand, SpreadBand} from "./index";

export const pricingTruthVersion = "2026.08.25-v1";

type Status = "completed" | "partial" | "blocked" | "not_computable" | "not_applicable";

export type PricingObservation = {
  id: string;
  sourceId: string;
  sourceOwner: string;
  sourceKind: "public_closing" | "direct_manager_confirmation" | "term_sheet" | "indication" | "sounding" | "authorized_historical";
  confidentiality: "public" | "aggregated_confidential" | "restricted_internal";
  observedOn: string;
  validUntil: string;
  status: "closed" | "term" | "indication" | "sounding";
  instrument: PricedInstrument;
  rating: RatingBand;
  normalizedSpreadBps: number;
  normalizationMethod: string;
  tenorMonths: number;
  securityClass: string;
  amortizationClass: string;
  sectorGroup: string;
  amount: string;
  regime: string;
  quality: number;
  aggregateAuthorized: boolean;
  economics?: {
    quotedSpreadBps: number;
    feeBps: number;
    oidBps: number;
    warrantBps: number;
    hedgeBps: number;
  };
};

export type GovernedPriceAdjustment = PriceAdjustment & {
  sourceId: string;
  observedOn: string;
  validUntil: string;
};

export type PricingCostComponent = {
  id: string;
  label: string;
  sourceId: string;
  validUntil: string;
  oneTimeAmount?: string;
  annualAmount?: string;
};

export type PricingPolicy = {
  version: string;
  asOf: string;
  regime: string;
  status: "active" | "invalidated";
  minObservations: number;
  minDistinctSources: number;
  minQuality: number;
  maxTenorDeltaMonths: number;
  minAmountRatio: string;
  maxAmountRatio: string;
  minBandWidthBps: number;
  maxBandWidthBps: number;
};

export type PricingTarget = {
  instrument: PricedInstrument;
  rating: RatingBand;
  cdi: string;
  tenorMonths: number;
  securityClass: string;
  amortizationClass: string;
  sectorGroup: string;
  amount: string;
  indexer: "cdi" | "ipca" | "fixed" | "other";
  indexerRationale?: string;
  targetBuyer?: string;
  expectedSpreadBps?: number;
  currentAllIn?: string;
};

export type PricingProcedureResult = {
  procedureId: `PR-${string}`;
  status: Status;
  result: Record<string, unknown> | null;
  outputCount: number;
  evidenceCount: number;
  missingInputs: string[];
  exceptionIds: string[];
};

export type PricingTruthSet = {
  version: string;
  policyVersion: string;
  status: "complete" | "partial" | "blocked";
  decision: "reference_available" | "abstain";
  indicativePrice: IndicativePrice | null;
  sample: {
    eligible: PricingObservation[];
    rejected: Array<{id: string; reasons: string[]}>;
    distinctSources: number;
    latestObservation: string | null;
  };
  allIn: {
    annualizedCostBps: number | null;
    totalRate: {min: string; max: string} | null;
    components: Array<PricingCostComponent & {annualizedBps: number | null}>;
  };
  exceptions: Array<{id: string; severity: "medium" | "high" | "critical"; message: string; affectedProcedures: `PR-${string}`[]}>
  missingInputs: string[];
  procedureCoverage: PricingProcedureResult[];
};

const isoValid = (value: string) => /^\d{4}-\d{2}-\d{2}$/.test(value) && Number.isFinite(Date.parse(`${value}T00:00:00Z`));
const median = (values: number[]) => {
  const ordered = [...values].sort((a, b) => a - b);
  const middle = Math.floor(ordered.length / 2);
  return ordered.length % 2 ? ordered[middle]! : (ordered[middle - 1]! + ordered[middle]!) / 2;
};
const moneyRatio = (observation: string, target: string) => new Decimal(observation).div(target);
const fmt = (value: number, locale: "pt" | "en") => `${value >= 0 ? "+" : "-"} ${Math.abs(value / 100).toLocaleString(locale === "pt" ? "pt-BR" : "en-US", {maximumFractionDigits: 2})}%`;

export function buildPricingTruthSet(input: {
  target: PricingTarget | null;
  policy?: PricingPolicy;
  observations?: readonly PricingObservation[];
  adjustments?: readonly GovernedPriceAdjustment[];
  costs?: readonly PricingCostComponent[];
  weightedAverageLifeYears?: string;
}): PricingTruthSet {
  const policy = input.policy;
  const target = input.target;
  const observations = [...(input.observations ?? [])];
  const missing = new Set<string>();
  const exceptions: PricingTruthSet["exceptions"] = [];
  const rejected: PricingTruthSet["sample"]["rejected"] = [];

  if (!target) missing.add("pricing.target");
  if (!policy) missing.add("pricing.policy");
  if (!observations.length) missing.add("pricing.observations");
  if (target && target.indexer !== "cdi") {
    missing.add("pricing.supported_indexer_curve");
    exceptions.push({
      id: "unsupported-indexer-curve",
      severity: "critical",
      message: "The governed pricing engine does not yet have a validated all-in curve for this indexer.",
      affectedProcedures: ["PR-01", "PR-06", "PR-07", "PR-09", "PR-10", "PR-11"],
    });
  }
  if (policy?.status === "invalidated") exceptions.push({id: "pricing-regime-invalidated", severity: "critical", message: "The active pricing regime was invalidated and must be rebuilt before a new reference is published.", affectedProcedures: ["PR-01", "PR-02", "PR-07", "PR-09", "PR-12"]});

  const eligible = target && policy ? observations.filter((observation) => {
    const reasons: string[] = [];
    if (!isoValid(observation.observedOn) || !isoValid(observation.validUntil)) reasons.push("invalid_date");
    else if (observation.validUntil < policy.asOf) reasons.push("expired");
    if (!observation.aggregateAuthorized) reasons.push("aggregate_not_authorized");
    if (!observation.sourceOwner) reasons.push("missing_owner");
    if (observation.confidentiality === "restricted_internal") reasons.push("restricted_from_aggregate");
    if (observation.quality < policy.minQuality) reasons.push("quality_below_policy");
    if (observation.regime !== policy.regime) reasons.push("different_regime");
    if (observation.instrument !== target.instrument) reasons.push("different_instrument");
    if (observation.rating !== target.rating) reasons.push("different_risk_band");
    if (observation.securityClass !== target.securityClass) reasons.push("different_security");
    if (observation.amortizationClass !== target.amortizationClass) reasons.push("different_amortization");
    if (observation.sectorGroup !== target.sectorGroup) reasons.push("different_sector");
    if (Math.abs(observation.tenorMonths - target.tenorMonths) > policy.maxTenorDeltaMonths) reasons.push("tenor_outside_window");
    if (new Decimal(target.amount).lte(0) || new Decimal(observation.amount).lte(0)) reasons.push("invalid_amount");
    else {
      const ratio = moneyRatio(observation.amount, target.amount);
      if (ratio.lt(policy.minAmountRatio) || ratio.gt(policy.maxAmountRatio)) reasons.push("amount_outside_window");
    }
    if (!observation.sourceId || !observation.normalizationMethod) reasons.push("missing_lineage");
    if (observation.economics) {
      const normalized = observation.economics.quotedSpreadBps
        + observation.economics.feeBps
        + observation.economics.oidBps
        + observation.economics.warrantBps
        + observation.economics.hedgeBps;
      if (Math.abs(normalized - observation.normalizedSpreadBps) > 0.01) reasons.push("normalization_identity_failed");
    }
    if (reasons.length) rejected.push({id: observation.id, reasons});
    return reasons.length === 0;
  }) : [];

  const distinctSources = new Set(eligible.map((observation) => observation.sourceId)).size;
  const sampleSufficient = Boolean(policy?.status === "active" && eligible.length >= policy.minObservations && distinctSources >= policy.minDistinctSources);
  if (policy && eligible.length < policy.minObservations) exceptions.push({id: "insufficient-observations", severity: "critical", message: "Comparable observations do not reach the governed minimum sample.", affectedProcedures: ["PR-01", "PR-02", "PR-07", "PR-09"]});
  if (policy && distinctSources < policy.minDistinctSources) exceptions.push({id: "insufficient-independent-sources", severity: "critical", message: "The sample does not reach the governed minimum number of distinct sources.", affectedProcedures: ["PR-02", "PR-07", "PR-13"]});

  const validAdjustments = (input.adjustments ?? []).filter((adjustment) => policy && adjustment.validUntil >= policy.asOf && Boolean(adjustment.sourceId));
  const rejectedAdjustments = (input.adjustments ?? []).filter((adjustment) => !policy || adjustment.validUntil < policy.asOf || !adjustment.sourceId);
  if (rejectedAdjustments.length) exceptions.push({id: "expired-or-untraced-adjustment", severity: "high", message: "At least one proposed pricing adjustment is expired or lacks a source.", affectedProcedures: ["PR-03", "PR-04", "PR-05", "PR-08"]});

  let indicativePrice: IndicativePrice | null = null;
  if (target && policy && sampleSufficient) {
    const spreads = eligible.map((observation) => observation.normalizedSpreadBps);
    const shift = validAdjustments.reduce((sum, adjustment) => sum + adjustment.bps, 0);
    const baseMin = Math.min(...spreads);
    const baseMax = Math.max(...spreads);
    const width = baseMax - baseMin;
    if (width < policy.minBandWidthBps) exceptions.push({id: "band-too-narrow", severity: "critical", message: "The observed band is narrower than the governed communication floor.", affectedProcedures: ["PR-01", "PR-07", "PR-09"]});
    if (width > policy.maxBandWidthBps) exceptions.push({id: "band-too-wide", severity: "critical", message: "The observed dispersion is wider than the governed communication ceiling.", affectedProcedures: ["PR-01", "PR-02", "PR-07", "PR-09"]});
    if (!exceptions.some((exception) => exception.severity === "critical")) {
      const bps = {min: baseMin + shift, max: baseMax + shift};
      const cdi = new Decimal(target.cdi);
      const base: SpreadBand = {instrument: target.instrument, rating: target.rating, bps: {min: baseMin, max: baseMax}};
      const latest = [...eligible].sort((a, b) => b.observedOn.localeCompare(a.observedOn))[0]!.observedOn;
      const allIn = {min: cdi.plus(new Decimal(bps.min).div(10_000)).toFixed(6), max: cdi.plus(new Decimal(bps.max).div(10_000)).toFixed(6), cdi: cdi.toFixed(6)};
      indicativePrice = {
        instrument: target.instrument,
        rating: target.rating,
        bps,
        allIn,
        base,
        adjustments: validAdjustments.map(({id, bps: adjustmentBps, rationale}) => ({id, bps: adjustmentBps, rationale})),
        provenance: {kind: "observed", sample: eligible.length, windowMonths: Math.max(1, Math.ceil((Date.parse(`${policy.asOf}T00:00:00Z`) - Date.parse(`${eligible.sort((a, b) => a.observedOn.localeCompare(b.observedOn))[0]!.observedOn}T00:00:00Z`)) / 2_629_746_000))},
        sentence: {
          pt: `Referência indicativa de CDI ${fmt(bps.min, "pt")} a CDI ${fmt(bps.max, "pt")} ao ano, baseada em ${eligible.length} observações comparáveis de ${distinctSources} fontes, com dado mais recente em ${latest}. Sujeita à análise e à decisão dos investidores.`,
          en: `Indicative reference of CDI ${fmt(bps.min, "en")} to CDI ${fmt(bps.max, "en")} per year, based on ${eligible.length} comparable observations from ${distinctSources} sources, with the latest data from ${latest}. Subject to investor analysis and decision.`,
        },
      };
    }
  }

  const costComponents = (input.costs ?? []).map((component) => {
    if (!target || !policy || component.validUntil < policy.asOf || !input.weightedAverageLifeYears || new Decimal(input.weightedAverageLifeYears).lte(0)) return {...component, annualizedBps: null};
    const annual = new Decimal(component.annualAmount ?? 0).plus(new Decimal(component.oneTimeAmount ?? 0).div(input.weightedAverageLifeYears));
    return {...component, annualizedBps: Number(annual.div(target.amount).times(10_000).toDecimalPlaces(2).toFixed())};
  });
  const annualizedCostBps = costComponents.length && costComponents.every((component) => component.annualizedBps !== null)
    ? Number(costComponents.reduce((sum, component) => sum.plus(component.annualizedBps!), new Decimal(0)).toFixed(2))
    : null;
  if ((input.costs?.length ?? 0) > 0 && annualizedCostBps === null) missing.add("pricing.weighted_average_life_and_valid_cost_sources");
  const totalRate = indicativePrice && annualizedCostBps !== null
    ? {
        min: new Decimal(indicativePrice.allIn.min).plus(new Decimal(annualizedCostBps).div(10_000)).toFixed(6),
        max: new Decimal(indicativePrice.allIn.max).plus(new Decimal(annualizedCostBps).div(10_000)).toFixed(6),
      }
    : null;

  const result = (procedureId: `PR-${string}`, status: Status, value: Record<string, unknown> | null, procedureMissing: string[] = [], procedureExceptions: string[] = [], evidenceCount = 0): PricingProcedureResult => ({
    procedureId, status, result: value, outputCount: value ? Object.keys(value).length : 0, evidenceCount, missingInputs: procedureMissing, exceptionIds: procedureExceptions,
  });
  const exceptionIds = (id: `PR-${string}`) => exceptions.filter((exception) => exception.affectedProcedures.includes(id)).map((exception) => exception.id);
  const latestObservation = eligible.length ? [...eligible].sort((a, b) => b.observedOn.localeCompare(a.observedOn))[0]!.observedOn : null;
  const expectedGap = target?.expectedSpreadBps !== undefined && indicativePrice ? {
    expectation: target.expectedSpreadBps,
    supportedMin: indicativePrice.bps.min,
    supportedMax: indicativePrice.bps.max,
    gapToNearest: target.expectedSpreadBps < indicativePrice.bps.min ? indicativePrice.bps.min - target.expectedSpreadBps : target.expectedSpreadBps > indicativePrice.bps.max ? target.expectedSpreadBps - indicativePrice.bps.max : 0,
  } : null;
  const currentComparison = target?.currentAllIn && indicativePrice ? {
    current: target.currentAllIn,
    proposedMin: indicativePrice.allIn.min,
    proposedMax: indicativePrice.allIn.max,
    deltaMin: new Decimal(indicativePrice.allIn.min).minus(target.currentAllIn).toFixed(6),
    deltaMax: new Decimal(indicativePrice.allIn.max).minus(target.currentAllIn).toFixed(6),
  } : null;

  const coverage: PricingProcedureResult[] = [
    result("PR-01", indicativePrice ? "completed" : "blocked", indicativePrice ? {cell: `${target!.instrument}:${target!.rating}:${target!.tenorMonths}:${target!.securityClass}`, band: indicativePrice.bps, sample: eligible.length, latestObservation} : null, indicativePrice ? [] : ["reliable pricing cell"], exceptionIds("PR-01"), eligible.length),
