import Decimal from "decimal.js";
import {calculateAdjustedEbitda, calculateLeverage, applyCollateralHaircuts, type CalculationResult} from "@offroad/financial-core";

import {factValue, type ReconciledFact} from "./facts";
import type {RuleContext} from "./rules";

/**
 * The numbers the desk computes, each one showing its work.
 *
 * Every calculation here is arithmetic over reconciled facts, done by `financial-core` in
 * Decimal, and every one carries a trace: which inputs, from which fact, from which document.
 * That is the whole difference between a platform that says "leverage is 2.87x" and one that
 * can be asked *why* and answer with the two numbers and the two documents they came from.
 *
 * A calculation whose inputs are missing does not appear. It is never estimated, never carried
 * over from a neighbouring period, never defaulted to zero — the gap is reported instead, and
 * a missing metric with a named cause is more useful to a credit committee than a number
 * nobody can source.
 */

export type TracedCalculation = {
  id: string;
  labels: {pt: string; en: string};
  value: string;
  /** Inputs, in order, with where each came from. */
  trace: Array<{label: string; value: string; fieldPath?: string; sourceDocument?: string}>;
  /** Facts this calculation depends on — the audit trail from number to page. */
  inputs: string[];
  warnings: string[];
};

/** Missing inputs, so the caller can turn them into a question rather than a silent absence. */
export type CalculationGap = {
  id: string;
  labels: {pt: string; en: string};
  missing: string[];
};

export type CalculationSet = {
  calculations: TracedCalculation[];
  gaps: CalculationGap[];
};

type Sourced = {value: Decimal; fieldPath: string; sourceDocument?: string};

function sourced(context: RuleContext, fieldPath: string, periodEnd?: string): Sourced | null {
  const value = factValue(context.index, fieldPath, periodEnd);
  if (value === null) return null;
  const fact: ReconciledFact | undefined = context.index.get(periodEnd ? [fieldPath, periodEnd].join("|") : fieldPath);
  return {value, fieldPath, ...(fact?.accepted.sourceDocument ? {sourceDocument: fact.accepted.sourceDocument} : {})};
}

function traced(
  id: string,
  labels: {pt: string; en: string},
  result: CalculationResult,
  inputs: Sourced[],
): TracedCalculation {
  const byLabel = new Map(inputs.map((input, index) => [index, input]));
  return {
    id,
    labels,
    value: result.value,
    trace: result.trace.map((entry, index) => {
      const input = byLabel.get(index);
      return {
        label: entry.label,
        value: entry.value,
        ...(input?.fieldPath ? {fieldPath: input.fieldPath} : {}),
        ...(input?.sourceDocument ? {sourceDocument: input.sourceDocument} : {}),
      };
    }),
    inputs: inputs.map((input) => input.fieldPath),
    warnings: result.warnings,
  };
}

/**
 * Computes what can be computed, and names what cannot.
 *
 * The set is deliberately small and load-bearing: net debt, adjusted EBITDA, leverage before
 * and after the operation, collateral capacity after haircuts, and the sources/uses totals.
 * These are the numbers a credit committee asks for first, and the ones every downstream
 * document repeats.
 */
export function computeCalculations(context: RuleContext): CalculationSet {
  const calculations: TracedCalculation[] = [];
  const gaps: CalculationGap[] = [];
  // Projection dates can be years ahead of the balance sheet. They must never move the
  // calculation anchor forward and make today's cash, debt and LTM EBITDA disappear.
  const period = [...new Set(
    context.facts
      .filter((fact) => /^(historical|interim)_financials\./.test(fact.key.fieldPath))
      .map((fact) => fact.key.periodEnd)
      .filter((value): value is string => Boolean(value)),
  )].sort().reverse()[0] ?? context.periods[0];
  const year = period?.slice(0, 4) ?? "";

  const pick = (paths: string[]): Sourced | null => {
    for (const path of paths) {
      const found = sourced(context, path, period) ?? sourced(context, path);
      if (found) return found;
    }
    return null;
  };

  // ---- net debt -------------------------------------------------------------------------
  const grossDebt = pick(["debt.total_gross", `historical_financials.${year}.gross_debt`, `interim_financials.${year}_07.gross_debt`]);
  const cash = pick([`historical_financials.${year}.cash`, `interim_financials.${year}_07.cash`]);

  let netDebt: Sourced | null = null;
  if (grossDebt && cash) {
    const value = grossDebt.value.minus(cash.value);
    netDebt = {value, fieldPath: "calculated.net_debt"};
    calculations.push({
      id: "net_debt",
      labels: {pt: "Dívida líquida", en: "Net debt"},
      value: value.toDecimalPlaces(2).toFixed(),
      trace: [
        {label: "gross_debt", value: grossDebt.value.toFixed(), fieldPath: grossDebt.fieldPath, ...(grossDebt.sourceDocument ? {sourceDocument: grossDebt.sourceDocument} : {})},
        {label: "cash", value: cash.value.toFixed(), fieldPath: cash.fieldPath, ...(cash.sourceDocument ? {sourceDocument: cash.sourceDocument} : {})},
      ],
      inputs: [grossDebt.fieldPath, cash.fieldPath],
      warnings: [],
    });
  } else {
    gaps.push({
      id: "net_debt",
      labels: {pt: "Dívida líquida", en: "Net debt"},
      missing: [!grossDebt ? "dívida bruta" : "", !cash ? "caixa e equivalentes" : ""].filter(Boolean),
    });
  }

  // ---- adjusted EBITDA ------------------------------------------------------------------
  const ebitda = pick([`historical_financials.${year}.ebitda`, `interim_financials.${year}_07.ebitda_ltm`, `interim_financials.${year}_07.ebitda`]);
  let adjustedEbitda: Sourced | null = null;
  if (ebitda) {
    // Add-backs are only included once a human approved them (R10); none are assumed here.
    const result = calculateAdjustedEbitda(ebitda.value, []);
    adjustedEbitda = {value: new Decimal(result.value), fieldPath: "calculated.adjusted_ebitda"};
    calculations.push(
      traced("adjusted_ebitda", {pt: "EBITDA ajustado", en: "Adjusted EBITDA"}, result, [ebitda, ebitda]),
    );
  } else {
    gaps.push({id: "adjusted_ebitda", labels: {pt: "EBITDA ajustado", en: "Adjusted EBITDA"}, missing: ["EBITDA do período"]});
  }

  // ---- leverage, before and after -------------------------------------------------------
  if (netDebt && adjustedEbitda && adjustedEbitda.value.gt(0)) {
    const result = calculateLeverage(netDebt.value, adjustedEbitda.value);
    calculations.push(
      traced("leverage_pre_transaction", {pt: "Alavancagem pré-operação", en: "Leverage before the transaction"}, result, [netDebt, adjustedEbitda]),
    );

    const requested = pick(["transaction.requested_amount"]);
    if (requested) {
      const refinancing = pick(["transaction.refinancing"]);
      const companyCash = pick(["project.company_cash"]);
      const projectedEbitda = pick([`projections.${year}.ebitda`]);
      const postGross = (grossDebt?.value ?? new Decimal(0))
        .plus(requested.value)
        .minus(refinancing?.value ?? new Decimal(0));
      calculations.push({
        id: "gross_debt_post_transaction",
        labels: {pt: "Dívida bruta pós-operação", en: "Gross debt after the transaction"},
        value: postGross.toDecimalPlaces(2).toFixed(),
        trace: [
          {label: "gross_debt", value: (grossDebt?.value ?? new Decimal(0)).toFixed(), ...(grossDebt?.fieldPath ? {fieldPath: grossDebt.fieldPath} : {})},
          {label: "requested_amount", value: requested.value.toFixed(), fieldPath: requested.fieldPath},
          ...(refinancing ? [{label: "refinancing_repaid", value: refinancing.value.negated().toFixed(), fieldPath: refinancing.fieldPath}] : []),
        ],
        inputs: [grossDebt?.fieldPath ?? "", requested.fieldPath, refinancing?.fieldPath ?? ""].filter(Boolean),
        warnings: [],
      });

      const postCash = (cash?.value ?? new Decimal(0)).minus(companyCash?.value ?? new Decimal(0));
      const leverageEbitda = projectedEbitda ?? adjustedEbitda;
      const postNet = postGross.minus(postCash);
      const postResult = calculateLeverage(postNet, leverageEbitda.value);
      calculations.push({
        id: "leverage_post_transaction",
        labels: {pt: "Alavancagem pós-operação", en: "Leverage after the transaction"},
        value: postResult.value,
        trace: [
          {label: "gross_debt_post_transaction", value: postGross.toFixed(), fieldPath: "calculated.gross_debt_post_transaction"},
          {label: "cash_before_transaction", value: (cash?.value ?? new Decimal(0)).toFixed(), ...(cash?.fieldPath ? {fieldPath: cash.fieldPath} : {})},
          ...(companyCash ? [{label: "company_cash_used", value: companyCash.value.toFixed(), fieldPath: companyCash.fieldPath}] : []),
          {label: projectedEbitda ? "projected_ebitda_at_closing" : "current_adjusted_ebitda", value: leverageEbitda.value.toFixed(), fieldPath: leverageEbitda.fieldPath},
        ],
        inputs: [grossDebt?.fieldPath ?? "", requested.fieldPath, refinancing?.fieldPath ?? "", cash?.fieldPath ?? "", companyCash?.fieldPath ?? "", leverageEbitda.fieldPath].filter(Boolean),
        warnings: [
          ...postResult.warnings,
          ...(projectedEbitda
            ? ["usa o EBITDA projetado para o ano do fechamento, identificado como premissa da administração"]
            : ["na ausência de EBITDA para o fechamento, mantém o EBITDA ajustado atual"]),
        ],
      });
    }
  } else if (!gaps.some((gap) => gap.id === "net_debt" || gap.id === "adjusted_ebitda")) {
    gaps.push({id: "leverage", labels: {pt: "Alavancagem", en: "Leverage"}, missing: ["EBITDA positivo"]});
  }

  // ---- collateral capacity --------------------------------------------------------------
  const collateralItems = context.facts
    .filter((fact) => /^collateral\.assets\.\d+\.eligible_base$/.test(fact.key.fieldPath) && fact.valueType === "number")
    .map((fact) => {
      const index = fact.key.fieldPath.split(".")[2];
      const haircut = factValue(context.index, `collateral.assets.${index}.policy_haircut`);
      const description = context.index.get(`collateral.assets.${index}.description`);
      return {
        name: description?.value ?? `ativo ${index}`,
        grossValue: fact.value,
        haircutRate: haircut ? haircut.toFixed() : "0",
        fieldPath: fact.key.fieldPath,
        sourceDocument: fact.accepted.sourceDocument,
      };
    });

  const collateralCapacityComponents = [
    "collateral.receivables_capacity",
    "collateral.inventory_capacity",
    "collateral.property_equipment_capacity",
  ]
    .map((fieldPath) => sourced(context, fieldPath, period) ?? sourced(context, fieldPath))
    .filter((item): item is Sourced => item !== null);

  if (collateralItems.length > 0) {
    const result = applyCollateralHaircuts(collateralItems);
    calculations.push({
      id: "collateral_capacity_total",
      labels: {pt: "Capacidade de garantias após haircut", en: "Collateral capacity after haircuts"},
      value: result.value,
      trace: result.trace.map((entry, index) => ({
        label: entry.label,
        value: entry.value,
        ...(collateralItems[index]?.fieldPath ? {fieldPath: collateralItems[index]!.fieldPath} : {}),
        ...(collateralItems[index]?.sourceDocument ? {sourceDocument: collateralItems[index]!.sourceDocument} : {}),
      })),
      inputs: collateralItems.map((item) => item.fieldPath),
      warnings: result.warnings,
    });
  } else if (collateralCapacityComponents.length > 0) {
    const total = collateralCapacityComponents.reduce((sum, item) => sum.plus(item.value), new Decimal(0));
    calculations.push({
      id: "collateral_capacity_total",
      labels: {pt: "Capacidade de garantias após haircut", en: "Collateral capacity after haircuts"},
      value: total.toDecimalPlaces(2).toFixed(),
      trace: collateralCapacityComponents.map((item) => ({
        label: item.fieldPath,
        value: item.value.toFixed(),
        fieldPath: item.fieldPath,
        ...(item.sourceDocument ? {sourceDocument: item.sourceDocument} : {}),
      })),
      inputs: collateralCapacityComponents.map((item) => item.fieldPath),
      warnings: [],
    });
  } else {
    gaps.push({
      id: "collateral_capacity_total",
      labels: {pt: "Capacidade de garantias", en: "Collateral capacity"},
      missing: ["base elegível e haircut por ativo"],
    });
  }

  // ---- stabilized project add-on --------------------------------------------------------
  const investmentIndexes = [...new Set(
    context.facts
      .map((fact) => fact.key.fieldPath.match(/^project\.investments\.(\d+)\.stabilized_revenue$/)?.[1])
      .filter((index): index is string => Boolean(index)),
  )].sort((a, b) => Number(a) - Number(b));
  if (investmentIndexes.length > 0) {
    const revenues = investmentIndexes
      .map((index) => sourced(context, `project.investments.${index}.stabilized_revenue`))
      .filter((item): item is Sourced => item !== null);
    const margins = investmentIndexes
      .map((index) => sourced(context, `project.investments.${index}.stabilized_ebitda_margin`))
      .filter((item): item is Sourced => item !== null);
    if (revenues.length === investmentIndexes.length) {
      const totalRevenue = revenues.reduce((sum, item) => sum.plus(item.value), new Decimal(0));
      calculations.push({
        id: "addon_stabilized_revenue",
        labels: {pt: "Receita estabilizada incremental", en: "Stabilized incremental revenue"},
        value: totalRevenue.toDecimalPlaces(2).toFixed(),
        trace: revenues.map((item) => ({label: item.fieldPath, value: item.value.toFixed(), fieldPath: item.fieldPath, ...(item.sourceDocument ? {sourceDocument: item.sourceDocument} : {})})),
        inputs: revenues.map((item) => item.fieldPath),
        warnings: ["run-rate estabilizado do projeto, não receita do primeiro ano"],
      });
    }
    if (revenues.length === investmentIndexes.length && margins.length === investmentIndexes.length) {
      const totalEbitda = investmentIndexes.reduce((sum, _index, position) =>
        sum.plus(revenues[position]!.value.times(margins[position]!.value)), new Decimal(0));
      calculations.push({
        id: "addon_stabilized_ebitda",
        labels: {pt: "EBITDA estabilizado incremental", en: "Stabilized incremental EBITDA"},
        value: totalEbitda.toDecimalPlaces(2).toFixed(),
        trace: investmentIndexes.flatMap((_index, position) => [
          {label: revenues[position]!.fieldPath, value: revenues[position]!.value.toFixed(), fieldPath: revenues[position]!.fieldPath, ...(revenues[position]!.sourceDocument ? {sourceDocument: revenues[position]!.sourceDocument} : {})},
          {label: margins[position]!.fieldPath, value: margins[position]!.value.toFixed(), fieldPath: margins[position]!.fieldPath, ...(margins[position]!.sourceDocument ? {sourceDocument: margins[position]!.sourceDocument} : {})},
        ]),
        inputs: investmentIndexes.flatMap((_index, position) => [revenues[position]!.fieldPath, margins[position]!.fieldPath]),
        warnings: ["receita estabilizada multiplicada pela margem EBITDA estabilizada de cada unidade"],
      });
    } else if (revenues.length > 0) {
      gaps.push({
        id: "addon_stabilized_ebitda",
        labels: {pt: "EBITDA estabilizado incremental", en: "Stabilized incremental EBITDA"},
        missing: ["margem EBITDA estabilizada de cada unidade"],
      });
    }
  }

  // ---- sources and uses -----------------------------------------------------------------
  for (const [side, id, labels] of [
    ["sources", "sources_total", {pt: "Total das fontes", en: "Total sources"}],
    ["uses", "uses_total", {pt: "Total dos usos", en: "Total uses"}],
  ] as const) {
    const entries = context.facts.filter(
      (fact) => /^transaction\.sources_and_uses\.\d+\.side$/.test(fact.key.fieldPath) && fact.value === side,
    );
    if (entries.length === 0) continue;

    const amounts = entries
      .map((fact) => context.index.get(fact.key.fieldPath.replace(/\.side$/, ".amount")))
      .filter((fact): fact is ReconciledFact => Boolean(fact) && fact!.valueType === "number");
    if (amounts.length === 0) continue;

    const total = amounts.reduce((sum, fact) => sum.plus(new Decimal(fact.value)), new Decimal(0));
    calculations.push({
      id,
      labels,
      value: total.toDecimalPlaces(2).toFixed(),
      trace: amounts.map((fact) => ({
        label: fact.key.fieldPath,
        value: fact.value,
        fieldPath: fact.key.fieldPath,
        ...(fact.accepted.sourceDocument ? {sourceDocument: fact.accepted.sourceDocument} : {}),
      })),
      inputs: amounts.map((fact) => fact.key.fieldPath),
      warnings: [],
    });
  }

  return {calculations, gaps};
}

packages/reconciliation/src/financial-tr.content:
import {
  calculateConcentration,
  calculateCurrencyExposure,
  calculateCashConversion,
  calculateCfads,
  calculateMargin,
  calculateSeasonality,
  calculateWorkingCapital,
  calculateWorkingCapitalInvestment,
  checkIdentity,
} from "@offroad/financial-core";
import Decimal from "decimal.js";
import {z} from "zod";

import type {ReconciledFact} from "./facts";

const decimalString = z.string().regex(/^-?\d+(?:\.\d+)?$/);
const evidenceLinkSchema = z.object({
  fieldPath: z.string().min(1),
  sourceDocument: z.string().min(1),
  anchor: z.unknown().optional(),
}).strict();

export const accountingLineSchema = z.object({
  metric: z.string().min(1),
  value: decimalString,
  evidence: evidenceLinkSchema,
  informationClass: z.string().min(1),
  disputed: z.boolean(),
}).strict();
export type AccountingLine = z.infer<typeof accountingLineSchema>;

export const normalizationAdjustmentSchema = z.object({
  id: z.string().min(1),
  description: z.string().min(1),
  amount: decimalString,
  decision: z.enum(["accepted", "rejected", "case_by_case"]),
  rationale: z.string().min(1),
  evidence: z.array(evidenceLinkSchema).min(1),
}).strict();
export type NormalizationAdjustment = z.infer<typeof normalizationAdjustmentSchema>;

export const financialStatementViewSchema = z.object({
  id: z.string().min(1),
  period: z.string().min(4),
  periodEnd: z.string().nullable(),
  basis: z.enum(["historical", "interim", "projected"]),
  entity: z.string().nullable(),
  scope: z.string().nullable(),
  lines: z.array(accountingLineSchema),
  reportedEbitda: decimalString.nullable(),
  adjustedEbitda: decimalString.nullable(),
  ebitdaMargin: decimalString.nullable(),
  workingCapital: decimalString.nullable(),
  cfads: decimalString.nullable(),
  cashConversion: decimalString.nullable(),
  adjustments: z.array(normalizationAdjustmentSchema),
}).strict();
export type FinancialStatementView = z.infer<typeof financialStatementViewSchema>;

export const cashConversionBridgeSchema = z.object({
  statementId: z.string().min(1),
  lines: z.array(z.object({id: z.string(), value: decimalString, operation: z.enum(["start", "add", "subtract"])}).strict()),
  cfads: decimalString,
  conversion: decimalString,
  evidence: z.array(evidenceLinkSchema),
}).strict();
export type CashConversionBridge = z.infer<typeof cashConversionBridgeSchema>;

export const workingCapitalBridgeSchema = z.object({
  fromStatementId: z.string().min(1),
  toStatementId: z.string().min(1),
  priorWorkingCapital: decimalString,
  currentWorkingCapital: decimalString,
  investment: decimalString,
  evidence: z.array(evidenceLinkSchema),
}).strict();
export type WorkingCapitalBridge = z.infer<typeof workingCapitalBridgeSchema>;

export const maintenanceCapexBridgeSchema = z.object({
  statementId: z.string().min(1),
  totalCapex: decimalString.nullable(),
  maintenanceCapex: decimalString.nullable(),
  growthCapex: decimalString.nullable(),
  method: z.enum(["reported_split", "company_supported_estimate", "not_computable"]),
  evidence: z.array(evidenceLinkSchema),
}).strict();
export type MaintenanceCapexBridge = z.infer<typeof maintenanceCapexBridgeSchema>;

export const financialIdentityCheckSchema = z.object({
  id: z.string().min(1),
  statementId: z.string().min(1),
  left: decimalString,
  right: decimalString,
  difference: decimalString,
  tolerance: decimalString,
  status: z.enum(["pass", "fail"]),
  evidence: z.array(evidenceLinkSchema),
}).strict();
export type FinancialIdentityCheck = z.infer<typeof financialIdentityCheckSchema>;

export const reconciliationExceptionSchema = z.object({
  id: z.string().min(1),
  severity: z.enum(["low", "medium", "high", "critical"]),
  status: z.enum(["open", "resolved"]),
  message: z.object({pt: z.string().min(1), en: z.string().min(1)}).strict(),
  affectedFields: z.array(z.string().min(1)),
  evidence: z.array(evidenceLinkSchema),
  blocksExternalOutputs: z.boolean(),
}).strict();
export type FinancialTruthException = z.infer<typeof reconciliationExceptionSchema>;

export const projectedStatementSetSchema = z.object({
  base: z.array(z.string()),
  downside: z.array(z.string()),
  missingDownside: z.boolean(),
}).strict();
export type ProjectedStatementSet = z.infer<typeof projectedStatementSetSchema>;

export const financialTruthSetSchema = z.object({
  version: z.string().min(1),
  status: z.enum(["complete", "partial", "blocked"]),
  statements: z.array(financialStatementViewSchema),
  cashConversionBridges: z.array(cashConversionBridgeSchema),
  workingCapitalBridges: z.array(workingCapitalBridgeSchema),
  maintenanceCapexBridges: z.array(maintenanceCapexBridgeSchema),
  projectedStatements: projectedStatementSetSchema,
  identityChecks: z.array(financialIdentityCheckSchema),
  exceptions: z.array(reconciliationExceptionSchema),
  missingInputs: z.array(z.string()),
  analytics: z.object({
    customerConcentration: z.object({top1: decimalString, top5: decimalString, top10: decimalString}).strict().nullable(),
    revenueSeasonality: z.object({average: decimalString, peak: decimalString, trough: decimalString, amplitude: decimalString, indices: z.array(decimalString)}).strict().nullable(),
    workingCapitalSeasonality: z.object({average: decimalString, peak: decimalString, trough: decimalString, amplitude: decimalString, indices: z.array(decimalString)}).strict().nullable(),
    currencyExposure: z.array(z.object({currency: z.string(), revenue: decimalString, cost: decimalString, debtService: decimalString, hedge: decimalString, exposure: decimalString, evidence: z.array(evidenceLinkSchema)}).strict()),
    receivablesAging: z.array(z.object({bucket: z.string(), amount: decimalString, evidence: z.array(evidenceLinkSchema)}).strict()),
    inventoryAging: z.array(z.object({bucket: z.string(), amount: decimalString, evidence: z.array(evidenceLinkSchema)}).strict()),
  }).strict(),
  procedureCoverage: z.array(z.object({
    procedureId: z.string().regex(/^Q-\d{2}$/),
    status: z.enum(["completed", "partial", "blocked", "not_computable"]),
    outputCount: z.number().int().nonnegative(),
    evidenceCount: z.number().int().nonnegative(),
    missingInputs: z.array(z.string()),
    exceptionIds: z.array(z.string()),
  }).strict()).length(18),
}).strict();
export type FinancialTruthSet = z.infer<typeof financialTruthSetSchema>;

const source = (fact: ReconciledFact) => ({
  fieldPath: fact.key.fieldPath,
  sourceDocument: fact.accepted.sourceDocument,
  ...(fact.accepted.anchor !== undefined ? {anchor: fact.accepted.anchor} : {}),
});

const numeric = (facts: readonly ReconciledFact[], path: string) =>
  facts.find((fact) => fact.key.fieldPath === path && fact.valueType === "number");

const pathParts = (path: string) => /^(historical_financials|interim_financials|projections)\.(\d{4}(?:_\d{2})?)\.(.+)$/.exec(path);

function indexedRows(facts: readonly ReconciledFact[], prefix: string) {
  const indexes = [...new Set(facts.map((fact) => fact.key.fieldPath.match(new RegExp(`^${prefix.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\.(\\d+)\\.`))?.[1]).filter(Boolean))] as string[];
  return indexes.map((index) => ({
    index,
    facts: facts.filter((fact) => fact.key.fieldPath.startsWith(`${prefix}.${index}.`)),
  }));
}

function adjustmentRows(facts: readonly ReconciledFact[], prefix: string): NormalizationAdjustment[] {
  const indexes = [...new Set(facts.map((fact) => fact.key.fieldPath.match(new RegExp(`^${prefix.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\.normalization_adjustments\\.(\\d+)\\.`))?.[1]).filter(Boolean))] as string[];
  return indexes.flatMap((index) => {
    const base = `${prefix}.normalization_adjustments.${index}`;
    const description = facts.find((fact) => fact.key.fieldPath === `${base}.description`);
    const amount = numeric(facts, `${base}.amount`);
    const decision = facts.find((fact) => fact.key.fieldPath === `${base}.decision`);
    const rationale = facts.find((fact) => fact.key.fieldPath === `${base}.rationale`);
    if (!description || !amount || !decision || !["accepted", "rejected", "case_by_case"].includes(decision.value)) return [];
    return [{
      id: `${prefix}:${index}`,
      description: description.value,
      amount: amount.value,
      decision: decision.value as NormalizationAdjustment["decision"],
      rationale: rationale?.value ?? "Rationale not supplied",
      evidence: [source(description), source(amount), source(decision)],
    }];
  });
}

export function buildFinancialTruthSet(facts: readonly ReconciledFact[]): FinancialTruthSet {
  const grouped = new Map<string, ReconciledFact[]>();
  for (const fact of facts) {
    const match = pathParts(fact.key.fieldPath);
    if (!match || fact.valueType !== "number") continue;
    const key = `${match[1]}.${match[2]}`;
    grouped.set(key, [...(grouped.get(key) ?? []), fact]);
  }

  const statements: FinancialStatementView[] = [];
  const cashConversionBridges: CashConversionBridge[] = [];
  const maintenanceCapexBridges: MaintenanceCapexBridge[] = [];
  const identityChecks: FinancialIdentityCheck[] = [];
  const exceptions: FinancialTruthException[] = [];
  const missing = new Set<string>();

  for (const [id, statementFacts] of [...grouped.entries()].sort(([a], [b]) => a.localeCompare(b))) {
    const [group, period] = id.split(".") as ["historical_financials" | "interim_financials" | "projections", string];
    const metric = (name: string) => numeric(statementFacts, `${group}.${period}.${name}`);
    const reportedEbitda = metric("ebitda");
    const adjustments = adjustmentRows(facts, `${group}.${period}`);
    const accepted = adjustments.filter((item) => item.decision === "accepted").reduce((sum, item) => sum.plus(item.amount), new Decimal(0));
    const adjustedEbitda = reportedEbitda ? new Decimal(reportedEbitda.value).plus(accepted).toFixed() : null;
    const revenue = metric("revenue");
    const receivables = metric("receivables");
    const inventory = metric("inventory");
    const payables = metric("payables");
    const workingCapital = receivables && inventory && payables
      ? calculateWorkingCapital({receivables: receivables.value, inventory: inventory.value, payables: payables.value})
      : null;
    const totalCapex = metric("capex");
    const maintenanceCapex = metric("maintenance_capex");
    const growthCapex = metric("growth_capex");
    const cashTaxes = metric("cash_taxes");
    const fixedCharges = metric("fixed_charges");
    const approvedCashAdjustments = metric("approved_cash_adjustments");
    const periodEnd = statementFacts.map((fact) => fact.key.periodEnd).filter(Boolean).sort().at(-1) ?? null;
    const statementId = `${group}.${period}`;
    const lines = statementFacts
      .filter((fact) => !fact.key.fieldPath.includes(".normalization_adjustments."))
      .map((fact) => ({
        metric: fact.key.fieldPath.slice(`${group}.${period}.`.length), value: fact.value,
        evidence: source(fact), informationClass: fact.accepted.informationClass, disputed: fact.disputed,
      }));
    let cfads: string | null = null;
    let cashConversion: string | null = null;
    if (adjustedEbitda && cashTaxes && maintenanceCapex && fixedCharges) {
      const priorWcInvestment = metric("working_capital_investment");
      if (priorWcInvestment) {
        const bridge = calculateCfads({
          adjustedEbitda, cashTaxes: cashTaxes.value, maintenanceCapex: maintenanceCapex.value,
          workingCapitalInvestment: priorWcInvestment.value, fixedCharges: fixedCharges.value,
          approvedCashAdjustments: approvedCashAdjustments?.value ?? "0",
        });
        cfads = bridge.value;
        cashConversion = new Decimal(adjustedEbitda).isZero() ? null : calculateCashConversion(cfads, adjustedEbitda);
        cashConversionBridges.push({
          statementId, lines: bridge.lines, cfads,
          conversion: cashConversion ?? "0",
          evidence: [reportedEbitda, cashTaxes, maintenanceCapex, priorWcInvestment, fixedCharges, approvedCashAdjustments].filter((item): item is ReconciledFact => Boolean(item)).map(source),
        });
      } else missing.add(`${statementId}.working_capital_investment`);
    } else {
      if (!cashTaxes) missing.add(`${statementId}.cash_taxes`);
      if (!maintenanceCapex) missing.add(`${statementId}.maintenance_capex`);
      if (!fixedCharges) missing.add(`${statementId}.fixed_charges`);
    }

    maintenanceCapexBridges.push({
      statementId,
      totalCapex: totalCapex?.value ?? null,
      maintenanceCapex: maintenanceCapex?.value ?? null,
      growthCapex: growthCapex?.value ?? null,
      method: maintenanceCapex && growthCapex ? "reported_split" : maintenanceCapex ? "company_supported_estimate" : "not_computable",
      evidence: [totalCapex, maintenanceCapex, growthCapex].filter((item): item is ReconciledFact => Boolean(item)).map(source),
    });

    const totalAssets = metric("total_assets");
    const liabilitiesEquity = metric("total_liabilities_equity");
    if (totalAssets && liabilitiesEquity) {
      const checked = checkIdentity({id: "balance_sheet", left: totalAssets.value, right: liabilitiesEquity.value});
      identityChecks.push({...checked, statementId, evidence: [source(totalAssets), source(liabilitiesEquity)]});
    }
    const openingCash = metric("opening_cash");
    const netChange = metric("net_change_in_cash");
    const closingCash = metric("closing_cash") ?? metric("cash");
    if (openingCash && netChange && closingCash) {
      const checked = checkIdentity({id: "cash_flow", left: new Decimal(openingCash.value).plus(netChange.value), right: closingCash.value});
      identityChecks.push({...checked, statementId, evidence: [source(openingCash), source(netChange), source(closingCash)]});
    }
    statements.push({
      id: statementId, period, periodEnd,
      basis: group === "historical_financials" ? "historical" : group === "interim_financials" ? "interim" : "projected",
      entity: statementFacts[0]?.key.entityName ?? null,
      scope: statementFacts[0]?.accepted.entityScope ?? null,
      lines, reportedEbitda: reportedEbitda?.value ?? null, adjustedEbitda,
      ebitdaMargin: adjustedEbitda && revenue && !new Decimal(revenue.value).isZero() ? calculateMargin(adjustedEbitda, revenue.value) : null,
      workingCapital, cfads, cashConversion, adjustments,
    });
  }

  const workingCapitalBridges: WorkingCapitalBridge[] = [];
  const actual = statements.filter((statement) => statement.basis !== "projected" && statement.workingCapital !== null).sort((a, b) => (a.periodEnd ?? a.period).localeCompare(b.periodEnd ?? b.period));
  for (let index = 1; index < actual.length; index += 1) {
    const prior = actual[index - 1]!;
    const current = actual[index]!;
    const evidence = [...grouped.get(prior.id) ?? [], ...grouped.get(current.id) ?? []]
      .filter((fact) => /\.(receivables|inventory|payables)$/.test(fact.key.fieldPath)).map(source);
    workingCapitalBridges.push({
      fromStatementId: prior.id, toStatementId: current.id,
      priorWorkingCapital: prior.workingCapital!, currentWorkingCapital: current.workingCapital!,
      investment: calculateWorkingCapitalInvestment(current.workingCapital!, prior.workingCapital!), evidence,
    });
  }

  for (const check of identityChecks.filter((item) => item.status === "fail")) {
    exceptions.push({
      id: `identity:${check.statementId}:${check.id}`, severity: "critical", status: "open",
      message: {pt: `A identidade ${check.id} não fecha em ${check.statementId}.`, en: `The ${check.id} identity does not tie in ${check.statementId}.`},
      affectedFields: check.evidence.map((item) => item.fieldPath), evidence: check.evidence, blocksExternalOutputs: true,
    });
  }
  for (const statement of statements) {
    const disputed = statement.lines.filter((line) => line.disputed);
    if (disputed.length > 0) exceptions.push({
      id: `disputed:${statement.id}`, severity: "high", status: "open",
      message: {pt: `Há números materiais em conflito em ${statement.id}.`, en: `Material figures conflict in ${statement.id}.`},
      affectedFields: disputed.map((line) => line.evidence.fieldPath), evidence: disputed.map((line) => line.evidence), blocksExternalOutputs: true,
    });
  }
  const projected = statements.filter((statement) => statement.basis === "projected");
  const scenarioName = facts.find((fact) => fact.key.fieldPath === "projections.scenario_name")?.value ?? "";
  const scenarioRows = indexedRows(facts, "projections.scenario");
  const downsidePeriods = new Set(scenarioRows.filter(({facts: row}) => /downside|stress|advers/i.test(row.find((fact) => fact.key.fieldPath.endsWith(".name"))?.value ?? ""))
    .map(({facts: row}) => row.find((fact) => fact.key.fieldPath.endsWith(".period"))?.value).filter(Boolean));
  const downside = projected.filter((statement) => /downside|stress/i.test(statement.id) || /downside|stress/i.test(scenarioName) || downsidePeriods.has(statement.period));

  const customerShares = indexedRows(facts, "customers.top_customers").flatMap(({facts: row}) => {
    const share = row.find((fact) => fact.key.fieldPath.endsWith(".share_pct") && fact.valueType === "number");
    return share ? [share] : [];
  });
  const monthlyRows = indexedRows(facts, "historical_financials.monthly")
    .map(({facts: row}) => ({
      month: row.find((fact) => fact.key.fieldPath.endsWith(".month"))?.value ?? "",
      revenue: row.find((fact) => fact.key.fieldPath.endsWith(".revenue") && fact.valueType === "number"),
      workingCapital: row.find((fact) => fact.key.fieldPath.endsWith(".working_capital") && fact.valueType === "number"),
    })).sort((a, b) => a.month.localeCompare(b.month));
  const currencyExposure = indexedRows(facts, "historical_financials.currency_mix").flatMap(({facts: row}) => {
    const find = (suffix: string) => row.find((fact) => fact.key.fieldPath.endsWith(`.${suffix}`));
    const currency = find("currency");
    const revenue = find("revenue");
    const cost = find("cost");
    const debtService = find("debt_service");
    if (!currency || !revenue || !cost || !debtService) return [];
    const hedge = find("hedge");
    return [{
      currency: currency.value, revenue: revenue.value, cost: cost.value, debtService: debtService.value,
      hedge: hedge?.value ?? "0",
      exposure: calculateCurrencyExposure({currency: currency.value, revenue: revenue.value, cost: cost.value, debtService: debtService.value, hedge: hedge?.value ?? 0}).exposure,
      evidence: row.map(source),
    }];
  });
  const aging = (prefix: string) => indexedRows(facts, prefix).flatMap(({facts: row}) => {
    const bucket = row.find((fact) => fact.key.fieldPath.endsWith(".bucket"));
    const amount = row.find((fact) => fact.key.fieldPath.endsWith(".amount") && fact.valueType === "number");
    return bucket && amount ? [{bucket: bucket.value, amount: amount.value, evidence: row.map(source)}] : [];
  });
  const analytics = {
    customerConcentration: customerShares.length > 0 ? calculateConcentration(customerShares.map((fact) => fact.value)) : null,
    revenueSeasonality: calculateSeasonality(monthlyRows.flatMap((row) => row.revenue ? [row.revenue.value] : [])),
    workingCapitalSeasonality: calculateSeasonality(monthlyRows.flatMap((row) => row.workingCapital ? [row.workingCapital.value] : [])),
    currencyExposure,
    receivablesAging: aging("historical_financials.receivables_aging"),
    inventoryAging: aging("historical_financials.inventory_aging"),
  };
  const coverageInputs: Array<{id: string; outputCount: number; missing: string[]}> = [
    {id: "Q-01", outputCount: statements.reduce((sum, item) => sum + item.adjustments.length, 0), missing: statements.some((item) => item.reportedEbitda !== null) ? [] : ["EBITDA reportado e ajustes item a item"]},
    {id: "Q-02", outputCount: cashConversionBridges.length, missing: cashConversionBridges.length ? [] : ["impostos caixa, capex de manutenção, NCG e encargos fixos"]},
    {id: "Q-03", outputCount: maintenanceCapexBridges.filter((item) => item.method !== "not_computable").length, missing: maintenanceCapexBridges.some((item) => item.method !== "not_computable") ? [] : ["registro de capex classificado por finalidade"]},
    {id: "Q-04", outputCount: workingCapitalBridges.length + (analytics.workingCapitalSeasonality ? 1 : 0), missing: workingCapitalBridges.length || analytics.workingCapitalSeasonality ? [] : ["série comparável de clientes, estoques e fornecedores"]},
    {id: "Q-05", outputCount: 0, missing: ["política de reconhecimento, cut-off e devoluções"]},
    {id: "Q-06", outputCount: analytics.customerConcentration ? 1 : 0, missing: analytics.customerConcentration ? [] : ["faturamento por grupo econômico de cliente"]},
    {id: "Q-07", outputCount: 0, missing: ["transações e CNPJs de partes relacionadas"]},
    {id: "Q-08", outputCount: facts.some((fact) => fact.key.fieldPath.startsWith("company.auditor.")) ? 1 : 0, missing: facts.some((fact) => fact.key.fieldPath.startsWith("company.auditor.")) ? [] : ["relatórios do auditor por exercício"]},
    {id: "Q-09", outputCount: statements.filter((item) => item.lines.some((line) => line.disputed)).length, missing: statements.some((item) => item.lines.some((line) => line.disputed)) ? [] : ["auditado e balancete do mesmo período e perímetro"]},
    {id: "Q-10", outputCount: projected.length, missing: projected.length ? [] : ["projeções, premissas e drivers"]},
    {id: "Q-11", outputCount: analytics.revenueSeasonality ? 1 : 0, missing: analytics.revenueSeasonality ? [] : ["24 meses de receita e NCG"]},
    {id: "Q-12", outputCount: analytics.currencyExposure.length, missing: analytics.currencyExposure.length ? [] : ["receita, custos, serviço e hedge por moeda"]},
    {id: "Q-13", outputCount: analytics.inventoryAging.length, missing: analytics.inventoryAging.length ? [] : ["estoque por idade, provisão e perdas"]},
    {id: "Q-14", outputCount: analytics.receivablesAging.length, missing: analytics.receivablesAging.length ? [] : ["aging, PDD, perdas e renegociados"]},
    {id: "Q-15", outputCount: 0, missing: ["desembolsos trabalhistas, provisão e estoque de processos"]},
    {id: "Q-16", outputCount: 0, missing: ["receita e EBITDA por unidade ou segmento"]},
    {id: "Q-17", outputCount: identityChecks.length, missing: identityChecks.length ? [] : ["demonstrações suficientes para identidades"]},
    {id: "Q-18", outputCount: statements.length, missing: statements.length ? [] : ["base financeira material"]},
  ];
  const procedureCoverage = coverageInputs.map((procedure) => {
    const relatedExceptions = exceptions.filter((exception) => procedure.id === "Q-17" ? exception.id.startsWith("identity:") : exception.affectedFields.some((field) => statements.some((statement) => field.startsWith(`${statement.id}.`))));
    return {
      procedureId: procedure.id,
      status: relatedExceptions.some((item) => item.blocksExternalOutputs) ? "blocked" as const : procedure.outputCount > 0 && procedure.missing.length === 0 ? "completed" as const : procedure.outputCount > 0 ? "partial" as const : "not_computable" as const,
      outputCount: procedure.outputCount,
      evidenceCount: procedure.id === "Q-06" ? customerShares.length : statements.reduce((sum, item) => sum + item.lines.length, 0),
      missingInputs: procedure.missing,
      exceptionIds: relatedExceptions.map((item) => item.id),
    };
  });
  const status = exceptions.some((item) => item.blocksExternalOutputs)
    ? "blocked"
    : missing.size > 0 || procedureCoverage.some((item) => item.status !== "completed") ? "partial" : "complete";
  return financialTruthSetSchema.parse({
    version: "2026.08.25-v1", status, statements, cashConversionBridges, workingCapitalBridges,
    maintenanceCapexBridges, projectedStatements: {base: projected.filter((statement) => !downside.includes(statement)).map((statement) => statement.id), downside: downside.map((statement) => statement.id), missingDownside: projected.length > 0 && downside.length === 0},
    identityChecks, exceptions, missingInputs: [...missing].sort(), analytics, procedureCoverage,
  });
}

packages/reconciliation/src/gaps.ts.content:
import {
  archetype,
  assessSufficiency,
  materialFieldRequirements,
  requirementIsSatisfied,
  type ArchetypeId,
  type ClassifiedDocument,
  type InformationAnswers,
  type RequirementResponses,
} from "@offroad/credit-playbook";

import type {ReconciledFact} from "./facts";
import type {ExceptionSeverity} from "@offroad/credit-ontology";

/**
 * What is missing, said as a question rather than a silence.
 *
 * Half of what a credit desk sends back is not a correction — it is a request. "We need the
 * payoff letters", "we need proof of the equity contribution", "we need an updated appraisal".
 * Those are not failures of the extraction; they are the desk doing its job, and they are the
 * single most useful thing a company can receive early, because each one is a week saved later.
 *
 * Two sources, both deterministic:
 *
 *   1. **The playbook's checklist** — a required document nobody sent.
 *   2. **The material fields** — a fact the analysis needs that no document stated. This is
 *      what the extractor's `absent_fields` becomes once it is scoped by what the operation
 *      actually requires.
 *
 * Nothing here is invented. A gap names the document or the field, says why it matters, and
 * points at whoever can close it.
 */

export type InformationGap = {
  id: string;
  severity: ExceptionSeverity;
  title: string;
  description: string;
  /** Who closes it. Almost always the company. */
  ownerRole: "company" | "internal_analyst" | "external_advisor";
  /** The requirement or field path behind it, for traceability. */
  reference: string;
};

export function findGaps(input: {
  archetypeId: ArchetypeId;
  documents: readonly ClassifiedDocument[];
  facts: readonly ReconciledFact[];
  locale?: "pt" | "en";
  informationAnswers?: InformationAnswers;
  requirementResponses?: RequirementResponses;
  additionalAvailableFieldPaths?: readonly string[];
}): InformationGap[] {
  const locale = input.locale ?? "pt";
  const gaps: InformationGap[] = [];

  // 1 — documents the operation requires that nobody sent.
  const sufficiency = assessSufficiency(
    input.archetypeId,
    input.documents,
    input.informationAnswers,
    input.requirementResponses,
  );
  for (const status of sufficiency.missing) {
    const {requirement} = status;
    gaps.push({
      id: `missing_document:${requirement.id}`,
      severity: requirement.level === "minimum" ? "high" : "medium",
      title: requirement.labels[locale],
      description: requirement.rationale[locale],
      ownerRole: "company",
      reference: requirement.id,
    });
  }

  // 2 — material facts the analysis needs that no document stated.
  const present = new Set([
    ...input.facts.map((fact) => fact.key.fieldPath),
    ...(input.additionalAvailableFieldPaths ?? []),
  ]);
  const definition = archetype(input.archetypeId);
  for (const requirement of materialFieldRequirements(input.archetypeId)) {
    if (requirementIsSatisfied(requirement, present)) continue;
    const path = requirement.anyOf[0] ?? requirement.id;

    const focus = definition.focus.find((entry) => entry.evidence.some((evidence) => evidence.replace(/\{[a-z]+\}/g, "") === path.replace(/\.\d+\./g, ".")));
    gaps.push({
      id: `missing_field:${requirement.id}`,
      severity: "medium",
      title:
        locale === "pt"
          ? `Informação não encontrada: ${path}`
          : `Information not found: ${path}`,
      description: focus
        ? locale === "pt"
          ? `Nenhum documento enviado declara este dado, e ele é necessário para responder: ${focus.question.pt}`
          : `No document states this, and it is needed to answer: ${focus.question.en}`
        : locale === "pt"
          ? "Nenhum documento enviado declara este dado, e ele é material para a análise."
          : "No document states this, and it is material to the analysis.",
      ownerRole: "company",
      reference: requirement.id,
    });
  }

  return gaps;
}

/**
 * The archetype's known risks, raised as hypotheses to test.
 *
 * These are the questions an experienced lender asks before the numbers are even finished, and
 * they come from the playbook rather than from the data — which is the point. A desk does not
 * wait to be surprised by a ramp-up assumption; it asks about the ramp-up because it is a
 * growth deal.
 */
export function archetypeQuestions(archetypeId: ArchetypeId, locale: "pt" | "en" = "pt"): InformationGap[] {
  const definition = archetype(archetypeId);
  return definition.risks.map((risk) => ({
    id: `risk:${risk.id}`,
    severity: risk.severity === "critical" ? ("high" as const) : risk.severity,
    title: risk.labels[locale],
    description:
      locale === "pt"
        ? `Hipótese a testar neste tipo de operação. Como se verifica: ${risk.test.pt}`
        : `A hypothesis to test in this kind of operation. How it is checked: ${risk.test.en}`,
    ownerRole: "internal_analyst" as const,
    reference: risk.id,
  }));
}

packages/reconciliation/src/debt-truth.t.content:
import {
  aggregateDebtViews,
  applyRateShock,
  buildDebtBalanceBridge,
  calculateLiquidityCoverage,
  debtLedgerBalance,
  groupDebt,
  maturityBuckets,
  propagateDefaults,
  reconcileInterestExpense,
  weightedAverageLife,
  type DebtLedgerMathRow,
  type DefaultEdge,
} from "@offroad/financial-core";
import Decimal from "decimal.js";
import {z} from "zod";

import type {ReconciledFact} from "./facts";

const decimalString = z.string().regex(/^-?\d+(?:\.\d+)?$/);
const evidenceLinkSchema = z.object({fieldPath: z.string(), sourceDocument: z.string(), anchor: z.unknown().optional()}).strict();

export const debtInstrumentSchema = z.object({
  id: z.string().min(1),
  borrower: z.string().nullable(),
  lender: z.string().nullable(),
  instrument: z.string().nullable(),
  contractId: z.string().nullable(),
  entity: z.string().nullable(),
  principal: decimalString.nullable(),
  principalBasis: z.enum(["reported_principal", "reported_balance_only", "missing"]).optional(),
  accruedInterest: decimalString,
  pik: decimalString,
  indexation: decimalString,
  balance: decimalString,
  currency: z.string().nullable(),
  indexer: z.string().nullable(),
  spread: decimalString.nullable(),
  hedge: z.string().nullable(),
  issueDate: z.string().nullable(),
  drawDate: z.string().nullable(),
  maturity: z.string().nullable(),
  amortization: z.string().nullable(),
  cashCost: z.string().nullable(),
  accountingCost: z.string().nullable(),
  allInCost: z.string().nullable(),
  fees: decimalString,
  averageBalance: decimalString.nullable(),
  cashInterest: decimalString.nullable(),
  accountingInterest: decimalString.nullable(),
  collateral: z.string().nullable(),
  collateralOwner: z.string().nullable(),
  collateralValue: decimalString.nullable(),
  lien: z.string().nullable(),
  priority: z.string().nullable(),
  covenantIncluded: z.boolean(),
  capacityObligation: z.boolean(),
  commitment: decimalString,
  quasiDebt: decimalString,
  recourse: z.string().nullable(),
  coobligation: z.string().nullable(),
  repurchase: z.string().nullable(),
  retainedRisk: z.string().nullable(),
  negativePledge: z.string().nullable(),
  renewalCommitment: z.string().nullable(),
  paymentHistory: z.string().nullable(),
  evidence: z.array(evidenceLinkSchema).min(1),
  completeness: z.number().min(0).max(1),
}).strict();
export type DebtInstrument = z.infer<typeof debtInstrumentSchema>;

export const covenantTestSchema = z.object({
  id: z.string(), instrumentId: z.string().nullable(), metric: z.string().nullable(), definition: z.string().nullable(),
  threshold: decimalString.nullable(), direction: z.enum(["maximum", "minimum", "not_informed"]),
  testedValue: decimalString.nullable(), headroom: decimalString.nullable(), cure: z.string().nullable(),
  crossDefault: z.string().nullable(), status: z.enum(["pass", "fail", "not_computable"]), evidence: z.array(evidenceLinkSchema),
}).strict();
export type CovenantTest = z.infer<typeof covenantTestSchema>;

export const debtPaymentSchema = z.object({
  id: z.string(), instrumentId: z.string().nullable(), date: z.string(), principal: decimalString,
  interest: decimalString, other: decimalString, evidence: z.array(evidenceLinkSchema),
}).strict();

export const obligationSchema = z.object({
  id: z.string(), nature: z.string(), entity: z.string().nullable(), counterparty: z.string().nullable(),
  amount: decimalString, currency: z.string().nullable(), dueDate: z.string().nullable(), probability: z.string().nullable(),
  financialDebt: z.boolean(), capacityObligation: z.boolean(), offBalanceSheet: z.boolean(), evidence: z.array(evidenceLinkSchema),
}).strict();

export const debtReconciliationSchema = z.object({
  id: z.string(), expected: decimalString, observed: decimalString, difference: decimalString,
  status: z.enum(["pass", "fail"]), evidence: z.array(evidenceLinkSchema),
}).strict();

export const debtTruthExceptionSchema = z.object({
  id: z.string(), severity: z.enum(["low", "medium", "high", "critical"]),
  message: z.object({pt: z.string(), en: z.string()}).strict(), affectedInstrumentIds: z.array(z.string()),
  evidence: z.array(evidenceLinkSchema), blocksExternalOutputs: z.boolean(),
}).strict();

export const debtTruthSetSchema = z.object({
  version: z.string(), referenceDate: z.string(), status: z.enum(["complete", "partial", "blocked"]),
  instruments: z.array(debtInstrumentSchema),
  views: z.object({
    grossFinancialDebt: decimalString, unrestrictedCash: decimalString, netFinancialDebt: decimalString,
    cashBasis: z.enum(["reported", "missing"]).optional(),
    balanceBasis: z.enum(["reported_instruments", "missing"]).optional(),
    covenantDebt: decimalString, adjustedCapacityObligations: decimalString, commitmentsAndQuasiDebt: decimalString,
    contingentExposures: decimalString, offBalanceSheetExposures: decimalString,
  }).strict(),
  maturity: z.record(z.string(), decimalString),
  payments: z.array(debtPaymentSchema),
  obligations: z.array(obligationSchema),
  serviceNext12Months: decimalString,
  weightedAverageLifeYears: decimalString.nullable(),
  byEntity: z.array(z.object({label: z.string(), value: decimalString}).strict()),
  byLender: z.array(z.object({label: z.string(), value: decimalString}).strict()),
  byCurrency: z.array(z.object({label: z.string(), value: decimalString}).strict()),
  byIndexer: z.array(z.object({label: z.string(), value: decimalString}).strict()),
  byGuarantee: z.array(z.object({label: z.string(), value: decimalString}).strict()),
  covenants: z.array(covenantTestSchema), reconciliations: z.array(debtReconciliationSchema),
  balanceBridge: z.object({value: decimalString, lines: z.array(z.object({id: z.string(), value: decimalString, operation: z.enum(["start", "add", "subtract"])}).strict()), reportedClosingBalance: decimalString, difference: decimalString, status: z.enum(["pass", "fail"]), evidence: z.array(evidenceLinkSchema)}).strict().nullable(),
  interestExpenseBridge: z.object({rows: z.array(z.object({id: z.string(), calculated: decimalString, accounting: decimalString, difference: decimalString}).strict()), calculatedTotal: decimalString, accountingTotal: decimalString, difference: decimalString, reportedAccountingTotal: decimalString.nullable(), reportedDifference: decimalString.nullable(), evidence: z.array(evidenceLinkSchema)}).strict().nullable(),
  liquidityCoverage: z.array(z.object({period: z.string(), openingCash: decimalString, sources: decimalString, debtService: decimalString, coverage: decimalString.nullable(), closingCash: decimalString, deficit: decimalString}).strict()),
  stressScenarios: z.array(z.object({id: z.string(), policyVersion: z.string(), instrumentId: z.string(), baseInterest: decimalString, stressedInterest: decimalString, delta: decimalString}).strict()),
  crossDefault: z.object({edges: z.array(z.object({from: z.string(), to: z.string(), type: z.enum(["cross_default", "cross_acceleration"]), thresholdSatisfied: z.boolean(), cureExpired: z.boolean()}).strict()), defaulted: z.array(z.string()), accelerated: z.array(z.string())}).strict(),
  exceptions: z.array(debtTruthExceptionSchema), missingInputs: z.array(z.string()),
  procedureCoverage: z.array(z.object({procedureId: z.string().regex(/^D-\d{2}$/), status: z.enum(["completed", "partial", "blocked", "not_computable", "not_applicable"]), outputCount: z.number().int().nonnegative(), evidenceCount: z.number().int().nonnegative(), missingInputs: z.array(z.string()), exceptionIds: z.array(z.string())}).strict()).length(31),
}).strict();
export type DebtTruthSet = z.infer<typeof debtTruthSetSchema>;

const source = (fact: ReconciledFact) => ({
  fieldPath: fact.key.fieldPath, sourceDocument: fact.accepted.sourceDocument,
  ...(fact.accepted.anchor !== undefined ? {anchor: fact.accepted.anchor} : {}),
});

const bool = (value: string | undefined) => value === "true" || value === "yes" || value === "sim" || value === "1";

export type DebtAnalysisPolicies = {
  reconciliationTolerance?: string;
  rateShocks?: Array<{id: string; policyVersion: string; indexer: string; baseRate: string; shock: string}>;
  initialDefaultInstrumentIds?: string[];
};

export function buildDebtTruthSet(facts: readonly ReconciledFact[], referenceDate: string, policies: DebtAnalysisPolicies = {}): DebtTruthSet {
  const indexes = [...new Set(facts.map((fact) => fact.key.fieldPath.match(/^debt\.instruments\.(\d+)\./)?.[1]).filter(Boolean))] as string[];
  const missing = new Set<string>();
  const instruments: DebtInstrument[] = indexes.map((index) => {
    const prefix = `debt.instruments.${index}`;
    const rows = facts.filter((fact) => fact.key.fieldPath.startsWith(`${prefix}.`));
    const get = (name: string) => rows.find((fact) => fact.key.fieldPath === `${prefix}.${name}`);
    const principal = get("principal");
    const reportedBalance = get("balance");
    if (!principal) missing.add(`${prefix}.principal`);
    for (const required of ["lender", "instrument_type", "maturity", "currency"]) if (!get(required)) missing.add(`${prefix}.${required}`);
    const math: DebtLedgerMathRow = {
      id: prefix, principal: principal?.value ?? "0", accruedInterest: get("accrued_interest")?.value ?? "0",
      pik: get("pik")?.value ?? "0", indexation: get("indexation_balance")?.value ?? "0",
    };
    const expected = ["lender", "instrument_type", "principal", "currency", "maturity", "amortization", "cash_cost", "collateral", "covenant_included"];
    const present = expected.filter((name) => get(name)).length;
    return debtInstrumentSchema.parse({
      id: prefix, borrower: get("borrower")?.value ?? null, lender: get("lender")?.value ?? null,
      instrument: get("instrument_type")?.value ?? null, contractId: get("contract_id")?.value ?? null,
      entity: get("entity")?.value ?? rows[0]?.key.entityName ?? null,
      principal: principal?.value ?? null,
      principalBasis: principal ? "reported_principal" : reportedBalance ? "reported_balance_only" : "missing", accruedInterest: get("accrued_interest")?.value ?? "0",
      pik: get("pik")?.value ?? "0", indexation: get("indexation_balance")?.value ?? "0", balance: principal ? debtLedgerBalance(math) : reportedBalance?.value ?? "0",
      currency: get("currency")?.value ?? null, indexer: get("indexer")?.value ?? null,
      spread: get("spread")?.value ?? null, hedge: get("hedge")?.value ?? null,
      issueDate: get("issue_date")?.value ?? null, drawDate: get("draw_date")?.value ?? null,
      maturity: get("maturity")?.value ?? null, amortization: get("amortization")?.value ?? null,
      cashCost: get("cash_cost")?.value ?? get("rate")?.value ?? null, accountingCost: get("accounting_cost")?.value ?? null,
      allInCost: get("all_in_cost")?.value ?? null, fees: get("fees")?.value ?? "0",
      averageBalance: get("average_balance")?.value ?? null, cashInterest: get("cash_interest")?.value ?? null,
      accountingInterest: get("accounting_interest")?.value ?? null, collateral: get("collateral")?.value ?? null,
      collateralOwner: get("collateral_owner")?.value ?? null, collateralValue: get("collateral_value")?.value ?? null,
      lien: get("lien")?.value ?? null, priority: get("priority")?.value ?? null,
      covenantIncluded: bool(get("covenant_included")?.value), capacityObligation: bool(get("capacity_obligation")?.value),
      commitment: get("undrawn_commitment")?.value ?? "0", quasiDebt: get("quasi_debt")?.value ?? "0",
      recourse: get("recourse")?.value ?? null, coobligation: get("coobligation")?.value ?? null,
      repurchase: get("repurchase_obligation")?.value ?? null, retainedRisk: get("retained_risk")?.value ?? null,
      negativePledge: get("negative_pledge")?.value ?? null, renewalCommitment: get("renewal_commitment")?.value ?? null,
      paymentHistory: get("payment_history")?.value ?? null,
      evidence: rows.map(source), completeness: present / expected.length,
    });
  });

  // A reported carrying balance already includes its components. Use it once for
  // balance-based views; never derive an unreported nominal principal from it.
  const mathRows: DebtLedgerMathRow[] = instruments.map((instrument) => ({
    id: instrument.id, principal: instrument.principal ?? instrument.balance,
    accruedInterest: instrument.principal === null ? "0" : instrument.accruedInterest,
    pik: instrument.principal === null ? "0" : instrument.pik,
    indexation: instrument.principal === null ? "0" : instrument.indexation, covenantIncluded: instrument.covenantIncluded,
    capacityObligation: instrument.capacityObligation, commitment: instrument.commitment, quasiDebt: instrument.quasiDebt,
    ...(instrument.currency ? {currency: instrument.currency} : {}), ...(instrument.entity ? {entity: instrument.entity} : {}),
    ...(instrument.lender ? {lender: instrument.lender} : {}), ...(instrument.maturity ? {maturity: instrument.maturity} : {}),
  }));

  const rowIndexes = (prefix: string) => [...new Set(facts.map((fact) => fact.key.fieldPath.match(new RegExp(`^${prefix.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\.(\\d+)\\.`))?.[1]).filter(Boolean))] as string[];
  const paymentIndexes = rowIndexes("debt.payments");
  const payments = paymentIndexes.flatMap((index) => {
    const prefix = `debt.payments.${index}`;
    const rows = facts.filter((fact) => fact.key.fieldPath.startsWith(`${prefix}.`));
    const get = (name: string) => rows.find((fact) => fact.key.fieldPath === `${prefix}.${name}`);
    const date = get("date");
    if (!date) { missing.add(`${prefix}.date`); return []; }
    return [debtPaymentSchema.parse({
      id: prefix, instrumentId: get("instrument_id")?.value ?? null, date: date.value,
      principal: get("principal")?.value ?? "0", interest: get("interest")?.value ?? "0", other: get("other")?.value ?? "0",
      evidence: rows.map(source),
    })];
  });

  const obligationIndexes = rowIndexes("debt.obligations");
  const obligations = obligationIndexes.flatMap((index) => {
    const prefix = `debt.obligations.${index}`;
    const rows = facts.filter((fact) => fact.key.fieldPath.startsWith(`${prefix}.`));
    const get = (name: string) => rows.find((fact) => fact.key.fieldPath === `${prefix}.${name}`);
    const nature = get("nature");
    const amount = get("amount");
    if (!nature || !amount) { missing.add(`${prefix}.${!nature ? "nature" : "amount"}`); return []; }
    return [obligationSchema.parse({
      id: prefix, nature: nature.value, entity: get("entity")?.value ?? null, counterparty: get("counterparty")?.value ?? null,
      amount: amount.value, currency: get("currency")?.value ?? null, dueDate: get("due_date")?.value ?? null,
      probability: get("probability")?.value ?? null, financialDebt: bool(get("financial_debt")?.value),
      capacityObligation: bool(get("capacity_obligation")?.value), offBalanceSheet: bool(get("off_balance_sheet")?.value),
      evidence: rows.map(source),
    })];
  });
  const cashFact = facts
    .filter((fact) => /^(historical|interim)_financials\.[^.]+\.cash$/.test(fact.key.fieldPath) && fact.valueType === "number")
    .sort((a, b) => (b.key.periodEnd ?? "").localeCompare(a.key.periodEnd ?? ""))[0];
  if (!cashFact) missing.add("debt.unrestricted_cash");
  const restrictedCash = facts.find((fact) => /\.restricted_cash$/.test(fact.key.fieldPath) && fact.valueType === "number");
  const baseViews = aggregateDebtViews({rows: mathRows, cash: cashFact?.value ?? "0", restrictedCash: restrictedCash?.value ?? "0"});
  const financialObligations = obligations.filter((item) => item.financialDebt).reduce((sum, item) => sum.plus(item.amount), new Decimal(0));
  const capacityObligations = obligations.filter((item) => item.capacityObligation).reduce((sum, item) => sum.plus(item.amount), new Decimal(0));
  const contingentExposures = obligations.filter((item) => /possible|possível|provável|probable/i.test(item.probability ?? "") || /conting/i.test(item.nature)).reduce((sum, item) => sum.plus(item.amount), new Decimal(0));
  const offBalanceSheetExposures = obligations.filter((item) => item.offBalanceSheet).reduce((sum, item) => sum.plus(item.amount), new Decimal(0));
  const views = {
    ...baseViews,
    // Preserve numeric legacy payload shape, but make an unobserved zero unusable as cash evidence.
    cashBasis: cashFact ? "reported" : "missing",
    balanceBasis: instruments.length > 0 && instruments.every((instrument) => instrument.principalBasis !== "missing") ? "reported_instruments" : "missing",
    grossFinancialDebt: new Decimal(baseViews.grossFinancialDebt).plus(financialObligations).toFixed(),
    netFinancialDebt: new Decimal(baseViews.netFinancialDebt).plus(financialObligations).toFixed(),
    adjustedCapacityObligations: new Decimal(baseViews.adjustedCapacityObligations).plus(capacityObligations).toFixed(),
    contingentExposures: contingentExposures.toFixed(),
    offBalanceSheetExposures: offBalanceSheetExposures.toFixed(),
  };

  const covIndexes = [...new Set(facts.map((fact) => fact.key.fieldPath.match(/^debt\.covenants\.(\d+)\./)?.[1]).filter(Boolean))] as string[];
  const covenants: CovenantTest[] = covIndexes.map((index) => {
    const prefix = `debt.covenants.${index}`;
    const get = (name: string) => facts.find((fact) => fact.key.fieldPath === `${prefix}.${name}`);
    const threshold = get("threshold");
    const tested = get("tested_value");
    const direction = get("direction")?.value;
    const normalizedDirection = direction === "maximum" || direction === "minimum" ? direction : "not_informed";
    let headroom: string | null = null;
    let status: CovenantTest["status"] = "not_computable";
    if (threshold && tested && normalizedDirection !== "not_informed") {
      headroom = normalizedDirection === "maximum"
        ? new Decimal(threshold.value).minus(tested.value).toFixed()
        : new Decimal(tested.value).minus(threshold.value).toFixed();
      status = new Decimal(headroom).gte(0) ? "pass" : "fail";
    }
    const evidence = facts.filter((fact) => fact.key.fieldPath.startsWith(`${prefix}.`)).map(source);
    return {
      id: prefix, instrumentId: get("instrument_id")?.value ?? null, metric: get("metric")?.value ?? null,
      definition: get("definition")?.value ?? null, threshold: threshold?.value ?? null, direction: normalizedDirection,
      testedValue: tested?.value ?? null, headroom, cure: get("cure")?.value ?? null,
      crossDefault: get("cross_default")?.value ?? null, status, evidence,
    };
  });

  const reconciliations: z.infer<typeof debtReconciliationSchema>[] = [];
  for (const instrument of instruments) {
    const reported = facts.find((fact) => fact.key.fieldPath === `${instrument.id}.balance`);
    if (instrument.principal === null || !reported) continue;
    const difference = new Decimal(reported.value).minus(instrument.balance);
    reconciliations.push({
      id: `instrument_balance:${instrument.id}`, expected: reported.value, observed: instrument.balance,
      difference: difference.toFixed(), status: difference.abs().lte(policies.reconciliationTolerance ?? "1") ? "pass" : "fail",
      evidence: instrument.evidence,
    });
  }
  const scheduleTotal = facts.find((fact) => fact.key.fieldPath === "debt.total_gross" && fact.valueType === "number");
  if (scheduleTotal) {
    const observed = instruments.reduce((sum, item) => sum.plus(item.balance), new Decimal(0));
    const difference = new Decimal(scheduleTotal.value).minus(observed);
    reconciliations.push({
      id: "schedule_to_ledger", expected: scheduleTotal.value, observed: observed.toFixed(), difference: difference.toFixed(),
      status: difference.abs().lte(policies.reconciliationTolerance ?? "1") ? "pass" : "fail", evidence: [source(scheduleTotal), ...instruments.flatMap((item) => item.evidence)],
    });
  }

  const groupInstruments = (key: "indexer" | "collateral") => {
    const grouped = new Map<string, Decimal>();
    for (const instrument of instruments) {
      const label = instrument[key] || "not_informed";
      grouped.set(label, (grouped.get(label) ?? new Decimal(0)).plus(instrument.balance));
    }
    return [...grouped.entries()].map(([label, value]) => ({label, value: value.toFixed()}))
      .sort((a, b) => new Decimal(b.value).comparedTo(a.value) || a.label.localeCompare(b.label));
  };

  const bridgeFact = (name: string) => facts.find((fact) => fact.key.fieldPath === `debt.balance_bridge.${name}` && fact.valueType === "number");
  const openingBalance = bridgeFact("opening_balance");
  const reportedClosing = bridgeFact("closing_balance");
  const balanceBridge = openingBalance && reportedClosing ? (() => {
    const bridge = buildDebtBalanceBridge({
      openingBalance: openingBalance.value, drawdowns: bridgeFact("drawdowns")?.value ?? 0,
      accruedInterest: bridgeFact("accrued_interest")?.value ?? 0, pik: bridgeFact("pik")?.value ?? 0,
      indexation: bridgeFact("indexation")?.value ?? 0, foreignExchange: bridgeFact("foreign_exchange")?.value ?? 0,
      acquisitions: bridgeFact("acquisitions")?.value ?? 0, otherAdditions: bridgeFact("other_additions")?.value ?? 0,
      amortizations: bridgeFact("amortizations")?.value ?? 0, prepayments: bridgeFact("prepayments")?.value ?? 0,
      writeOffs: bridgeFact("write_offs")?.value ?? 0,
    });
    const difference = new Decimal(reportedClosing.value).minus(bridge.value);
    return {
      ...bridge, reportedClosingBalance: reportedClosing.value, difference: difference.toFixed(),
      status: difference.abs().lte(policies.reconciliationTolerance ?? "1") ? "pass" as const : "fail" as const,
      evidence: facts.filter((fact) => fact.key.fieldPath.startsWith("debt.balance_bridge.")).map(source),
    };
  })() : null;

  const interestRows = instruments.filter((item) => item.cashInterest !== null && item.accountingInterest !== null)
    .map((item) => ({id: item.id, calculated: item.cashInterest!, accounting: item.accountingInterest!}));
  const reportedAccountingTotal = facts.find((fact) => fact.key.fieldPath === "debt.interest_bridge.accounting_total" && fact.valueType === "number");
  const interestExpenseBridge = interestRows.length > 0 ? (() => {
    const bridge = reconcileInterestExpense(interestRows);
    return {
      ...bridge, reportedAccountingTotal: reportedAccountingTotal?.value ?? null,
      reportedDifference: reportedAccountingTotal ? new Decimal(reportedAccountingTotal.value).minus(bridge.accountingTotal).toFixed() : null,
      evidence: [...instruments.filter((item) => item.cashInterest !== null && item.accountingInterest !== null).flatMap((item) => item.evidence), ...(reportedAccountingTotal ? [source(reportedAccountingTotal)] : [])],
    };
  })() : null;

  const referenceTime = new Date(`${referenceDate}T00:00:00.000Z`).getTime();
  const twelveMonths = referenceTime + 365.25 * 24 * 60 * 60 * 1000;
  const serviceNext12Months = payments.filter((item) => {
    const time = new Date(`${item.date}T00:00:00.000Z`).getTime();
    return time >= referenceTime && time <= twelveMonths;
  }).reduce((sum, item) => sum.plus(item.principal).plus(item.interest).plus(item.other), new Decimal(0)).toFixed();
  const weightedAverageLifeYears = weightedAverageLife(payments.map((item) => ({date: item.date, principal: item.principal})), referenceDate);

  const yearlyPayments = new Map<string, {principal: Decimal; interest: Decimal; other: Decimal}>();
  for (const payment of payments) {
    const year = payment.date.slice(0, 4);
    const current = yearlyPayments.get(year) ?? {principal: new Decimal(0), interest: new Decimal(0), other: new Decimal(0)};
    current.principal = current.principal.plus(payment.principal);
    current.interest = current.interest.plus(payment.interest);
    current.other = current.other.plus(payment.other);
    yearlyPayments.set(year, current);
  }
  const cashFlowByYear = new Map<string, ReconciledFact>();
  for (const fact of facts.filter((item) => /^(historical_financials|interim_financials|projections)\.(\d{4}).*\.(free_cash_flow|cfo)$/.test(item.key.fieldPath) && item.valueType === "number")) {
    const year = fact.key.fieldPath.match(/\.(\d{4})/)?.[1];
    if (year && (!cashFlowByYear.has(year) || fact.key.fieldPath.endsWith(".free_cash_flow"))) cashFlowByYear.set(year, fact);
  }
  const liquidityInputs = [...yearlyPayments.entries()].sort(([a], [b]) => a.localeCompare(b)).flatMap(([period, service], index) => {
    const cfads = cashFlowByYear.get(period);
    if (!cfads || !cashFact) return [];
    return [{
      period, openingCash: index === 0 ? cashFact?.value ?? "0" : "0", cfads: cfads.value,
      principal: service.principal.toFixed(), interest: service.interest.toFixed(), otherObligations: service.other.toFixed(),
    }];
  });
  const liquidityCoverage = calculateLiquidityCoverage(liquidityInputs);

  const stressScenarios = (policies.rateShocks ?? []).flatMap((policy) => instruments.flatMap((instrument) => {
    if (instrument.indexer !== policy.indexer || instrument.averageBalance === null) return [];
    return [{id: policy.id, policyVersion: policy.policyVersion, instrumentId: instrument.id, ...applyRateShock({averageBalance: instrument.averageBalance, baseRate: policy.baseRate, shock: policy.shock})}];
  }));

  const edgeIndexes = rowIndexes("debt.cross_default_edges");
  const edges: DefaultEdge[] = edgeIndexes.flatMap((index) => {
    const prefix = `debt.cross_default_edges.${index}`;
    const rows = facts.filter((fact) => fact.key.fieldPath.startsWith(`${prefix}.`));
    const get = (name: string) => rows.find((fact) => fact.key.fieldPath === `${prefix}.${name}`)?.value;
    const from = get("from_instrument");
    const to = get("to_instrument");
    const type = get("type")?.replace("-", "_");
    if (!from || !to || (type !== "cross_default" && type !== "cross_acceleration")) return [];
    return [{from, to, type, thresholdSatisfied: bool(get("threshold_satisfied")), cureExpired: bool(get("cure_expired"))}];
  });
  const propagation = propagateDefaults(policies.initialDefaultInstrumentIds ?? [], edges);
  const crossDefault = {edges, ...propagation};

  const exceptions: z.infer<typeof debtTruthExceptionSchema>[] = [];
  if (!cashFact) exceptions.push({
    id: "missing:unrestricted_cash", severity: "high",
    message: {pt: "O saldo de caixa não foi informado. Informe o caixa disponível para calcular a dívida líquida e a cobertura de liquidez.", en: "The cash balance was not reported. Provide available cash to calculate net debt and liquidity coverage."},
    affectedInstrumentIds: [], evidence: [], blocksExternalOutputs: true,
  });
  for (const row of instruments.filter((item) => item.principalBasis === "missing")) exceptions.push({
    id: `missing_principal:${row.id}`, severity: "high",
    message: {pt: "O principal contratual não foi informado; o saldo reportado não comprova sua composição.", en: "Contractual principal was not reported; the reported balance does not establish its composition."},
    affectedInstrumentIds: [row.id], evidence: row.evidence, blocksExternalOutputs: true,
  });
  for (const row of instruments.filter((item) => item.completeness < 0.4)) exceptions.push({
    id: `incomplete:${row.id}`, severity: "high",
    message: {pt: `O instrumento ${row.id} não possui dados suficientes para uma leitura contratual.`, en: `Instrument ${row.id} lacks sufficient data for a contractual reading.`},
    affectedInstrumentIds: [row.id], evidence: row.evidence, blocksExternalOutputs: true,
  });
  for (const reconciliation of reconciliations.filter((item) => item.status === "fail")) exceptions.push({
    id: `reconciliation:${reconciliation.id}`, severity: "critical",
    message: {pt: "O saldo reportado não concilia com o ledger de dívida.", en: "The reported balance does not reconcile to the debt ledger."},
    affectedInstrumentIds: instruments.map((item) => item.id), evidence: reconciliation.evidence, blocksExternalOutputs: true,
  });
  for (const covenant of covenants.filter((item) => item.status === "fail")) exceptions.push({
    id: `covenant:${covenant.id}`, severity: "critical",
    message: {pt: `O covenant ${covenant.metric ?? covenant.id} está fora do limite literal informado.`, en: `Covenant ${covenant.metric ?? covenant.id} is outside its stated literal limit.`},
    affectedInstrumentIds: covenant.instrumentId ? [covenant.instrumentId] : [], evidence: covenant.evidence, blocksExternalOutputs: true,
  });
  if (balanceBridge?.status === "fail") exceptions.push({
    id: "reconciliation:debt_balance_bridge", severity: "critical",
    message: {pt: "A ponte de evolução da dívida não concilia com o saldo final informado.", en: "The debt evolution bridge does not reconcile to the reported closing balance."},
    affectedInstrumentIds: instruments.map((item) => item.id), evidence: balanceBridge.evidence, blocksExternalOutputs: true,
  });

  const evidenceCount = instruments.reduce((sum, item) => sum + item.evidence.length, 0) + obligations.reduce((sum, item) => sum + item.evidence.length, 0);
  const has = (predicate: (item: DebtInstrument) => boolean) => instruments.filter(predicate).length;
  const coverageInputs: Array<{id: string; outputCount: number; missing: string[]; notApplicable?: boolean}> = [
    {id: "D-01", outputCount: instruments.length, missing: instruments.length ? [] : ["relação analítica por contrato"]},
    {id: "D-02", outputCount: has((item) => item.indexer !== null), missing: has((item) => item.indexer !== null) ? [] : ["indexador e spread por contrato"]},
    {id: "D-03", outputCount: payments.length || instruments.filter((item) => item.maturity).length, missing: payments.length ? [] : ["cronograma de principal por data"]},
    {id: "D-04", outputCount: instruments.length ? 1 : 0, missing: instruments.length ? [] : ["credor e saldo por contrato"]},
    {id: "D-05", outputCount: has((item) => item.renewalCommitment !== null), missing: has((item) => item.renewalCommitment !== null) ? [] : ["compromisso, limite e histórico das linhas curtas"]},
    {id: "D-06", outputCount: has((item) => /sacado|confirming|forfait/i.test(`${item.instrument} ${item.recourse}`)), missing: ["teste documentado de fornecedores financiados"]},
    {id: "D-07", outputCount: has((item) => item.recourse !== null || item.repurchase !== null || item.retainedRisk !== null), missing: ["mecânica de cessões e risco retido"]},
    {id: "D-08", outputCount: obligations.filter((item) => /lease|arrendamento/i.test(item.nature)).length, missing: ["nota e convenção de arrendamentos"]},
    {id: "D-09", outputCount: obligations.filter((item) => /tribut|refis|pert/i.test(item.nature)).length, missing: ["parcelamentos tributários e cronogramas"]},
