import Decimal from "decimal.js";
import {archetype, type ArchetypeId} from "@offroad/credit-playbook";
import {calculateCapacityEnvelope, solveMaximumDebtByDscr} from "@offroad/financial-core";
import type {TracedCalculation} from "@offroad/reconciliation";

/**
 * How much this company can actually carry, and which of the three walls it hits first.
 *
 * A desk does not size an operation against what was asked for. It sizes against three
 * independent limits and takes the lowest, because a deal only clears if all three clear:
 *
 *   - **Cash flow.** What the generation services at the coverage a lender underwrites to.
 *     This is the one that matters most and the one companies underestimate most.
 *   - **Collateral.** What the assets support after haircuts, and after what is already
 *     pledged elsewhere.
 *   - **Market.** What this kind of paper carries at closing leverage before it stops finding
 *     buyers. Not a covenant, not a target, an observation about who buys.
 *
 * Naming the **binding constraint** is the useful part. "You asked for 38 and the answer is
 * 31" is a rejection; "you asked for 38, cash flow supports 46 and collateral supports 31, so
 * the conversation is about security, not about the amount" is the beginning of a structure.
 * Companies routinely respond to the second by finding an asset nobody had mentioned.
 *
 * Every figure here is arithmetic over reconciled facts, and every one carries its inputs.
 * Nothing is indicative in the sense of "roughly": it is indicative in the sense of "this is
 * what the numbers give, before an investor prices the risk".
 */

export type CapacityInput = {
  archetypeId: ArchetypeId;
  /** Amount asked for, decimal string. */
  requested: string;
  /** Cash available for debt service in a year, CFADS. */
  cfads?: string;
  /** Adjusted EBITDA, for the leverage ceiling. */
  adjustedEbitda?: string;
  /** Debt already outstanding, netted of cash. */
  existingNetDebt?: string;
  /** Eligible collateral after policy haircuts. */
  collateralCapacity?: string;
  /**
   * Annual debt service per unit of debt, at the tenor being discussed. A 60-month SAC
   * amortisation with interest is roughly 0.28; the caller passes what the structure implies.
   */
  annualDebtServiceFactor?: string;
  /** Annual recurring revenue, for venture debt, where EBITDA is negative by design. */
  arr?: string;
  /** Size of the last equity round, the other reference a venture lender sizes against. */
  lastEquityRound?: string;
};

export type CapacityWall = {
  id: "cash_flow" | "collateral" | "market" | "arr_and_round";
  labels: {pt: string; en: string};
  /** Decimal string, or null when the inputs to compute it are missing. */
  amount: string | null;
  /** Why this number, in terms the reader can check. */
  explanation: {pt: string; en: string};
  /** Which facts and calculations it rests on. */
  inputs: string[];
};

export type CapacityAssessment = {
  requested: string;
  /** The lowest wall, what the desk would take to market. Null when nothing could be computed or existing net debt is unknown for non-venture sizing. */
  recommended: string | null;
  bindingConstraint: CapacityWall["id"] | null;
  walls: CapacityWall[];
  /** Traced calculations, for the audit trail. */
  calculations: TracedCalculation[];
  /** What could not be computed and why, never silently omitted. */
  gaps: string[];
};

const money = (value: Decimal) => value.toDecimalPlaces(2).toFixed();

export function assessCapacity(input: CapacityInput): CapacityAssessment {
  const definition = archetype(input.archetypeId);
  const calculations: TracedCalculation[] = [];
  const gaps: string[] = [];

  // Venture debt is sized against a company that burns cash on purpose: the cash-flow wall and
  // the EBITDA-multiple wall do not exist for it. What exists is a fraction of the recurring
  // revenue and a fraction of the last round, whichever is lower, and the collateral wall.
  const ventureDebt = definition.id === "venture_debt";
  let arrAndRound: string | null = null;
  if (ventureDebt) {
    const candidates: Array<{label: string; value: Decimal}> = [];
    if (input.arr && new Decimal(input.arr).gt(0)) candidates.push({label: "arr", value: new Decimal(input.arr).times("0.30")});
    if (input.lastEquityRound && new Decimal(input.lastEquityRound).gt(0)) candidates.push({label: "last_equity_round", value: new Decimal(input.lastEquityRound).times("0.35")});
    if (candidates.length > 0) {
      const lowest = candidates.reduce((min, entry) => (entry.value.lt(min.value) ? entry : min));
      arrAndRound = money(lowest.value);
      calculations.push({
        id: "capacity_arr_and_round",
        labels: {pt: "Capacidade por ARR e última rodada", en: "Capacity from ARR and last round"},
        value: arrAndRound,
        trace: [
          {label: "arr", value: input.arr ?? "n/d"},
          {label: "arr_fraction", value: "0.30"},
          {label: "last_equity_round", value: input.lastEquityRound ?? "n/d"},
          {label: "round_fraction", value: "0.35"},
          {label: "binding", value: lowest.label},
        ],
        inputs: ["historical_financials.arr", "company.last_equity_round.amount", "playbook.venture_debt"],
        warnings: [],
      });
    } else {
      gaps.push("ARR ou valor da última rodada");
    }
  }

  // ---- wall 1: what the cash flow services -------------------------------------------------
  let cashFlow: string | null = null;
  if (ventureDebt) {
    // Not a gap: a venture lender does not ask a pre-profit company for DSCR.
  } else if (input.cfads && input.annualDebtServiceFactor) {
    const result = solveMaximumDebtByDscr(input.cfads, definition.structure.minimumDscr, input.annualDebtServiceFactor);
    cashFlow = result.value;
    calculations.push({
      id: "capacity_cash_flow",
      labels: {pt: "Capacidade por geração de caixa", en: "Capacity from cash generation"},
      value: result.value,
      trace: result.trace,
      inputs: ["calculated.cfads", "playbook.minimum_dscr"],
      warnings: [],
    });
  } else {
    gaps.push(input.cfads ? "fator de serviço da dívida" : "CFADS (caixa disponível para o serviço da dívida)");
  }

  // ---- wall 2: what the collateral supports ------------------------------------------------
  const collateral = input.collateralCapacity ?? null;
  if (!collateral) gaps.push("capacidade de garantias após haircut");

  // ---- wall 3: what the market carries -----------------------------------------------------
  //
  // Honest naming, because this one is easy to over-read. The number is EBITDA times the
  // playbook's leverage ceiling, the desk's own view of what this profile places, not an
  // observation of transactions that cleared. It is a good proxy for *size*, and it says nothing
  // at all about tenor, which is the other half of what the market decides; that half lives in
  // `market.ts` and is labelled by provenance for the same reason.
  let market: string | null = null;
  if (ventureDebt) {
    // No EBITDA ceiling by construction; the ARR wall above plays this role.
  } else if (input.existingNetDebt === undefined) {
    gaps.push("Dívida líquida existente");
  } else if (input.adjustedEbitda) {
    const ebitda = new Decimal(input.adjustedEbitda);
    if (ebitda.gt(0)) {
      const ceiling = ebitda.times(definition.structure.leverageCeiling);
      const headroom = ceiling.minus(new Decimal(input.existingNetDebt));
      // Already above the ceiling means no incremental room, not negative room.
      market = money(Decimal.max(headroom, new Decimal(0)));
      calculations.push({
        id: "capacity_market",
        labels: {pt: "Capacidade pelo teto de alavancagem", en: "Capacity at the leverage ceiling"},
        value: market,
        trace: [
          {label: "adjusted_ebitda", value: money(ebitda)},
          {label: "leverage_ceiling", value: definition.structure.leverageCeiling},
          {label: "existing_net_debt", value: input.existingNetDebt},
        ],
        inputs: ["calculated.adjusted_ebitda", "playbook.leverage_ceiling", "calculated.net_debt"],
        warnings: [],
      });
    } else {
      gaps.push("EBITDA ajustado positivo");
    }
  } else {
    gaps.push("EBITDA ajustado");
  }

  const ventureWall: CapacityWall = {
    id: "arr_and_round",
    labels: {pt: "Fração do ARR e da última rodada", en: "Fraction of ARR and last round"},
    amount: arrAndRound,
    explanation: {
      pt: arrAndRound
        ? "O menor entre 30% do ARR e 35% da última rodada de equity: a prática de venture debt, onde o EBITDA é negativo por desenho e o que sustenta a dívida é a receita recorrente e o apoio dos investidores."
        : "Não calculada: falta o ARR ou o valor da última rodada.",
      en: arrAndRound
        ? "The lower of 30% of ARR and 35% of the last equity round: venture-debt practice, where EBITDA is negative by design and what carries the debt is recurring revenue and sponsor support."
        : "Not computed: ARR or the last round size is missing.",
    },
    inputs: ["historical_financials.arr", "company.last_equity_round.amount"],
  };
  const walls: CapacityWall[] = [
    ...(ventureDebt ? [ventureWall] : []),
    ...(ventureDebt ? [] : [{
      id: "cash_flow" as const,
      labels: {pt: "Geração de caixa", en: "Cash generation"},
      amount: cashFlow,
      explanation: {
        pt: cashFlow
          ? `A geração cobre um serviço de dívida a um DSCR mínimo de ${definition.structure.minimumDscr}x, que é a cobertura que um financiador subscreve para este tipo de operação.`
          : "Não calculada: falta CFADS ou o fator de serviço da dívida do prazo em discussão.",
        en: cashFlow
          ? `Generation covers debt service at a minimum DSCR of ${definition.structure.minimumDscr}x, the coverage a lender underwrites to for this operation.`
          : "Not computed: CFADS or the debt service factor for the tenor under discussion is missing.",
      },
      inputs: ["calculated.cfads"],
    }]),
    {
      id: "collateral",
      labels: {pt: "Garantias", en: "Collateral"},
      amount: collateral,
      explanation: {
        pt: collateral
          ? "Base elegível dos ativos após os haircuts de política e descontado o que já está gravado."
          : "Não calculada: falta a base elegível dos ativos e o haircut por classe.",
        en: collateral
          ? "Eligible asset base after policy haircuts and net of what is already encumbered."
          : "Not computed: the eligible asset base and per-class haircut are missing.",
      },
      inputs: ["calculated.collateral_capacity_total"],
    },
    ...(ventureDebt ? [] : [{
      id: "market" as const,
      labels: {pt: "Apetite de mercado (alavancagem)", en: "Market appetite (leverage)"},
      amount: market,
      explanation: {
        pt: market
          ? `Espaço até ${definition.structure.leverageCeiling}x dívida líquida / EBITDA no fechamento, que é onde este tipo de papel deixa de encontrar comprador. Este teto é a leitura do desk, não uma média de operações observadas, e ele fala de tamanho, não de prazo. Não é covenant nem meta.`
          : "Não calculada: falta EBITDA ajustado positivo ou dívida líquida existente.",
        en: market
          ? `Room to ${definition.structure.leverageCeiling}x net debt / EBITDA at closing, where this paper stops finding buyers. This ceiling is the desk's read rather than an average of observed transactions, and it speaks to size, not tenor. Not a covenant and not a target.`
          : "Not computed: positive adjusted EBITDA or existing net debt is missing.",
      },
      inputs: ["calculated.adjusted_ebitda"],
    }]),
  ];

  const computed = walls.filter((wall): wall is CapacityWall & {amount: string} => wall.amount !== null);
  if (computed.length === 0 || (!ventureDebt && input.existingNetDebt === undefined)) {
    return {requested: input.requested, recommended: null, bindingConstraint: null, walls, calculations, gaps};
  }

  // The envelope takes the lowest of the three. A wall that could not be computed is not
  // treated as infinite, it is simply absent, and the gaps say so, because a recommendation
  // that ignores a missing constraint is a recommendation that will move later.
  const envelope = calculateCapacityEnvelope({
    requested: input.requested,
    cashFlowCapacity: cashFlow ?? arrAndRound ?? computed[0]!.amount,
    collateralCapacity: collateral ?? computed[0]!.amount,
    marketCapacity: market ?? arrAndRound ?? computed[0]!.amount,
  });

  const binding = computed.reduce((lowest, wall) =>
    new Decimal(wall.amount).lt(new Decimal(lowest.amount)) ? wall : lowest,
  );

  return {
    requested: envelope.requested,
    recommended: binding.amount,
    bindingConstraint: binding.id,
    walls,
    calculations,
    gaps,
  };
}

packages/deal-structure/src/termsheet.ts.content:
import Decimal from "decimal.js";
import {archetype, type ArchetypeId} from "@offroad/credit-playbook";

import type {CapacityAssessment} from "./capacity";
import {bandProvenanceNote, playbookBand, reconcileTenor, type MarketBand} from "./market";

/**
 * The indicative term sheet — the shape of the paper, with every term traceable to why.
 *
 * This is the document a company takes to a conversation, and the discipline that makes it
 * useful is the same one that makes it safe: **it is indicative and it says so in its own
 * structure**, not in a footnote. Amounts come from the capacity assessment, tenor and
 * covenants come from the playbook's bands, and pricing is deliberately absent — the desk does
 * not know what an investor will charge, and inventing a rate is the fastest way to lose the
 * company's trust when the market answers differently.
 *
 * Every term carries a `basis`: where it came from. A company reading "prazo 60 meses" learns
 * nothing; reading "60 meses — dentro da banda típica para expansão (48–84), limitada pela
 * maturação do projeto" can argue with it, which is the point.
 *
 * The endpoint of this product is a qualified introduction. Nothing here commits anyone to
 * anything, and the language is written so it cannot be read as an offer.
 */

export type TermBasis = "capacity" | "playbook" | "company_request" | "reconciled_fact";

/**
 * Whether this term answers something the company asked for, or fills something it did not.
 *
 * A company often arrives knowing one thing — "I need R$ 40 million" — and nothing else. It does
 * not know whether it wants 48 months or 72, six months of grace or twelve, a debênture or a
 * CCB. That is the expertise it came here for, and a product that treats those blanks as missing
 * input has misunderstood its own job.
 *
 * So every term is either **`requested`** — the company stated a preference and this is our read
 * on it — or **`proposed`**, which we filled in from the analysis. The distinction is not
 * cosmetic: it changes what the sentence next to the number has to do. A proposed term must
 * justify itself from scratch; a requested one must explain why we agree, or why we do not.
 */
export type TermOrigin = "requested" | "proposed";

export type Term = {
  id: string;
  labels: {pt: string; en: string};
  /** The value, formatted for reading. */
  value: {pt: string; en: string};
  basis: TermBasis;
  /** Exact governed inputs that produced the term. No rendered term may invent its provenance. */
  supportIds: string[];
  origin: TermOrigin;
  /** Why this value and not another. */
  rationale: {pt: string; en: string};
  /**
   * Present only when the company asked for something the analysis does not support.
   *
   * This is the sentence that has to survive a hard conversation, so it carries both sides: what
   * they asked for, and the reason ours differs. A term sheet that quietly replaces a company's
   * number with a better one teaches it nothing and ambushes it in the first meeting where
   * somebody asks why the figure changed.
   */
  divergence?: {
    requested: {pt: string; en: string};
    reason: {pt: string; en: string};
  };
};

export type IndicativeTermSheet = {
  archetypeId: ArchetypeId;
  /** `indicative` always. The type exists to make the absence of other values obvious. */
  status: "indicative";
  terms: Term[];
  /** Covenants proposed for discussion, from the archetype's menu. */
  covenants: string[];
  /** The security package the desk would ask for. */
  collateral: string[];
  /** What stops this being circulated, if anything. */
  blockers: string[];
  /** Stated plainly, in the document, in both languages. */
  disclaimer: {pt: string; en: string};
};

export type TermSheetInput = {
  archetypeId: ArchetypeId;
  capacity: CapacityAssessment;
  /** Tenor the company asked for, in months. */
  requestedTermMonths?: number;
  /** Grace the company asked for, in months. */
  requestedGraceMonths?: number;
  /**
   * The cost the company hoped for, as it wrote it ("13% a.a.", "CDI + 4").
   *
   * Recorded and answered, never argued with by an invented number. Kept as free text because a
   * company writes a rate in whatever convention it thinks in, and normalising it here would be
   * pretending to a precision the field does not have.
   */
  expectedRate?: string;
  /** Currency of the operation. */
  currency?: string;
  /** Anything that holds the case — a critical exception, a missing minimum document. */
  blockers?: readonly string[];
  /**
   * What the market does for this profile. Defaults to the playbook's band, labelled as ours.
   *
   * Passing an observed band is what turns "this operation usually carries 48–84 months" into
   * "fourteen transactions of this profile cleared between 48 and 72 months in the last year" —
   * the same sentence with evidence behind it.
   */
  market?: MarketBand;
};

const formatMoney = (value: string, currency: string, locale: "pt-BR" | "en-US") =>
  `${currency} ${Number(value).toLocaleString(locale, {maximumFractionDigits: 0})}`;

/** Clamps a requested figure into a band, and says which end it hit. */
function withinBand(requested: number | undefined, band: [number, number]): {value: number; clamped: "low" | "high" | null} {
  if (requested === undefined) return {value: band[1], clamped: null};
  if (requested < band[0]) return {value: band[0], clamped: "low"};
  if (requested > band[1]) return {value: band[1], clamped: "high"};
  return {value: requested, clamped: null};
}

export function buildTermSheet(input: TermSheetInput): IndicativeTermSheet {
  const definition = archetype(input.archetypeId);
  const currency = input.currency ?? "R$";
  const terms: Term[] = [];

  // ---- amount ------------------------------------------------------------------------------
  const recommended = input.capacity.recommended;
  const requested = input.capacity.requested;
  const constrained = recommended !== null && new Decimal(recommended).lt(new Decimal(requested));

  const bindingLabel =
    input.capacity.bindingConstraint === "cash_flow"
      ? {pt: "a geração de caixa", en: "cash generation"}
      : input.capacity.bindingConstraint === "collateral"
        ? {pt: "a capacidade de garantias", en: "collateral capacity"}
        : input.capacity.bindingConstraint === "arr_and_round"
          ? {pt: "a fração do ARR e da última rodada", en: "the fraction of ARR and of the last round"}
          : {pt: "o apetite de mercado", en: "market appetite"};

  terms.push({
    id: "amount",
    labels: {pt: "Montante indicativo", en: "Indicative amount"},
    value: {
      pt: recommended ? formatMoney(recommended, currency, "pt-BR") : "a definir",
      en: recommended ? formatMoney(recommended, currency, "en-US") : "to be determined",
    },
    basis: "capacity",
    supportIds: ["capacity.requested", "capacity.recommended", `capacity.constraint.${input.capacity.bindingConstraint ?? "none"}`],
    // The amount is always something the company asked for — it is the one thing nobody else can
    // state on its behalf.
    origin: "requested",
    rationale: constrained
      ? {
          pt: `Pedido de ${formatMoney(requested, currency, "pt-BR")}. O limite é ${bindingLabel.pt}, e a conversa é sobre essa restrição, não sobre o montante.`,
          en: `Requested ${formatMoney(requested, currency, "en-US")}. The binding limit is ${bindingLabel.en}, and the conversation is about that constraint, not about the amount.`,
        }
      : {
          pt: "O montante pedido cabe nas três restrições calculadas.",
          en: "The requested amount fits inside all three computed constraints.",
        },
    ...(constrained
      ? {
          divergence: {
            requested: {
              pt: formatMoney(requested, currency, "pt-BR"),
              en: formatMoney(requested, currency, "en-US"),
            },
            reason: {
              pt: `A operação não suporta o pedido inteiro: ${bindingLabel.pt} limita em ${formatMoney(recommended!, currency, "pt-BR")}. Para chegar aos ${formatMoney(requested, currency, "pt-BR")} é preciso mexer nessa restrição: mais garantia, prazo maior, ou o caixa crescendo antes do desembolso.`,
              en: `The operation does not carry the full request: ${bindingLabel.en} caps it at ${formatMoney(recommended!, currency, "en-US")}. Reaching ${formatMoney(requested, currency, "en-US")} means moving that constraint: more security, a longer tenor, or cash growing before disbursement.`,
            },
          },
        }
      : {}),
  });

  // ---- tenor and grace ---------------------------------------------------------------------
  //
  // Two different constraints, and conflating them is how a company is told something beautiful
  // and then hears nothing back from the market. The cash flow decides whether the operation can
  // be serviced; the band decides whether anyone buys that shape. This is the second one.
  const band = input.market ?? playbookBand(input.archetypeId);
  const bandNote = bandProvenanceNote(band);
  const verdict = reconcileTenor(band, input.requestedTermMonths);
  const tenor = {value: verdict.recommended, clamped: verdict.binding === "market" ? ((input.requestedTermMonths ?? 0) < band.tenorMonths.min ? "low" : "high") : null} as const;
  terms.push({
    id: "tenor",
    labels: {pt: "Prazo", en: "Tenor"},
    value: {pt: `${tenor.value} meses`, en: `${tenor.value} months`},
    basis: input.requestedTermMonths === undefined ? "playbook" : "company_request",
    supportIds: [
      `playbook.archetype.${input.archetypeId}.tenor`,
      `market.band.${band.provenance}`,
      ...(input.requestedTermMonths === undefined ? [] : ["transaction.desired_term_months"]),
    ],
    origin: input.requestedTermMonths === undefined ? "proposed" : "requested",
    rationale:
      input.requestedTermMonths === undefined
        ? {
            pt: `Você não indicou prazo, então propomos ${tenor.value} meses: é o prazo que os financiadores compram neste perfil (${band.tenorMonths.min}–${band.tenorMonths.max} meses). ${bandNote.pt} ${definition.structure.notes.pt}`,
            en: `You did not state a tenor, so we propose ${tenor.value} months: it is the tenor lenders buy in this profile (${band.tenorMonths.min}–${band.tenorMonths.max} months). ${bandNote.en} ${definition.structure.notes.en}`,
          }
        : {
            pt: `Dentro do que os financiadores compram neste perfil (${band.tenorMonths.min}–${band.tenorMonths.max} meses). ${bandNote.pt} ${definition.structure.notes.pt}`,
            en: `Inside what lenders buy in this profile (${band.tenorMonths.min}–${band.tenorMonths.max} months). ${bandNote.en} ${definition.structure.notes.en}`,
          },
    ...(tenor.clamped
      ? {
          divergence: {
            requested: {pt: `${input.requestedTermMonths} meses`, en: `${input.requestedTermMonths} months`},
            reason:
              tenor.clamped === "low"
                ? {
                    pt: `Os financiadores deste perfil trabalham entre ${band.tenorMonths.min} e ${band.tenorMonths.max} meses. Prazo apertado sobe a parcela e derruba a cobertura, e costuma ser isso que faz o fundo recusar, não o valor. ${bandNote.pt}`,
                    en: `Lenders in this profile work between ${band.tenorMonths.min} and ${band.tenorMonths.max} months. A tight tenor raises the instalment and cuts coverage, and that is usually what makes a fund decline, rather than the amount. ${bandNote.en}`,
                  }
                : {
                    pt: `O seu fluxo pode até comportar esse prazo. O problema é outro: os financiadores deste perfil compram de ${band.tenorMonths.min} a ${band.tenorMonths.max} meses. Fundo de crédito tem os próprios cotistas para remunerar num horizonte, e prazo fora disso simplesmente não encontra comprador, por mais que a conta feche. ${bandNote.pt}`,
                    en: `Your cash flow may well carry that tenor. The problem is a different one: lenders in this profile buy ${band.tenorMonths.min} to ${band.tenorMonths.max} months. A credit fund has its own investors to repay on its own horizon, and a tenor outside that simply finds no buyer, however well the arithmetic works. ${bandNote.en}`,
                  },
          },
        }
      : {}),
  });

  const grace = withinBand(input.requestedGraceMonths, definition.structure.gracePeriodMonths.typical);
  terms.push({
    id: "grace",
    labels: {pt: "Carência", en: "Grace period"},
    value: {pt: `${grace.value} meses`, en: `${grace.value} months`},
    basis: input.requestedGraceMonths === undefined ? "playbook" : "company_request",
    supportIds: [
      `playbook.archetype.${input.archetypeId}.grace`,
      ...(input.requestedGraceMonths === undefined ? [] : ["transaction.desired_grace_months"]),
    ],
    origin: input.requestedGraceMonths === undefined ? "proposed" : "requested",
    rationale:
      input.requestedGraceMonths === undefined
        ? {
            pt: `Você não indicou carência, então propomos ${grace.value} meses. A banda usual desta operação é ${definition.structure.gracePeriodMonths.typical.join("–")} meses, e ela existe para cobrir o tempo até o investimento começar a gerar caixa.`,
            en: `You did not state a grace period, so we propose ${grace.value} months. The usual band for this operation is ${definition.structure.gracePeriodMonths.typical.join("–")} months, and it exists to cover the time before the investment starts generating cash.`,
          }
        : {
            pt: `Banda típica: ${definition.structure.gracePeriodMonths.typical.join("–")} meses.`,
            en: `Typical band: ${definition.structure.gracePeriodMonths.typical.join("–")} months.`,
          },
    ...(grace.clamped
      ? {
          divergence: {
            requested: {pt: `${input.requestedGraceMonths} meses`, en: `${input.requestedGraceMonths} months`},
            reason:
              grace.clamped === "low"
                ? {
                    pt: `Curta para esta operação. Começar a amortizar antes de o investimento maturar é o que costuma apertar a cobertura no primeiro ano, e o primeiro ano é o que o comitê olha.`,
                    en: `Short for this operation. Amortising before the investment matures is what usually squeezes coverage in year one, and year one is what a committee looks at.`,
                  }
                : {
                    pt: `Mais longa que o usual (${definition.structure.gracePeriodMonths.typical.join("–")} meses). Carência longa não é de graça: o juro do período corre e entra no saldo, e o financiador cobra por isso.`,
                    en: `Longer than usual (${definition.structure.gracePeriodMonths.typical.join("–")} months). A long grace is not free: interest accrues into the balance over the period, and the lender charges for it.`,
                  },
          },
        }
      : {}),
  });

  terms.push({
    id: "amortization",
    labels: {pt: "Amortização", en: "Amortisation"},
    value: {pt: definition.structure.amortization.join(" · "), en: definition.structure.amortization.join(" · ")},
    basis: "playbook",
    supportIds: [`playbook.archetype.${input.archetypeId}.amortization`],
    origin: "proposed",
    rationale: {
      pt: "Formatos usuais para esta operação; o definitivo acompanha o perfil de geração.",
      en: "Usual formats for this operation; the final one follows the generation profile.",
    },
  });

  // No rate is stated in the document that reaches an investor. Inventing one is the fastest way
  // to lose the company's trust when the market answers differently, and a term sheet that prices
  // itself is presuming to speak for whoever takes the risk.
  //
  // What the company hoped for is answered separately, on the internal side: a banker tells their
  // client "expect CDI + 5"; they do not put a number in the teaser. That view needs comparables
  // to be worth anything, and the comparables are the fund directory's observed transactions —
  // which is why `expectedRate` is recorded here as an open question rather than argued with.
  terms.push({
    id: "pricing",
    labels: {pt: "Custo", en: "Pricing"},
    value: {pt: "definido pelo investidor", en: "set by the investor"},
    basis: "playbook",
    supportIds: [
      "playbook.boundary.investor_sets_pricing",
      ...(input.expectedRate === undefined ? [] : ["transaction.expected_rate"]),
    ],
    origin: input.expectedRate === undefined ? "proposed" : "requested",
    rationale: {
      pt: "A Offroad não precifica: o custo sai da conversa com quem toma o risco. O que este documento faz é chegar nessa conversa com os números conciliados e rastreáveis.",
      en: "Offroad does not price: cost comes from the conversation with whoever takes the risk. What this document does is arrive at that conversation with reconciled, traceable numbers.",
    },
    ...(input.expectedRate
      ? {
          divergence: {
            requested: {pt: input.expectedRate, en: input.expectedRate},
            reason: {
              pt: "Este documento não traz taxa, e isso é deliberado: quem precifica é quem toma o risco. A leitura do que o mercado tem pago para este perfil fica no documento interno, sustentada pelas operações comparáveis, não em um número posto aqui.",
              en: "This document carries no rate, deliberately: whoever takes the risk sets the price. Our read on what the market has been paying for this profile belongs in the internal document, supported by comparable transactions rather than by a number asserted here.",
            },
          },
        }
      : {}),
  });

  return {
    archetypeId: input.archetypeId,
    status: "indicative",
    terms,
    covenants: [...definition.structure.covenants],
    collateral: [...definition.structure.collateral],
    blockers: [...(input.blockers ?? [])],
    disclaimer: {
      pt: "Documento indicativo, preparado a partir das informações fornecidas pela companhia e conciliadas pela Offroad. Não constitui oferta, compromisso de crédito ou garantia de captação. Termos definitivos dependem de diligência e da decisão de cada investidor.",
      en: "Indicative document, prepared from information provided by the company and reconciled by Offroad. It is not an offer, a credit commitment or a guarantee of funding. Definitive terms depend on diligence and on each investor's decision.",
    },
  };
}

packages/deal-structure/src/market.ts.content:
import {archetype, type ArchetypeId} from "@offroad/credit-playbook";

/**
 * What the market actually does for this kind of operation — and how we know.
 *
 * There are two entirely different constraints on a transaction, and this desk was conflating
 * them. The first is arithmetic: what the company's cash flow, collateral and leverage support.
 * The second is behavioural: what funds are willing to buy. A 160-month facility can pass every
 * coverage test and still be unplaceable, because a credit fund has its own investors to repay
 * on its own horizon, and no amount of DSCR fixes a tenor nobody holds.
 *
 * Telling a company "your cash flow carries 160 months" and stopping there is the failure mode:
 * beautiful on paper, and then silence from the market. The useful sentence is "your cash flow
 * carries 160 months; funds in this profile buy 48 to 72; we recommend 72, and the binding
 * constraint is the market, not you."
 *
 * **Provenance is the point of this module.** The playbook's bands are the desk's own view —
 * defensible, validated by a banker, and still an opinion. Presenting an opinion in the voice of
 * an observation is the thing that would embarrass us in a room with a fund manager, so a band
 * always says which it is:
 *
 * - `observed` — reconstructed from transactions that actually cleared, with the sample attached.
 *   "Fourteen operations of this profile in the last twelve months, 48 to 72 months" is a fact
 *   somebody can check and argue with.
 * - `playbook` — our own practice band, used when nothing has been observed yet. Honest, and
 *   labelled, so nobody mistakes it for evidence.
 *
 * The upgrade path is deliberately a data change and not a code change: when the fund directory
 * carries observed transactions, `observedBand` is built from them and everything downstream
 * starts citing a sample instead of citing us.
 */

export type BandProvenance = "observed" | "playbook";

export type MarketSample = {
  /** How many transactions the band was built from. */
  count: number;
  /** How far back they reach. A band from five years ago is not this market. */
  windowMonths: number;
  /** ISO date the observation window closed. */
  asOf: string;
};

export type MarketBand = {
  archetypeId: ArchetypeId;
  tenorMonths: {min: number; max: number};
  /** Net debt / EBITDA the market has been carrying, as a decimal string. */
  leverageCeiling: string;
  provenance: BandProvenance;
  /** Present only when `provenance` is `observed`. */
  sample?: MarketSample;
};

/**
 * The desk's own practice band, labelled as such.
 *
 * Used until the directory has enough observed transactions of a profile to speak for it. The
 * numbers are the playbook's, which is the right default — they were validated by somebody who
 * ran a desk for twenty years — but the label is what keeps the product honest.
 */
export function playbookBand(archetypeId: ArchetypeId): MarketBand {
  const definition = archetype(archetypeId);
  return {
    archetypeId,
    tenorMonths: {min: definition.structure.tenorMonths.typical[0], max: definition.structure.tenorMonths.typical[1]},
    leverageCeiling: definition.structure.leverageCeiling,
    provenance: "playbook",
  };
}

/**
 * How a band should describe itself when a company asks where the number came from.
 *
 * Two sentences that a reader can act on differently: one invites "says who?", and answers it;
 * the other admits it is a judgement and lets the reader weigh it as one.
 */
export function bandProvenanceNote(band: MarketBand): {pt: string; en: string} {
  if (band.provenance === "observed" && band.sample) {
    const {count, windowMonths} = band.sample;
    return {
      pt: `Faixa observada em ${count} ${count === 1 ? "operação" : "operações"} deste perfil nos últimos ${windowMonths} meses.`,
      en: `Range observed across ${count} ${count === 1 ? "transaction" : "transactions"} of this profile in the last ${windowMonths} months.`,
    };
  }
  return {
    pt: "Faixa de prática do desk, não observação de mercado. Ainda não temos operações comparáveis suficientes deste perfil.",
    en: "The desk's practice range, not a market observation. We do not yet have enough comparable transactions of this profile.",
  };
}

export type TenorVerdict = {
  /** The tenor to take to market. */
  recommended: number;
  /** What the company asked for, when it asked. */
  requested?: number;
  /**
   * Which constraint decided it.
   *
   * `market` is the one that matters most and the one this module exists to surface: the
   * company's numbers were fine and the market simply does not buy that shape.
   */
  binding: "market" | "request" | "default";
  band: MarketBand;
};

/**
 * Reconciles what the company asked for against what the market buys.
 *
 * A request inside the band is honoured — the market has room for it and there is nothing to
 * argue about. Outside it, the band wins, and `binding: "market"` is how the caller knows to
 * write "funds do not buy this shape" rather than "adjusted into the typical band", which reads
 * as a technicality and teaches nobody anything.
 */
export function reconcileTenor(band: MarketBand, requested: number | undefined): TenorVerdict {
  if (requested === undefined) {
    // With nothing asked for, the top of the band is the right proposal: longer tenor is easier
    // on coverage, and the ceiling is where the market stops rather than where it prefers.
    return {recommended: band.tenorMonths.max, binding: "default", band};
  }
  if (requested < band.tenorMonths.min) {
    return {recommended: band.tenorMonths.min, requested, binding: "market", band};
  }
  if (requested > band.tenorMonths.max) {
    return {recommended: band.tenorMonths.max, requested, binding: "market", band};
  }
  return {recommended: requested, requested, binding: "request", band};
}

packages/deal-structure/src/collateral.t.content:
import Decimal from "decimal.js";

/**
 * The security package, designed from the inventory instead of listed from the playbook.
 *
 * A term sheet that says "alienação fiduciária de imóveis e cessão de recebíveis" has said
 * nothing a fund can price. What it prices is coverage: eligible value after the haircut the
 * asset class carries, over the ticket, asset by asset, with what is already pledged taken
 * out. This module reads the collateral inventory the room states, applies the desk's policy
 * haircut when the room states none, orders the assets by the quality a lender ranks them in,
 * and picks the smallest package that reaches the coverage the archetype asks for. Every asset
 * says what it adds and what was taken off it.
 */

export type CollateralClass = "receivables" | "inventory" | "property" | "equipment" | "vehicles" | "shares" | "financial" | "guarantee" | "other";

export type CollateralAsset = {
  /** As the room names it. */
  description: string;
  type: CollateralClass;
  /** Book or appraisal value, in reais; the appraisal wins when both exist. */
  value: string;
  /** Whether the value comes from an appraisal report rather than the books. */
  appraised?: boolean;
  /** What is already pledged against this asset, in reais. */
  encumbered?: string;
  /** Haircut the room states; absent → the desk's policy by class. */
  haircut?: string;
};

export type PackageLine = {
  asset: CollateralAsset;
  /** The haircut applied, as a fraction, and where it came from. */
  haircut: string;
  haircutSource: "room" | "policy";
  /** Value after encumbrances and haircut. */
  eligible: string;
  /** The lien the desk would take. */
  lien: {pt: string; en: string};
  selected: boolean;
};

export type CollateralPackage = {
  target: {coverage: string; amount: string; required: string};
  lines: PackageLine[];
  /** Eligible value of the selected lines. */
  coverageAchieved: string;
  eligibleSelected: string;
  sufficient: boolean;
  /** What would close the gap, when the package does not reach the target. */
  shortfall: string | null;
  notes: {pt: string; en: string}[];
};

/**
 * The desk's policy haircuts, by class. Written as data: a credit professional who disagrees
 * changes one number and every package is redesigned the same way.
 */
export const policyHaircuts: Record<CollateralClass, {haircut: string; rank: number; lien: {pt: string; en: string}; whyPt: string; whyEn: string}> = {
  financial: {haircut: "0.05", rank: 1, lien: {pt: "cessão fiduciária de aplicações financeiras", en: "fiduciary assignment of financial investments"}, whyPt: "Liquidez imediata; o desconto cobre apenas a variação de marcação.", whyEn: "Immediate liquidity; the discount covers marking only."},
  receivables: {haircut: "0.30", rank: 2, lien: {pt: "cessão fiduciária de recebíveis, com cobertura mínima e conta vinculada", en: "fiduciary assignment of receivables, with minimum coverage and a blocked account"}, whyPt: "Inadimplência, diluição e concentração; a prática de mercado pede 120% a 150% de cobertura.", whyEn: "Delinquency, dilution and concentration; market practice asks for 120% to 150% coverage."},
  property: {haircut: "0.40", rank: 3, lien: {pt: "alienação fiduciária de imóvel, com laudo", en: "fiduciary lien on property, with an appraisal"}, whyPt: "Tempo e custo de execução; o laudo define a base, a liquidez define o desconto.", whyEn: "Time and cost of enforcement; the appraisal sets the base, liquidity sets the discount."},
  vehicles: {haircut: "0.40", rank: 4, lien: {pt: "alienação fiduciária de veículos, com gravame no Detran", en: "fiduciary lien on vehicles, registered with the vehicle registry"}, whyPt: "Mercado secundário líquido, depreciação rápida.", whyEn: "Liquid secondary market, fast depreciation."},
  equipment: {haircut: "0.50", rank: 5, lien: {pt: "alienação fiduciária de máquinas e equipamentos", en: "fiduciary lien on machinery and equipment"}, whyPt: "Valor de liquidação muito abaixo do contábil quando o bem é específico.", whyEn: "Liquidation value well below book when the asset is specific."},
  inventory: {haircut: "0.50", rank: 6, lien: {pt: "alienação fiduciária de estoques, com monitoramento", en: "fiduciary lien on inventory, with monitoring"}, whyPt: "Gira, perece e some; só entra com monitoramento periódico.", whyEn: "It turns over, perishes and disappears; it enters only with periodic monitoring."},
  shares: {haircut: "0.60", rank: 7, lien: {pt: "alienação fiduciária de quotas ou ações da operadora", en: "fiduciary lien on the operating company's shares"}, whyPt: "Vale o que a empresa vale no dia da execução; é controle, não caixa.", whyEn: "Worth what the company is worth on the day of enforcement; it is control, not cash."},
  guarantee: {haircut: "1.00", rank: 8, lien: {pt: "aval ou fiança dos controladores", en: "personal guarantee of the controlling shareholders"}, whyPt: "Alinha incentivos; não conta como cobertura.", whyEn: "Aligns incentives; does not count as coverage."},
  other: {haircut: "0.70", rank: 9, lien: {pt: "garantia a classificar", en: "security to be classified"}, whyPt: "Classe não reconhecida; entra com desconto de desconhecido até ser nomeada.", whyEn: "Unrecognised class; enters at an unknown's discount until named."},
};

const d = (value: string | number): Decimal => new Decimal(value);

export function designCollateralPackage(input: {assets: CollateralAsset[]; amount: string; coverage?: string}): CollateralPackage {
  const amount = d(input.amount);
  const coverage = d(input.coverage ?? "1.3");
  const required = amount.times(coverage);

  const lines: PackageLine[] = input.assets.map((asset) => {
    const policy = policyHaircuts[asset.type];
    const haircut = asset.haircut !== undefined ? d(asset.haircut) : d(policy.haircut);
    const free = Decimal.max(d(asset.value).minus(d(asset.encumbered ?? "0")), 0);
    return {
      asset,
      haircut: haircut.toFixed(4),
      haircutSource: asset.haircut !== undefined ? "room" : "policy",
      eligible: free.times(new Decimal(1).minus(haircut)).toFixed(2),
      lien: policy.lien,
      selected: false,
    };
  });

  // Best quality first, then the largest eligible value: the package a lender signs is the one
  // with the fewest, most liquid liens, not the one with everything pledged.
  const ordered = [...lines].sort((a, b) => policyHaircuts[a.asset.type].rank - policyHaircuts[b.asset.type].rank || d(b.eligible).minus(a.eligible).toNumber());
  let running = new Decimal(0);
  for (const line of ordered) {
    if (running.gte(required)) break;
    if (d(line.eligible).lte(0)) continue;
    line.selected = true;
    running = running.plus(line.eligible);
  }
  const sufficient = running.gte(required);
  const notes: {pt: string; en: string}[] = [];
  const unappraised = lines.filter((line) => line.selected && (line.asset.type === "property" || line.asset.type === "equipment") && !line.asset.appraised);
  if (unappraised.length > 0) {
    notes.push({
      pt: `${unappraised.length} ativo(s) entram pelo valor contábil sem laudo: ${unappraised.map((line) => line.asset.description).join(", ")}. Um laudo muda a base e costuma mudar a cobertura.`,
      en: `${unappraised.length} asset(s) enter at book value without an appraisal: ${unappraised.map((line) => line.asset.description).join(", ")}. An appraisal changes the base and usually the coverage.`,
    });
  }
  const guaranteeOnly = lines.some((line) => line.asset.type === "guarantee");
  if (guaranteeOnly) notes.push({pt: "Aval dos controladores acompanha o pacote e não conta como cobertura.", en: "The controllers' guarantee accompanies the package and does not count as coverage."});
  if (!sufficient) {
    notes.push({
      pt: `O inventário cobre ${running.div(amount).toFixed(2).replace(".", ",")}x do pedido contra ${coverage.toFixed(2).replace(".", ",")}x exigidos: faltam ${required.minus(running).toFixed(0)} de valor elegível. Ou a empresa nomeia outro ativo, ou o tíquete cai, ou a cobertura se completa com garantia de terceiro.`,
      en: `The inventory covers ${running.div(amount).toFixed(2)}x of the ask against ${coverage.toFixed(2)}x required: ${required.minus(running).toFixed(0)} of eligible value is missing. Either the company names another asset, the ticket comes down, or a third-party guarantee completes the coverage.`,
    });
  }
  return {
    target: {coverage: coverage.toFixed(4), amount: amount.toFixed(2), required: required.toFixed(2)},
    lines: ordered,
    coverageAchieved: amount.gt(0) ? running.div(amount).toFixed(4) : "0",
    eligibleSelected: running.toFixed(2),
    sufficient,
    shortfall: sufficient ? null : required.minus(running).toFixed(2),
    notes,
  };
}

packages/deal-structure/src/operation.ts.content:
import {
  calculateExcessFundingCarry,
  calculateIncrementalWorkingCapital,
  calculateProFormaPosition,
  calculateTransactionNeed,
  reconcileSourcesAndUses,
  testDisbursementCoverage,
} from "@offroad/financial-core";
import type {DebtTruthSet, FinancialTruthSet, ReconciledFact} from "@offroad/reconciliation";
import Decimal from "decimal.js";

import type {CapacityAssessment} from "./capacity";

export const operationTruthVersion = "2026.09.08-v2";
type Status = "completed" | "partial" | "blocked" | "not_computable" | "not_applicable";
type EvidenceLink = {fieldPath: string; sourceDocument: string; anchor?: unknown};
type Line = {
  id: string;
  side: "source" | "use";
  item: string;
  amount: string;
  entity: string | null;
  currency: string;
  date: string | null;
  tranche: string | null;
  condition: "available" | "conditional" | "not_confirmed";
  evidence: EvidenceLink[];
};

export type OperationPolicies = {
  version: string;
  sizingMateriality?: string;
  residualTolerance?: string;
  authorizedBuffer?: string;
  annualDebtCost?: string;
  annualCashYield?: string;
  minimumDscr?: string;
  generalPurposeCap?: string;
};

export type OperationTruthSet = {
  version: string;
  policyVersion: string;
  status: "complete" | "partial" | "blocked";
  request: {amount: string | null; purpose: string | null; termMonths: number | null; evidence: EvidenceLink[]};
  calculatedNeed: {value: string; trace: Array<{label: string; value: string}>; divergence: string | null; status: Status} | null;
  sourcesAndUses: {lines: Line[]; totalSources: string; totalUses: string; difference: string; status: "pass" | "fail" | "not_computable"};
  proForma: {grossDebt: string; unrestrictedCash: string; netDebt: string; leverage: string | null; dayOneCovenantConflict: boolean | null} | null;
  scenarioCapacity: Array<{scenario: string; coverage: string | null; deficit: string; status: "pass" | "fail" | "not_computable"}>;
  effects: {solves: string[]; doesNotTouch: string[]; creates: string[]};
  incrementalWorkingCapital: ReturnType<typeof calculateIncrementalWorkingCapital> | null;
  excessFunding: {excess: string; annualCarry: string} | null;
  tranches: Array<{id: string; amount: string | null; milestone: string | null; evidence: string | null; attestor: string | null; releaseDays: number | null; status: Status}>;
  conditionsPrecedent: Array<{id: string; condition: string; owner: string | null; evidence: string | null; deadline: string | null; status: string | null}>;
  bridgeAndTakeout: {bridgeAmount: string | null; takeout: string | null; failureRisk: string | null; planB: string | null; status: Status};
  disbursementSchedule: ReturnType<typeof testDisbursementCoverage> | null;
  waitAnalysis: {milestone: string | null; date: string | null; waitingCost: string | null; estimatedGain: string | null; decision: string | null; status: Status};
  mixedUses: Array<{category: "productive" | "remediation" | "reinforcement" | "other"; amount: string; description: string}>;
  declaredVersion: {version: string | null; confirmedAt: string | null; stale: boolean; materialTerms: string[]};
  exceptions: Array<{id: string; severity: "medium" | "high" | "critical"; message: string; affectedFields: string[]}>;
  missingInputs: string[];
  procedureCoverage: Array<{procedureId: `OP-${string}`; status: Status; outputCount: number; evidenceCount: number; missingInputs: string[]; exceptionIds: string[]}>;
};

const source = (fact: ReconciledFact): EvidenceLink => ({
  fieldPath: fact.key.fieldPath,
  sourceDocument: fact.accepted.sourceDocument,
  ...(fact.accepted.anchor !== undefined ? {anchor: fact.accepted.anchor} : {}),
});
const asNumber = (value: string | undefined) => value !== undefined && Number.isFinite(Number(value)) ? value : undefined;
const asInteger = (value: string | undefined) => value !== undefined && Number.isInteger(Number(value)) ? Number(value) : null;
const sum = (values: Array<string | undefined>) => values.reduce((total, value) => total.plus(asNumber(value) ?? 0), new Decimal(0)).toFixed();

export function buildOperationTruthSet(input: {
  facts: readonly ReconciledFact[];
  financialTruth: FinancialTruthSet;
  debtTruth: DebtTruthSet;
  capacity: CapacityAssessment | null;
  requestedAmount?: string;
  requestedTermMonths?: number;
  referenceDate: string;
  policies?: OperationPolicies;
}): OperationTruthSet {
  const facts = input.facts;
  const fact = (path: string) => facts.find((candidate) => candidate.key.fieldPath === path);
  const value = (path: string) => fact(path)?.value;
  const indexed = (prefix: string) => [...new Set(facts.flatMap((candidate) => candidate.key.fieldPath.match(new RegExp(`^${prefix.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\.(\\d+)\\.`))?.[1] ?? []))]
    .sort((left, right) => Number(left) - Number(right));
  const evidenceOf = (...paths: string[]) => paths.flatMap((path) => fact(path) ? [source(fact(path)!)] : []);
  const missing = new Set<string>();
  const exceptions: OperationTruthSet["exceptions"] = [];
  const policy = input.policies ?? {version: "required_missing"};
  const requested = asNumber(input.requestedAmount ?? value("transaction.requested_amount"));
  if (!requested) missing.add("transaction.requested_amount");

  const lines: Line[] = indexed("transaction.sources_and_uses").flatMap((index) => {
    const base = `transaction.sources_and_uses.${index}`;
    const side = value(`${base}.side`);
    const amount = asNumber(value(`${base}.amount`));
    const item = value(`${base}.item`);
    const normalizedSide = side === "sources" ? "source" : side === "uses" ? "use" : side;
    if ((normalizedSide !== "source" && normalizedSide !== "use") || !amount || !item) return [];
    return [{
      id: index, side: normalizedSide, item, amount,
      entity: value(`${base}.entity`) ?? null,
      currency: value(`${base}.currency`) ?? value("transaction.currency") ?? "BRL",
      date: value(`${base}.date`) ?? null,
      tranche: value(`${base}.tranche`) ?? null,
      condition: value(`${base}.condition`) === "available" || value(`${base}.condition`) === "conditional" ? value(`${base}.condition`) as "available" | "conditional" : "not_confirmed",
      evidence: evidenceOf(`${base}.amount`, `${base}.item`, `${base}.side`),
    }];
  });
  const sourceLines = lines.filter((line) => line.side === "source");
  const useLines = lines.filter((line) => line.side === "use");
  const tolerance = policy.residualTolerance ?? "0";
  const tie = sourceLines.length && useLines.length
    ? reconcileSourcesAndUses({sources: sourceLines, uses: useLines, tolerance})
    : null;
  if (!sourceLines.length || !useLines.length) missing.add("transaction.sources_and_uses");
  if (tie?.status === "fail") exceptions.push({id: "sources-uses-mismatch", severity: "critical", message: "Sources and uses do not tie within policy tolerance.", affectedFields: lines.map((line) => `transaction.sources_and_uses.${line.id}`)});
  const unmatchedTotalSources = sum(sourceLines.map((line) => line.amount));
  const unmatchedTotalUses = sum(useLines.map((line) => line.amount));
  const sourcesAndUses = tie ? {...tie, lines} : {
    lines,
    totalSources: unmatchedTotalSources,
    totalUses: unmatchedTotalUses,
    difference: new Decimal(unmatchedTotalSources).minus(unmatchedTotalUses).toFixed(),
    status: "not_computable" as const,
  };

  const capex = asNumber(value("project.total_cost")) ?? sum(useLines.filter((line) => /capex|expans|aquisi|equip|obra/i.test(line.item)).map((line) => line.amount));
  const incrementalWcValue = asNumber(value("transaction.incremental_working_capital")) ?? sum(useLines.filter((line) => /capital de giro|working capital|ncg/i.test(line.item)).map((line) => line.amount));
  const transactionCosts = asNumber(value("transaction.transaction_costs")) ?? sum(useLines.filter((line) => /fee|custo|despesa da opera/i.test(line.item)).map((line) => line.amount));
  const executionBuffer = asNumber(value("transaction.execution_buffer"));
  const selfFunding = sum([value("project.company_cash"), value("project.shareholder_equity"), value("transaction.self_funding")]);
  let calculatedNeed: OperationTruthSet["calculatedNeed"] = null;
  if (capex && incrementalWcValue && transactionCosts && executionBuffer !== undefined) {
    const calculation = calculateTransactionNeed({capex, incrementalWorkingCapital: incrementalWcValue, transactionCosts, executionBuffer, selfFunding});
    const divergence = requested ? new Decimal(requested).minus(calculation.calculatedNeed).toFixed() : null;
    calculatedNeed = {value: calculation.calculatedNeed, trace: calculation.trace, divergence, status: requested && policy.sizingMateriality !== undefined ? "completed" : "partial"};
    if (requested && policy.sizingMateriality !== undefined && new Decimal(divergence!).abs().gt(policy.sizingMateriality)) {
      exceptions.push({id: "request-need-divergence", severity: "high", message: "The stated request differs materially from calculated need.", affectedFields: ["transaction.requested_amount"]});
    }
  } else {
    for (const required of [!capex && "project.total_cost", !incrementalWcValue && "transaction.incremental_working_capital", !transactionCosts && "transaction.transaction_costs", executionBuffer === undefined && "transaction.execution_buffer"].filter(Boolean) as string[]) missing.add(required);
  }

  const workingCapitalRows = indexed("transaction.incremental_working_capital_schedule").flatMap((index) => {
    const base = `transaction.incremental_working_capital_schedule.${index}`;
    const row = ["period", "incremental_revenue", "incremental_cogs", "dso_days", "dio_days", "dpo_days", "taxes_and_other_operating", "days_in_period"].map((name) => value(`${base}.${name}`));
    if (row.some((item) => item === undefined)) return [];
    return [{period: row[0]!, incrementalRevenue: row[1]!, incrementalCogs: row[2]!, dsoDays: row[3]!, dioDays: row[4]!, dpoDays: row[5]!, taxesAndOtherOperating: row[6]!, daysInPeriod: row[7]!}];
  });
  const incrementalWorkingCapital = workingCapitalRows.length ? calculateIncrementalWorkingCapital(workingCapitalRows) : null;

  const latestAdjustedEbitda = [...input.financialTruth.statements]
    .filter((statement) => statement.adjustedEbitda !== null)
    .sort((left, right) => right.period.localeCompare(left.period))[0]?.adjustedEbitda ?? undefined;
  const proFormaMissing = new Set<string>();
  if (!requested) proFormaMissing.add("transaction.requested_amount");
  if (input.debtTruth.views.balanceBasis !== "reported_instruments") proFormaMissing.add("debt.balance_provenance");
  if (input.debtTruth.views.cashBasis !== "reported") proFormaMissing.add("debt.unrestricted_cash");
  if (!input.debtTruth.instruments?.length) proFormaMissing.add("debt.instruments");
  for (const instrument of input.debtTruth.instruments ?? []) {
    if (instrument.principalBasis !== "reported_principal") proFormaMissing.add(`${instrument.id}.principal`);
  }
  if (input.debtTruth.status === "blocked" || input.debtTruth.exceptions?.some((exception) => exception.blocksExternalOutputs)) {
    for (const field of input.debtTruth.missingInputs ?? []) proFormaMissing.add(field);
    proFormaMissing.add("debt.unblocked_snapshot");
  }
  for (const field of proFormaMissing) missing.add(field);
  const proForma = requested && proFormaMissing.size === 0 ? calculateProFormaPosition({
    grossDebt: input.debtTruth.views.grossFinancialDebt,
    unrestrictedCash: input.debtTruth.views.unrestrictedCash,
    newDebt: requested,
    refinancedDebt: asNumber(value("transaction.refinanced_debt")) ?? "0",
    feesPaidFromCash: asNumber(value("transaction.fees_paid_from_cash")) ?? "0",
    cashContribution: asNumber(value("project.company_cash")) ?? "0",
    ...(latestAdjustedEbitda ? {adjustedEbitda: latestAdjustedEbitda} : {}),
  }) : null;
  const covenantConflict = input.debtTruth.covenants.some((covenant) => covenant.status === "fail");
  const proFormaWithCovenant = proForma ? {...proForma, dayOneCovenantConflict: input.debtTruth.covenants.length ? covenantConflict : null} : null;
  if (covenantConflict) exceptions.push({id: "day-one-covenant-conflict", severity: "critical", message: "The pro forma structure conflicts with an existing covenant test.", affectedFields: ["debt.covenants"]});

  const scenarioCapacity = indexed("transaction.capacity_scenarios").flatMap((index) => {
    const base = `transaction.capacity_scenarios.${index}`;
    const scenario = value(`${base}.name`);
    const coverage = asNumber(value(`${base}.dscr`)) ?? null;
    const deficit = asNumber(value(`${base}.liquidity_deficit`));
    if (!scenario || deficit === undefined) return [];
    return [{scenario, coverage, deficit, status: coverage === null || policy.minimumDscr === undefined ? "not_computable" as const : new Decimal(coverage).gte(policy.minimumDscr) && new Decimal(deficit).eq(0) ? "pass" as const : "fail" as const}];
  });

  const effects = {
    solves: indexed("transaction.effects.solves").map((index) => value(`transaction.effects.solves.${index}.description`)).filter((item): item is string => Boolean(item)),
    doesNotTouch: indexed("transaction.effects.does_not_touch").map((index) => value(`transaction.effects.does_not_touch.${index}.description`)).filter((item): item is string => Boolean(item)),
    creates: indexed("transaction.effects.creates").map((index) => value(`transaction.effects.creates.${index}.description`)).filter((item): item is string => Boolean(item)),
  };
  const excessFunding = requested && calculatedNeed && policy.authorizedBuffer !== undefined && policy.annualDebtCost !== undefined && policy.annualCashYield !== undefined
    ? calculateExcessFundingCarry({requested, calculatedNeed: calculatedNeed.value, authorizedBuffer: policy.authorizedBuffer, annualDebtCost: policy.annualDebtCost, annualCashYield: policy.annualCashYield})
    : null;

  const tranches = indexed("transaction.tranches").map((index) => {
    const base = `transaction.tranches.${index}`;
    const milestone = value(`${base}.milestone`) ?? null;
    const evidence = value(`${base}.evidence`) ?? null;
    const attestor = value(`${base}.attestor`) ?? null;
    const releaseDays = asInteger(value(`${base}.release_days`));
    const objective = Boolean(milestone && evidence && attestor && releaseDays !== null);
    return {id: index, amount: asNumber(value(`${base}.amount`)) ?? null, milestone, evidence, attestor, releaseDays, status: objective ? "completed" as const : "blocked" as const};
  });
  const conditionsPrecedent = indexed("transaction.conditions_precedent").flatMap((index) => {
    const base = `transaction.conditions_precedent.${index}`;
    const condition = value(`${base}.condition`);
    return condition ? [{id: index, condition, owner: value(`${base}.owner`) ?? null, evidence: value(`${base}.evidence`) ?? null, deadline: value(`${base}.deadline`) ?? null, status: value(`${base}.status`) ?? null}] : [];
  });
  const bridgeAmount = asNumber(value("transaction.bridge.amount")) ?? null;
  const bridgeAndTakeout = {
    bridgeAmount,
    takeout: value("transaction.bridge.takeout") ?? null,
    failureRisk: value("transaction.bridge.takeout_failure_risk") ?? null,
    planB: value("transaction.bridge.plan_b") ?? null,
    status: !bridgeAmount ? "not_applicable" as const : value("transaction.bridge.takeout") && value("transaction.bridge.plan_b") ? "completed" as const : "blocked" as const,
  };
  if (bridgeAndTakeout.status === "blocked") exceptions.push({id: "bridge-without-takeout", severity: "critical", message: "Bridge financing lacks a named take-out or plan B.", affectedFields: ["transaction.bridge"]});

  const scheduleRows = indexed("transaction.disbursement_schedule").flatMap((index) => {
    const base = `transaction.disbursement_schedule.${index}`;
    const period = value(`${base}.period`);
    const sources = asNumber(value(`${base}.sources`));
    const uses = asNumber(value(`${base}.uses`));
    if (!period || sources === undefined || uses === undefined) return [];
    return [{period, openingLiquidity: asNumber(value(`${base}.opening_liquidity`)) ?? "0", scheduledSources: sources, scheduledUses: uses}];
  });
  const disbursementSchedule = scheduleRows.length ? testDisbursementCoverage(scheduleRows) : null;
  if (disbursementSchedule?.status === "fail") exceptions.push({id: "uncovered-disbursement-period", severity: "critical", message: "At least one period has an uncovered funding requirement.", affectedFields: ["transaction.disbursement_schedule"]});
  const waitAnalysis = {
    milestone: value("transaction.wait.milestone") ?? null,
    date: value("transaction.wait.date") ?? null,
    waitingCost: asNumber(value("transaction.wait.cost")) ?? null,
    estimatedGain: asNumber(value("transaction.wait.estimated_gain")) ?? null,
    decision: value("transaction.wait.decision") ?? null,
    status: value("transaction.wait.decision") ? "completed" as const : "not_applicable" as const,
  };
  const mixedUses = indexed("transaction.use_blocks").flatMap((index) => {
    const base = `transaction.use_blocks.${index}`;
    const category = value(`${base}.category`);
    const amount = asNumber(value(`${base}.amount`));
    const description = value(`${base}.description`);
    const normalizedCategory: "productive" | "remediation" | "reinforcement" | "other" = category === "productive" || category === "remediation" || category === "reinforcement" ? category : "other";
    return amount && description ? [{category: normalizedCategory, amount, description}] : [];
  });
  const version = value("transaction.declared_version") ?? null;
  const confirmedAt = value("transaction.declared_version_confirmed_at") ?? null;
  const stale = Boolean(value("transaction.declared_version_stale") === "true" || (confirmedAt && confirmedAt < input.referenceDate && value("transaction.material_change_since_confirmation") === "true"));
  const declaredVersion = {version, confirmedAt, stale, materialTerms: [requested, value("transaction.purpose"), input.requestedTermMonths?.toString() ?? value("transaction.desired_term_months"), value("transaction.preferred_structure")].filter((item): item is string => Boolean(item))};
  if (stale) exceptions.push({id: "stale-operation-version", severity: "critical", message: "The declared operation changed materially after its last confirmation.", affectedFields: ["transaction.declared_version"]});

  const evidenceCounts: Record<`OP-${string}`, number> = {
    "OP-01": evidenceOf("transaction.requested_amount", "project.total_cost", "transaction.incremental_working_capital", "transaction.transaction_costs", "transaction.execution_buffer", "project.company_cash", "project.shareholder_equity", "transaction.self_funding").length,
    "OP-02": lines.reduce((count, line) => count + line.evidence.length, 0),
    "OP-03": evidenceOf("transaction.requested_amount", "transaction.refinanced_debt", "transaction.fees_paid_from_cash", "project.company_cash").length,
    "OP-04": indexed("transaction.capacity_scenarios").reduce((count, index) => count + evidenceOf(`transaction.capacity_scenarios.${index}.name`, `transaction.capacity_scenarios.${index}.dscr`, `transaction.capacity_scenarios.${index}.liquidity_deficit`).length, 0),
    "OP-05": ["solves", "does_not_touch", "creates"].reduce((count, group) => count + indexed(`transaction.effects.${group}`).reduce((subtotal, index) => subtotal + evidenceOf(`transaction.effects.${group}.${index}.description`).length, 0), 0),
    "OP-06": indexed("transaction.incremental_working_capital_schedule").reduce((count, index) => count + facts.filter((candidate) => candidate.key.fieldPath.startsWith(`transaction.incremental_working_capital_schedule.${index}.`)).length, 0),
    "OP-07": evidenceOf("transaction.requested_amount").length,
    "OP-08": indexed("transaction.tranches").reduce((count, index) => count + facts.filter((candidate) => candidate.key.fieldPath.startsWith(`transaction.tranches.${index}.`)).length, 0),
    "OP-09": indexed("transaction.conditions_precedent").reduce((count, index) => count + facts.filter((candidate) => candidate.key.fieldPath.startsWith(`transaction.conditions_precedent.${index}.`)).length, 0),
    "OP-10": facts.filter((candidate) => candidate.key.fieldPath.startsWith("transaction.bridge.")).length,
    "OP-11": indexed("transaction.disbursement_schedule").reduce((count, index) => count + facts.filter((candidate) => candidate.key.fieldPath.startsWith(`transaction.disbursement_schedule.${index}.`)).length, 0),
    "OP-12": facts.filter((candidate) => candidate.key.fieldPath.startsWith("transaction.wait.")).length,
    "OP-13": indexed("transaction.use_blocks").reduce((count, index) => count + facts.filter((candidate) => candidate.key.fieldPath.startsWith(`transaction.use_blocks.${index}.`)).length, 0),
    "OP-14": evidenceOf("transaction.declared_version", "transaction.declared_version_confirmed_at", "transaction.requested_amount", "transaction.purpose", "transaction.desired_term_months", "transaction.preferred_structure").length,
  };
  const exceptionOwners: Record<string, `OP-${string}`[]> = {
    "request-need-divergence": ["OP-01"],
    "sources-uses-mismatch": ["OP-02"],
    "day-one-covenant-conflict": ["OP-03"],
    "bridge-without-takeout": ["OP-10"],
    "uncovered-disbursement-period": ["OP-11"],
    "stale-operation-version": ["OP-14"],
  };
  const coverageSpec: Array<[`OP-${string}`, Status, number, string[]]> = [
    ["OP-01", calculatedNeed?.status ?? "not_computable", calculatedNeed ? 1 : 0, calculatedNeed ? [] : ["complete calculated need"]],
    ["OP-02", sourcesAndUses.status === "pass" ? "completed" : sourcesAndUses.status === "fail" ? "blocked" : "not_computable", lines.length, sourceLines.length && useLines.length ? [] : ["complete sources and uses"]],
    ["OP-03", proFormaWithCovenant ? covenantConflict ? "blocked" : "completed" : "not_computable", proFormaWithCovenant ? 1 : 0, proFormaWithCovenant ? [] : [...proFormaMissing].sort()],
    ["OP-04", scenarioCapacity.length ? scenarioCapacity.some((item) => item.status === "fail") ? "blocked" : scenarioCapacity.every((item) => item.status === "pass") ? "completed" : "partial" : "not_computable", scenarioCapacity.length, scenarioCapacity.length ? [] : ["scenario liquidity coverage"]],
    ["OP-05", Object.values(effects).every((items) => items.length) ? "completed" : "partial", Object.values(effects).flat().length, Object.values(effects).every((items) => items.length) ? [] : ["three explicit effect lists"]],
    ["OP-06", incrementalWorkingCapital ? "completed" : "not_computable", incrementalWorkingCapital?.periods.length ?? 0, incrementalWorkingCapital ? [] : ["period working capital drivers"]],
    ["OP-07", excessFunding ? "completed" : "not_computable", excessFunding ? 1 : 0, excessFunding ? [] : ["approved carry policy"]],
    ["OP-08", tranches.length ? tranches.some((item) => item.status === "blocked") ? "blocked" : "completed" : "not_applicable", tranches.length, []],
    ["OP-09", conditionsPrecedent.length ? conditionsPrecedent.every((item) => item.owner && item.evidence && item.deadline && item.status) ? "completed" : "partial" : "not_computable", conditionsPrecedent.length, conditionsPrecedent.length ? [] : ["conditions precedent catalogue"]],
    ["OP-10", bridgeAndTakeout.status, bridgeAmount ? 1 : 0, bridgeAndTakeout.status === "blocked" ? ["take-out and plan B"] : []],
    ["OP-11", disbursementSchedule ? disbursementSchedule.status === "pass" ? "completed" : "blocked" : "not_computable", disbursementSchedule?.periods.length ?? 0, disbursementSchedule ? [] : ["draw and works schedule"]],
    ["OP-12", waitAnalysis.status, waitAnalysis.status === "completed" ? 1 : 0, []],
    ["OP-13", mixedUses.length ? "completed" : "not_computable", mixedUses.length, mixedUses.length ? [] : ["uses classified by economic purpose"]],
    ["OP-14", version && confirmedAt && !stale ? "completed" : stale ? "blocked" : "partial", declaredVersion.materialTerms.length, version && confirmedAt ? [] : ["confirmed operation version"]],
  ];
  const procedureCoverage = coverageSpec.map(([procedureId, status, outputCount, procedureMissing]) => ({
    procedureId,
    status,
    outputCount,
    evidenceCount: evidenceCounts[procedureId] ?? 0,
    missingInputs: procedureMissing,
    exceptionIds: exceptions.filter((item) => exceptionOwners[item.id]?.includes(procedureId)).map((item) => item.id),
  }));
  const blocking = exceptions.some((item) => item.severity === "critical");
  return {
    version: operationTruthVersion, policyVersion: policy.version,
    status: blocking ? "blocked" : procedureCoverage.every((item) => item.status === "completed" || item.status === "not_applicable") ? "complete" : "partial",
    request: {amount: requested ?? null, purpose: value("transaction.purpose") ?? null, termMonths: input.requestedTermMonths ?? asInteger(value("transaction.desired_term_months")), evidence: evidenceOf("transaction.requested_amount", "transaction.purpose")},
    calculatedNeed, sourcesAndUses, proForma: proFormaWithCovenant, scenarioCapacity, effects, incrementalWorkingCapital, excessFunding, tranches, conditionsPrecedent, bridgeAndTakeout, disbursementSchedule, waitAnalysis, mixedUses, declaredVersion, exceptions, missingInputs: [...missing].sort(), procedureCoverage,
  };
}

packages/deal-structure/src/structure.ts.content:
import {archetype, type ArchetypeId, type InstrumentVerdict} from "@offroad/credit-playbook";
import {
  buildDebtServiceSchedule,
  calculateCoverageSeries,
  calculateCovenantHeadroom,
  maturityConcentration,
  type GraceInterest,
  type InterestConvention,
  type RepaymentFormat,
} from "@offroad/financial-core";
import type {DebtTruthSet, FinancialTruthSet, ReconciledFact} from "@offroad/reconciliation";
import Decimal from "decimal.js";

import type {CapacityAssessment} from "./capacity";
import type {CollateralPackage} from "./collateral";
import type {OperationTruthSet} from "./operation";
import type {IndicativeTermSheet} from "./termsheet";

export const structureTruthVersion = "2026.08.29-v2";
type Status = "completed" | "partial" | "blocked" | "not_computable" | "not_applicable";
type EvidenceLink = {fieldPath: string; sourceDocument: string; anchor?: unknown};

export type StructurePolicies = {
  version: string;
  annualSizingRate?: string;
  rateConvention?: InterestConvention;
  amortizationFormat?: RepaymentFormat;
  graceInterest?: GraceInterest;
  balloonPercent?: string;
  minimumDscr?: string;
  minimumCovenantHeadroom?: string;
  maturityConcentrationLimit?: string;
  constructionDelayMonths?: number;
  reserveMonths?: string;
  collateralPolicyVersion?: string;
  minimumCollateralCoverage?: string;
  matchedTicketMin?: string;
  matchedTicketMax?: string;
};

export type StructureProcedureResult = {
  procedureId: `ES-${string}`;
  status: Status;
  result: Record<string, unknown> | null;
  outputCount: number;
  evidenceCount: number;
  missingInputs: string[];
  exceptionIds: string[];
};

export type StructureTruthSet = {
  version: string;
  policyVersion: string;
  status: "complete" | "partial" | "blocked";
  proposal: {
    instrument: string | null;
    amount: string | null;
    termMonths: number | null;
    graceMonths: number | null;
    amortizationFormat: RepaymentFormat | null;
    bindingConstraint: string | null;
    minimumDownsideDscr: string | null;
    collateralCoverage: string | null;
    dayOneCompatible: boolean | null;
  };
  capacityEnvelope: {ceilings: Array<{id: string; amount: string; basis: string}>; amount: string | null; bindingConstraint: string | null};
  repayment: {
    origin: "declared" | "policy" | "house_playbook_candidate" | null;
    schedule: ReturnType<typeof buildDebtServiceSchedule> | null;
    coverage: ReturnType<typeof calculateCoverageSeries>;
  };
  security: {
    package: CollateralPackage | null;
    mechanics: Array<{asset: string; type: string; procedureId: string; status: Status; missingInputs: string[]}>;
  };
  dayOne: {covenants: boolean | null; negativePledge: boolean | null; corporateAuthority: boolean | null; maturityWall: boolean | null; passes: boolean | null};
  finalSizing: {requested: string | null; calculated: string | null; envelope: string | null; proposed: string | null; ticketCompatible: boolean | null; rationale: string[]};
  exceptions: Array<{id: string; severity: "medium" | "high" | "critical"; message: string; affectedProcedures: `ES-${string}`[]}>;
  missingInputs: string[];
  procedureCoverage: StructureProcedureResult[];
};

const number = (value: string | undefined | null) => value !== undefined && value !== null && value.trim() !== "" && Number.isFinite(Number(value)) ? value : undefined;
const integer = (value: string | undefined | null) => number(value) !== undefined && Number.isInteger(Number(value)) ? Number(value) : null;
const bool = (value: string | undefined) => value === undefined ? null : ["true","yes","sim","1","pass","compliant"].includes(value.toLowerCase()) ? true : ["false","no","não","nao","0","fail","conflict"].includes(value.toLowerCase()) ? false : null;
const minimum = (values: Array<string | undefined | null>) => {
  const present = values.flatMap((value) => number(value) === undefined ? [] : [new Decimal(value!)]);
  return present.length ? present.reduce((lowest, value) => value.lt(lowest) ? value : lowest).toFixed() : null;
};
const firstRecognizedFormat = (labels: readonly string[]): RepaymentFormat | null => {
  for (const label of labels) {
    const normalized = label.toLowerCase();
    if (/\bsac\b/.test(normalized)) return "sac";
    if (/\bprice\b/.test(normalized)) return "price";
    if (/bullet/.test(normalized)) return "bullet";
    if (/bal[aã]o/.test(normalized)) return "balloon";
  }
  return null;
};

export function buildStructureTruthSet(input: {
  archetypeId: ArchetypeId;
  facts: readonly ReconciledFact[];
  financialTruth: FinancialTruthSet;
  debtTruth: DebtTruthSet;
  operationTruth: OperationTruthSet;
  capacity: CapacityAssessment | null;
  termSheet: IndicativeTermSheet | null;
  collateral: CollateralPackage | null;
  instruments: readonly InstrumentVerdict[];
  referenceDate: string;
  policies?: StructurePolicies;
}): StructureTruthSet {
  const definition = archetype(input.archetypeId);
  const policy = input.policies ?? {version:"required_missing"};
  const facts = input.facts;
  const fact = (path:string)=>facts.find((candidate)=>candidate.key.fieldPath===path);
  const value = (path:string)=>fact(path)?.value;
  const indexed = (prefix:string)=>[...new Set(facts.flatMap((candidate)=>candidate.key.fieldPath.match(new RegExp(`^${prefix.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")}\\.(\\d+)\\.`))?.[1]??[]))].sort((a,b)=>Number(a)-Number(b));
  const evidence = (...paths:string[]):EvidenceLink[]=>paths.flatMap((path)=>fact(path)?[{fieldPath:path,sourceDocument:fact(path)!.accepted.sourceDocument,...(fact(path)!.accepted.anchor!==undefined?{anchor:fact(path)!.accepted.anchor}: {})}]:[]);
  const evidencePrefix = (prefix:string)=>facts.filter((candidate)=>candidate.key.fieldPath.startsWith(prefix)).length;
  const missing = new Set<string>();
  const exceptions: StructureTruthSet["exceptions"] = [];

  const requested = input.operationTruth.request.amount;
  const calculated = input.operationTruth.calculatedNeed?.value ?? null;
  const capacityCeilings: Array<{id: string; amount: string; basis: string}> = input.capacity?.walls.flatMap((wall)=>wall.amount===null?[]:[{id:wall.id,amount:wall.amount,basis:"capacity_assessment"}]) ?? [];
  const covenantCeiling = number(value("structure.capacity.covenant_limit"));
  if (covenantCeiling) capacityCeilings.push({id:"existing_covenant",amount:covenantCeiling,basis:"reconciled_fact"});
  const envelopeAmount = minimum(capacityCeilings.map((ceiling)=>ceiling.amount));
  const bindingConstraint = envelopeAmount ? capacityCeilings.find((ceiling)=>new Decimal(ceiling.amount).eq(envelopeAmount))?.id ?? null : null;
  if (!capacityCeilings.length) missing.add("structure.capacity_envelope");

  const sizingBase = calculated ?? requested;
  const beforeTicket = minimum([sizingBase,envelopeAmount]);
  const ticketMin = number(value("structure.mandate.ticket_min")) ?? policy.matchedTicketMin;
  const ticketMax = number(value("structure.mandate.ticket_max")) ?? policy.matchedTicketMax;
  let proposed = beforeTicket;
  if (proposed && ticketMax && new Decimal(proposed).gt(ticketMax)) proposed = ticketMax;
  const ticketCompatible = proposed && ticketMin && ticketMax
    ? new Decimal(proposed).gte(ticketMin) && new Decimal(proposed).lte(ticketMax)
    : null;
  if (proposed && envelopeAmount && new Decimal(proposed).gt(envelopeAmount)) exceptions.push({id:"sizing-exceeds-envelope",severity:"critical",message:"Proposed sizing exceeds the binding capacity envelope.",affectedProcedures:["ES-03","ES-45"]});
  if (ticketCompatible===false) exceptions.push({id:"ticket-incompatible",severity:"high",message:"Proposed sizing does not fit the confirmed mandate ticket.",affectedProcedures:["ES-41","ES-45"]});
  if (input.operationTruth.sourcesAndUses.status!=="pass") exceptions.push({id:"sources-uses-not-closed",severity:"critical",message:"Final sizing cannot close before sources and uses tie.",affectedProcedures:["ES-45"]});

  const proFormaLeverage = input.operationTruth.proForma?.leverage ?? null;
  const leverageCeiling = definition.structure.leverageCeiling;
  const leveragePosition = proFormaLeverage===null ? null : new Decimal(proFormaLeverage).lte(leverageCeiling)?"inside":"above";
  if (leveragePosition==="above") exceptions.push({id:"leverage-above-band",severity:"high",message:"Pro forma leverage is above the current house-playbook ceiling and requires an ES-40 alternative.",affectedProcedures:["ES-01","ES-03","ES-40"]});

  const termValue = input.termSheet?.terms.find((term)=>term.id==="tenor")?.value.en.match(/\d+/)?.[0];
  const graceValue = input.termSheet?.terms.find((term)=>term.id==="grace")?.value.en.match(/\d+/)?.[0];
  const termMonths = integer(value("structure.term_months")) ?? integer(termValue) ?? input.operationTruth.request.termMonths;
  const graceMonths = integer(value("structure.grace_months")) ?? integer(graceValue) ?? 0;
  const declaredFormat = value("structure.amortization_format") as RepaymentFormat | undefined;
  const allowedFormats:RepaymentFormat[]=["sac","price","bullet","balloon"];
  const format = declaredFormat&&allowedFormats.includes(declaredFormat)?declaredFormat:policy.amortizationFormat??firstRecognizedFormat(definition.structure.amortization);
  const formatOrigin = declaredFormat&&allowedFormats.includes(declaredFormat)?"declared" as const:policy.amortizationFormat?"policy" as const:format?"house_playbook_candidate" as const:null;
  const annualRate = number(value("structure.sizing_annual_rate")) ?? policy.annualSizingRate;
  const declaredRateConvention=value("structure.rate_convention");
  const rateConvention:InterestConvention|undefined=declaredRateConvention==="nominal_annual"||declaredRateConvention==="effective_annual"?declaredRateConvention:policy.rateConvention;
  const declaredGraceInterest=value("structure.grace_interest");
  const graceInterest:GraceInterest=declaredGraceInterest==="paid"||declaredGraceInterest==="capitalized"?declaredGraceInterest:policy.graceInterest??"paid";
  const balloonPercent=number(value("structure.balloon_percent"))??policy.balloonPercent;
  const scheduleInputsValid=Boolean(
    proposed&&termMonths&&format&&annualRate&&rateConvention&&
    graceMonths>=0&&graceMonths<termMonths&&new Decimal(annualRate).gte(0)&&
    (format!=="balloon"||(balloonPercent!==undefined&&new Decimal(balloonPercent).gte(0)&&new Decimal(balloonPercent).lte(1))),
  );
  if (!termMonths) missing.add("structure.term_months");
  if (format===null) missing.add("structure.amortization_format");
  if (!annualRate) missing.add("structure.sizing_annual_rate");
  if (!rateConvention) missing.add("structure.rate_convention");
  if(termMonths&&graceMonths>=termMonths)exceptions.push({id:"invalid-grace-period",severity:"critical",message:"Grace must end before final maturity.",affectedProcedures:["ES-05","ES-07","ES-42"]});
  if(annualRate&&new Decimal(annualRate).lt(0))exceptions.push({id:"invalid-sizing-rate",severity:"critical",message:"The governed sizing rate cannot be negative.",affectedProcedures:["ES-02","ES-05"]});
  if(format==="balloon"&&(balloonPercent===undefined||new Decimal(balloonPercent).lt(0)||new Decimal(balloonPercent).gt(1)))exceptions.push({id:"invalid-balloon",severity:"critical",message:"Balloon amortisation requires a governed percentage between zero and one.",affectedProcedures:["ES-05","ES-06"]});
  let schedule:ReturnType<typeof buildDebtServiceSchedule>|null=null;
  if (scheduleInputsValid&&proposed&&termMonths&&format&&annualRate&&rateConvention) {
    schedule=buildDebtServiceSchedule({amount:proposed,annualRate,rateConvention,termMonths,graceMonths,graceInterest,format,...(format==="balloon"?{balloonPercent:balloonPercent!}: {})});
  }
  const scenarioInputs = indexed("structure.cfads_scenarios").flatMap((scenarioIndex)=>{
    const name=value(`structure.cfads_scenarios.${scenarioIndex}.name`);
    if(!name)return[];
    const cfadsByPeriod:Record<number,string>={};
    for(const periodIndex of indexed(`structure.cfads_scenarios.${scenarioIndex}.periods`)){
      const period=integer(value(`structure.cfads_scenarios.${scenarioIndex}.periods.${periodIndex}.period`));
      const cfads=number(value(`structure.cfads_scenarios.${scenarioIndex}.periods.${periodIndex}.cfads`));
      if(period!==null&&cfads!==undefined)cfadsByPeriod[period]=cfads;
    }
    return Object.keys(cfadsByPeriod).length?[{name,cfadsByPeriod}]:[];
  });
  const coverage=schedule&&scenarioInputs.length?calculateCoverageSeries({schedule:schedule.rows,scenarios:scenarioInputs}):[];
  const incompleteCoverage=coverage.some((scenario)=>scenario.periods.some((period)=>period.dscr===null));
  if(incompleteCoverage)exceptions.push({id:"incomplete-coverage-series",severity:"critical",message:"At least one CFADS scenario does not cover every debt-service period.",affectedProcedures:["ES-02","ES-05","ES-24","ES-42"]});
  const downside=coverage.find((scenario)=>/down|stress|advers|baixa/i.test(scenario.name));
  const minimumDscr=downside?.minimumDscr??null;
  const dscrFloor=policy.minimumDscr??definition.structure.minimumDscr;
  if(minimumDscr!==null&&new Decimal(minimumDscr).lt(dscrFloor))exceptions.push({id:"downside-coverage-breach",severity:"critical",message:"The proposed repayment schedule breaches the downside DSCR floor.",affectedProcedures:["ES-02","ES-03","ES-04","ES-05","ES-24","ES-42"]});
  if(!scenarioInputs.length)missing.add("structure.cfads_scenarios");

  const baseCoverage=coverage.find((scenario)=>/base/i.test(scenario.name));
  const covenantHeadroom=baseCoverage?.minimumDscr?calculateCovenantHeadroom({actual:baseCoverage.minimumDscr,limit:dscrFloor,direction:"minimum"}):null;
  if(covenantHeadroom&&!covenantHeadroom.passes)exceptions.push({id:"covenant-no-headroom",severity:"critical",message:"The proposed covenant has no headroom in the base case.",affectedProcedures:["ES-04","ES-23","ES-24","ES-42"]});
  if(covenantHeadroom?.percentage&&policy.minimumCovenantHeadroom&&new Decimal(covenantHeadroom.percentage).lt(policy.minimumCovenantHeadroom))exceptions.push({id:"covenant-insufficient-headroom",severity:"critical",message:"The proposed covenant headroom is below the governed minimum in the base case.",affectedProcedures:["ES-04","ES-23","ES-24","ES-42"]});

  const proposedMaturities:Record<string,string>={};
  for(const row of schedule?.rows??[]){
    if(new Decimal(row.principal).eq(0))continue;
    const key=`Y${Math.ceil(row.period/12)}`;
    proposedMaturities[key]=new Decimal(proposedMaturities[key]??0).plus(row.principal).toFixed();
  }
  const referenceYear=Number(input.referenceDate.slice(0,4));
  const existingMaturities:Record<string,string>={};
  for(const [period,amount] of Object.entries(input.debtTruth.maturity)){
    const year=Number(period.slice(0,4));
    const key=Number.isFinite(year)&&year>=referenceYear?`Y${Math.max(1,year-referenceYear+1)}`:period;
    existingMaturities[key]=new Decimal(existingMaturities[key]??0).plus(amount).toFixed();
  }
  const maturity=schedule?maturityConcentration({existing:existingMaturities,proposed:proposedMaturities}):null;
  const maturityLimit=policy.maturityConcentrationLimit;
  const maturityWallPass=maturity&&maturityLimit?maturity.rows.every((row)=>new Decimal(row.share).lte(maturityLimit)):null;
  if(maturityWallPass===false)exceptions.push({id:"new-maturity-wall",severity:"critical",message:"The proposed schedule creates a consolidated maturity concentration above policy.",affectedProcedures:["ES-10","ES-42"]});

  const bulletSource=value("structure.bullet_repayment_source")??input.operationTruth.bridgeAndTakeout.takeout;
  if(format==="bullet"&&!bulletSource)exceptions.push({id:"bullet-without-repayment-source",severity:"critical",message:"Bullet amortisation lacks a named and evidenced repayment source.",affectedProcedures:["ES-06","ES-29","ES-42"]});
  const rampMonths=integer(value("project.ramp_up_months"));
  const delayMonths=policy.constructionDelayMonths;
  if(rampMonths!==null&&delayMonths!==undefined&&graceMonths!==null&&graceMonths<rampMonths+delayMonths)exceptions.push({id:"grace-shorter-than-ramp",severity:"critical",message:"Grace is shorter than project ramp-up plus the governed delay margin.",affectedProcedures:["ES-07","ES-09","ES-42"]});

  const securityMechanics:StructureTruthSet["security"]["mechanics"]=(input.collateral?.lines.filter((line)=>line.selected)??[]).map((line)=>{
    const procedureId:{[key:string]:string}={receivables:"ES-11",property:"ES-13",inventory:"ES-14",equipment:"ES-15",vehicles:"ES-15",shares:"ES-16",guarantee:"ES-19",financial:"ES-20",other:"ES-20"};
    const required=line.asset.type==="receivables"?["domicile account","coverage ratio","replenishment rule","eligibility"]:line.asset.type==="property"?["independent appraisal","appraisal date","title and lien search","liquidity adjustment"]:line.asset.type==="inventory"?["independent monitoring","custodian","identifiability","minimum turnover"]:line.asset.type==="equipment"||line.asset.type==="vehicles"?["resale evidence","useful life","insurance","registered lien"]:line.asset.type==="shares"?["shareholders agreement","enforcement feasibility","rights while outstanding"]:line.asset.type==="guarantee"?["existing guarantees","evidenced reachable net worth"]:[];
    const confirmed=required.filter((item)=>bool(value(`structure.security.${line.asset.type}.${item.replaceAll(" ","_")}`))===true);
    return {asset:line.asset.description,type:line.asset.type,procedureId:procedureId[line.asset.type]??"ES-20",status:required.length===0?"partial" as const:confirmed.length===required.length?"completed" as const:"partial" as const,missingInputs:required.filter((item)=>!confirmed.includes(item))};
  });
  const collateralCoverage=input.collateral?.coverageAchieved??null;
  const governedCollateralCoverage = policy.collateralPolicyVersion && policy.minimumCollateralCoverage
    ? policy.minimumCollateralCoverage
    : null;
  const collateralSufficient = collateralCoverage && governedCollateralCoverage
    ? new Decimal(collateralCoverage).gte(governedCollateralCoverage)
    : null;
  if(collateralSufficient===false)exceptions.push({id:"collateral-policy-shortfall",severity:"critical",message:"Post-haircut collateral coverage is below the governed minimum.",affectedProcedures:["ES-03","ES-20","ES-40","ES-42"]});

  const covenantConflict=input.operationTruth.proForma?.dayOneCovenantConflict===null||input.operationTruth.proForma?.dayOneCovenantConflict===undefined?null:!input.operationTruth.proForma.dayOneCovenantConflict;
  const negativePledge=value("structure.day_one.negative_pledge_compliant")!==undefined?bool(value("structure.day_one.negative_pledge_compliant")):null;
  const corporateAuthority=value("structure.day_one.corporate_authority_complete")!==undefined?bool(value("structure.day_one.corporate_authority_complete")):null;
  const dayOneValues=[covenantConflict,negativePledge,corporateAuthority,maturityWallPass];
  const dayOnePasses=dayOneValues.some((item)=>item===false)?false:dayOneValues.every((item)=>item===true)?true:null;
  if(dayOnePasses===false)exceptions.push({id:"day-one-incompatibility",severity:"critical",message:"At least one mandatory day-one compatibility check failed.",affectedProcedures:["ES-26","ES-36","ES-42","ES-43"]});

  const selectedInstrument=value("structure.selected_instrument");
  const candidateInstrument=input.instruments.find((instrument)=>instrument.eligible)?.instrument;
  const routeAlternatives=input.instruments.map((verdict)=>({instrument:verdict.instrument.id,route:verdict.route,eligible:verdict.eligible,reasons:verdict.reasons}));
  if(!routeAlternatives.some((route)=>route.eligible))exceptions.push({id:"no-eligible-route",severity:"critical",message:"No currently assessed financing route is eligible for the issuer and use.",affectedProcedures:["ES-41","ES-44"]});
  const termBasis=(input.termSheet?.terms??[]).map((term)=>({termId:term.id,basis:term.basis,supportIds:term.supportIds,complete:term.supportIds.length>0}));
  if(termBasis.some((term)=>!term.complete))exceptions.push({id:"unsupported-term",severity:"critical",message:"At least one indicative term lacks a support basis.",affectedProcedures:["ES-43"]});

  const adjustments=(()=>{
    if(!bindingConstraint)return[];
