packages/credit-analysis/src/parse.ts.content:
import Decimal from "decimal.js";

/**
 * Reading the language a Brazilian debt schedule is actually written in.
 *
 * Rates arrive as prose: "CDI + 4,10% a.a.", "TLP + 2,90% a.a.", "1,42% a.m.", "112% do CDI",
 * "pré 16,5% a.a.". Comparing two contracts, or a stack against an ask, requires putting them
 * on one axis, and the axis a desk uses is effective annual cost at a stated index level. The
 * index level is an input with provenance, never a constant hidden here: the analysis says
 * "com CDI a 10,50%" out loud, because the whole comparison moves with it.
 *
 * Everything returns null rather than guessing. A rate this parser cannot read becomes an open
 * question in the analysis, not a silent zero, because a silent zero in a weighted cost is a
 * lie about every other number in the average.
 */

export type ParsedRate =
  | {kind: "index_plus_spread"; index: "CDI" | "TLP" | "IPCA" | "SELIC" | "TR"; spreadAnnual: string}
  | {kind: "percent_of_index"; index: "CDI"; factor: string}
  | {kind: "fixed_annual"; annual: string}
  | {kind: "fixed_monthly"; monthly: string};

const decimalFrom = (raw: string): Decimal => new Decimal(raw.replace(/\./g, "").replace(",", "."));

export function parseRate(text: string | null | undefined): ParsedRate | null {
  if (!text) return null;
  const value = text.trim().toLowerCase().replace(/\s+/g, " ");

  // "cdi + 4,10% a.a." / "tlp + 2,90% a.a." / "ipca + 7% a.a."
  const indexPlus = value.match(/^(cdi|tlp|ipca|selic|tr)\s*\+\s*([\d.,]+)\s*%(\s*a\.?a\.?)?$/);
  if (indexPlus) {
    return {
      kind: "index_plus_spread",
      index: indexPlus[1]!.toUpperCase() as "CDI" | "TLP" | "IPCA" | "SELIC" | "TR",
      spreadAnnual: decimalFrom(indexPlus[2]!).div(100).toFixed(6),
    };
  }

  // "112% do cdi" / "112% cdi" / "104% do di" / "105% da taxa di" (DI and CDI are the same axis)
  const percentOf = value.match(/^([\d.,]+)\s*%\s*(?:d[oa]\s+)?(?:taxa\s+)?(?:cdi|di)$/);
  if (percentOf) {
    return {kind: "percent_of_index", index: "CDI", factor: decimalFrom(percentOf[1]!).div(100).toFixed(6)};
  }

  // "1,42% a.m."
  const monthly = value.match(/^(?:pr[eé]\s+)?([\d.,]+)\s*%\s*a\.?m\.?$/);
  if (monthly) {
    return {kind: "fixed_monthly", monthly: decimalFrom(monthly[1]!).div(100).toFixed(6)};
  }

  // "16,5% a.a." / "pré 16,5% a.a." / "14,15% a.a. pré" / "14,15% a.a. pré-fixada"
  const annual = value.match(/^(?:pr[eé](?:-?fixad[oa])?\s+)?([\d.,]+)\s*%\s*a\.?a\.?(?:\s+pr[eé](?:-?fixad[oa])?)?$/);
  if (annual) {
    return {kind: "fixed_annual", annual: decimalFrom(annual[1]!).div(100).toFixed(6)};
  }

  return null;
}

/**
 * Effective annual cost at stated index levels.
 *
 * Monthly rates compound: 1,42% a.m. is 18,45% a.a., not 17,04%, and the difference is exactly
 * the kind of thing a schedule maintained by hand gets wrong in the company's favour.
 */
export function effectiveAnnualCost(rate: ParsedRate, indexLevels: {cdi: string; tlp?: string; ipca?: string; selic?: string; tr?: string}): string | null {
  const level = (name: string): Decimal | null => {
    const value = (indexLevels as Record<string, string | undefined>)[name.toLowerCase()];
    return value === undefined ? null : new Decimal(value);
  };

  if (rate.kind === "fixed_annual") return new Decimal(rate.annual).toFixed(6);
  if (rate.kind === "fixed_monthly") return new Decimal(rate.monthly).plus(1).pow(12).minus(1).toFixed(6);
  if (rate.kind === "percent_of_index") {
    const cdi = level("cdi");
    return cdi === null ? null : cdi.times(rate.factor).toFixed(6);
  }
  const base = level(rate.index);
  return base === null ? null : base.plus(rate.spreadAnnual).toFixed(6);
}

/**
 * A leverage covenant, as contracts state it: "Dívida líquida/EBITDA <= 3,0x".
 *
 * Only the net-debt-to-EBITDA family is parsed for now, because it is what Brazilian
 * middle-market contracts overwhelmingly carry and it is the one this analysis can test
 * pre and post transaction from the numbers in the room.
 */
export type ParsedCovenant = {metric: "net_debt_ebitda"; maximum: string; original: string};

export function parseCovenant(text: string | null | undefined): ParsedCovenant | null {
  if (!text) return null;
  const value = text.trim().toLowerCase();
  const match = value.match(/d[ií]vida\s+l[ií]quida\s*\/\s*ebitda\s*(?:<=|≤|menor ou igual a)\s*([\d.,]+)\s*x?/);
  if (!match) return null;
  return {metric: "net_debt_ebitda", maximum: decimalFrom(match[1]!).toFixed(4), original: text.trim()};
}

/**
 * A receivables coverage requirement, as collateral clauses state it: "Duplicatas 130%".
 *
 * The percentage is how much face value of receivables the lender requires per unit of
 * exposure, and it is what turns a list of collateral strings into an encumbrance number.
 */
export function parseReceivablesCoverage(text: string | null | undefined): string | null {
  if (!text) return null;
  const match = text.trim().toLowerCase().match(/(?:duplicatas|receb[ií]veis)\s+([\d.,]+)\s*%/);
  if (!match) return null;
  return decimalFrom(match[1]!).div(100).toFixed(4);
}

/** A cession clause: the receivables are assigned outright, so the exposure itself encumbers. */
export function isReceivablesCession(text: string | null | undefined): boolean {
  if (!text) return false;
  return /cedid|cess[aã]o/.test(text.trim().toLowerCase());
}

packages/credit-analysis/src/analyze.ts.content:
import Decimal from "decimal.js";

import {
  effectiveAnnualCost, isReceivablesCession, parseCovenant, parseRate,
  parseReceivablesCoverage, type ParsedCovenant, type ParsedRate,
} from "./parse";

/**
 * The desk battery: what a head of credit computes before writing a single sentence.
 *
 * The product's weakness was never that the model wrote badly. It was that there was nothing
 * for the model to narrate: the entire deterministic layer was leverage, DSCR and a haircut,
 * so every brief was a language model improvising over four numbers. A real desk sits down
 * with a data room and produces, mechanically, before judgement enters: the stack normalized
 * to one axis, the covenant arithmetic pre and post, the maximum new money the tightest
 * covenant admits, the cash cycle and what growth will absorb, the encumbrance of the asset
 * being offered, and the distance between what the company asks and what its own numbers say.
 *
 * Aurora made the gap measurable. The transaction as asked takes leverage from 2,19x to 4,56x
 * against a 3,0x covenant, the working capital ask consumes 91% of the free receivables base,
 * and the company asks CDI+4,0 while already paying CDI+4,1 on average at half the leverage.
 * Three sentences a desk head says in the first meeting, none of which the product could
 * produce, because nothing computed them.
 *
 * Everything here is Decimal, everything is traced (every finding names its inputs and carries
 * the numbers it cites), and everything degrades honestly: an unparsable rate becomes an open
 * question, never a silent zero inside an average.
 */

export type DebtLineInput = {
  lender: string;
  instrumentType?: string;
  /** Decimal string, in units. */
  balance: string;
  rate?: string;
  /** ISO date. */
  maturity?: string;
  amortization?: string;
  collateral?: string;
  covenant?: string;
};

export type DeskInput = {
  /** Stated out loud in every cost figure. An assumption of the analysis, not a fact of the room. */
  indexLevels: {cdi: string; tlp?: string; ipca?: string; selic?: string; tr?: string};
  /** The date the analysis is run, for maturity and grace arithmetic. ISO. */
  referenceDate: string;
  /** Most recent full audited year. */
  audited: {
    year: number;
    revenue: string;
    ebitda: string;
    cogs?: string;
    /** Interest expense of the year, as a magnitude. */
    financialExpenses?: string;
  };
  balance: {
    periodEnd: string;
    cash: string;
    receivables: string;
    inventory?: string;
    suppliers?: string;
    /** Gross debt as the balance sheet recognises it, leases included. */
    grossDebt: string;
  };
  interim?: {
    periodEnd: string;
    months: number;
    revenue: string;
    ebitda?: string;
    receivables?: string;
    cash?: string;
  };
  debt: DebtLineInput[];
  /**
   * Principal due per window, the way a note prints it ("Jun/26 a Mai/27: 1.229.828"). Listed
   * companies disclose this and rarely disclose maturities per line; when the lines carry no
   * dates, the wall is read from here.
   */
  maturityProfile?: Array<{window: string; amount: string; endsOn?: string}>;
  /**
   * Covenants the room states for the company as a whole rather than per line, the way a
   * listed company's notes do ("os principais instrumentos estão sujeitos a Dívida líquida /
   * EBITDA ≤ 4,0x"). They bind the stack, not one lender, and are labelled by their scope.
   */
  covenants?: Array<{scope: string; text: string}>;
  request: {
    /** Every amount the room states, with where it said so. More than one is itself a finding. */
    amounts: Array<{value: string; source: string}>;
    termMonths?: number;
    graceMonths?: number;
    rateAsk?: string;
    useOfProceeds?: Array<{item: string; amount: string}>;
    /** The slice of the ask labelled working capital, when the room says. */
    workingCapitalAsk?: string;
  };
  project?: {
    operationDate?: string;
    totalCost?: string;
  };
  /** Next projected year, for the growth-absorption arithmetic. */
  projectedNextYear?: {year: number; revenue: string};
  /**
   * What a venture lender reads instead of EBITDA: recurring revenue, burn, runway, the last
   * round, retention and concentration. Any of them may be absent; the runway arithmetic needs
   * burn, everything else sharpens it.
   */
  venture?: {
    arr?: string;
    mrr?: string;
    monthlyBurn?: string;
    runwayMonthsStated?: string;
    lastEquityRoundAmount?: string;
    lastEquityRoundDate?: string;
    nrr?: string;
    monthlyChurn?: string;
    topCustomerShare?: string;
  };
};

export type RunwayAnalysis = {
  monthlyBurn: string;
  cash: string;
  /** cash / burn, months, before the deal. */
  monthsPre: string;
  /** (cash + ask) / burn: what the ticket buys before its own service. */
  monthsPost: string;
  /** Same, with the ticket's interest paid monthly out of the same cash. */
  monthsPostAfterService: string;
  /** Annual rate assumed for the service, stated; the ask's own rate when parseable. */
  assumedRate: string;
  arr: string | null;
  /** (existing debt + ask) / ARR. Venture practice keeps this under roughly a third. */
  debtToArr: string | null;
  nrr: string | null;
  topCustomerShare: string | null;
};

export type Finding = {
  id: string;
  severity: "critical" | "high" | "medium" | "info";
  /** Desk language, numbers included. The model may rephrase; it may not renumber. */
  pt: string;
  en: string;
  /** Every figure the sentence cites, as decimal strings, so nothing has to be re-derived. */
  values: Record<string, string>;
  inputs: string[];
};

export type StackLine = {
  lender: string;
  instrumentType?: string;
  balance: string;
  rate: ParsedRate | null;
  effectiveAnnual: string | null;
  maturity?: string;
  covenant: ParsedCovenant | null;
};

export type DeskAnalysis = {
  assumptions: {cdi: string; referenceDate: string};
  stack: {
    lines: StackLine[];
    totalSchedule: string;
    totalOnBalance: string;
    scheduleGap: string;
    weightedCost: string | null;
    weightedSpreadOverCdi: string | null;
    unpriceableLines: number;
    maturingWithin24Months: string;
    /** Principal due within 12 months, from the profile when the lines cannot say. */
    maturingWithin12Months: string;
    /** Cash over the principal due within 12 months; null when nothing is due. */
    liquidityCoverage12: string | null;
  };
  leverage: {
    netDebtPre: string;
    ebitda: string;
    preTurns: string;
    scenarios: Array<{amount: string; source: string; postTurns: string}>;
    tightestCovenant: {lender: string; maximum: string} | null;
    /** The number that changes the meeting: new money the tightest covenant admits. */
    maxNewDebtUnderCovenants: string | null;
    /** EBITDA over the year's interest expense; null when the room does not state the expense. */
    interestCoverage: string | null;
    /** The same coverage with the ask's interest added at the stack's cost, or the ask's own rate. */
    interestCoveragePost: string | null;
  };
  workingCapital: {
    dso: string | null;
    dio: string | null;
    dpo: string | null;
    cycleDays: string | null;
    growthAbsorption: string | null;
  };
  encumbrance: {
    receivablesBase: string;
    encumbered: string;
    free: string;
    askAgainstFree: string | null;
  };
  /** Whether leverage arithmetic means anything: a company that burns cash has no turns to count. */
  profile: "cash_generative" | "cash_burning";
  runway: RunwayAnalysis | null;
  findings: Finding[];
};

const d = (value: string | number): Decimal => new Decimal(value);
const ZERO = new Decimal(0);

/** R$ 13,6M, the way a desk says a number out loud. */
const brlM = (value: Decimal.Value): string => {
  const millions = new Decimal(value).div(1_000_000);
  return `R$ ${millions.toFixed(1).replace(".", ",")}M`;
};
const turns = (value: Decimal.Value): string => `${new Decimal(value).toFixed(2).replace(".", ",")}x`;
const pctAA = (value: Decimal.Value): string => `${new Decimal(value).times(100).toFixed(1).replace(".", ",")}% a.a.`;

/**
 * Calendar months between two ISO dates, read from the string itself.
 *
 * Never through `new Date()`: an ISO date parses as UTC midnight, which in any timezone west
 * of Greenwich is the previous local day, and "2027-09-01" quietly becoming August moves every
 * maturity and grace computation by a month. Date arithmetic in a credit analysis cannot
 * depend on the analyst's timezone.
 */
const monthsBetween = (fromIso: string, toIso: string): number => {
  const [fromYear, fromMonth] = fromIso.split("-").map(Number);
  const [toYear, toMonth] = toIso.split("-").map(Number);
  return (toYear! - fromYear!) * 12 + (toMonth! - fromMonth!);
};

export function analyzeCreditPosition(input: DeskInput): DeskAnalysis {
  const findings: Finding[] = [];
  const cdi = d(input.indexLevels.cdi);

  // ---- the stack, on one axis -----------------------------------------------------------------
  const lines: StackLine[] = input.debt.map((line) => {
    const rate = parseRate(line.rate);
    return {
      lender: line.lender,
      ...(line.instrumentType !== undefined ? {instrumentType: line.instrumentType} : {}),
      balance: d(line.balance).toFixed(2),
      rate,
      effectiveAnnual: rate ? effectiveAnnualCost(rate, input.indexLevels) : null,
      ...(line.maturity !== undefined ? {maturity: line.maturity} : {}),
      covenant: parseCovenant(line.covenant),
    };
  });

  const totalSchedule = lines.reduce((sum, line) => sum.plus(line.balance), ZERO);
  const totalOnBalance = d(input.balance.grossDebt);
  const scheduleGap = totalOnBalance.minus(totalSchedule);

  const priceable = lines.filter((line) => line.effectiveAnnual !== null);
  const priceableTotal = priceable.reduce((sum, line) => sum.plus(line.balance), ZERO);
  const weightedCost = priceableTotal.gt(0)
    ? priceable.reduce((sum, line) => sum.plus(d(line.balance).times(line.effectiveAnnual!)), ZERO).div(priceableTotal)
    : null;
  const weightedSpread = weightedCost ? weightedCost.minus(cdi) : null;

  const maturingFromLines = lines
    .filter((line) => line.maturity !== undefined && monthsBetween(input.referenceDate, line.maturity) <= 24)
    .reduce((sum, line) => sum.plus(line.balance), ZERO);
  // The profile wins when the lines cannot speak: a line without a maturity is not a line that
  // never matures, and a note that says "Jun/26 a Mai/27: 1.229.828" has already done the sum.
  const linesWithDates = lines.filter((line) => line.maturity !== undefined).length;
  const profileWithin24 = (input.maturityProfile ?? [])
    .filter((entry) => entry.endsOn !== undefined && monthsBetween(input.referenceDate, entry.endsOn) <= 24)
    .reduce((sum, entry) => sum.plus(entry.amount), ZERO);
  const maturing24 = linesWithDates < lines.length && profileWithin24.gt(maturingFromLines) ? profileWithin24 : maturingFromLines;
  const within12FromLines = lines
    .filter((line) => line.maturity !== undefined && monthsBetween(input.referenceDate, line.maturity) <= 12)
    .reduce((sum, line) => sum.plus(line.balance), ZERO);
  const profileWithin12 = (input.maturityProfile ?? [])
    .filter((entry) => entry.endsOn !== undefined && monthsBetween(input.referenceDate, entry.endsOn) <= 12)
    .reduce((sum, entry) => sum.plus(entry.amount), ZERO);
  const maturing12 = linesWithDates < lines.length && profileWithin12.gt(within12FromLines) ? profileWithin12 : within12FromLines;
  const liquidityCoverage12 = maturing12.gt(0) ? d(input.balance.cash).div(maturing12) : null;

  // The wall a desk actually worries about is the next twelve months against the cash on hand.
  // A company can carry a heavy schedule if it sits on the cash to meet it; a light one is a
  // wall if the cash is not there. The ratio says which, before any refinancing assumption.
  if (liquidityCoverage12 && liquidityCoverage12.lt("1.5")) {
    const tight = liquidityCoverage12.lt(1);
    findings.push({
      id: "short-term-principal-vs-cash",
      severity: tight ? "critical" : "high",
      pt: `${brlM(maturing12)} de principal vencem nos próximos 12 meses contra ${brlM(input.balance.cash)} de caixa: cobertura de ${liquidityCoverage12.toFixed(2).replace(".", ",")}x. ${tight ? "O caixa não cobre o principal do ano: sem refinanciamento ou geração acima do histórico, a companhia não chega ao fim do período pelos próprios meios, e a captação tem que ser dimensionada para isso." : "Cobre, mas sem folga para a sazonalidade do capital de giro: parte do caixa que paga a dívida é o caixa que compra estoque, e a mesa precisa ver o fluxo mensal antes de tratar o refinanciamento como opcional."}`,
      en: `${brlM(maturing12)} of principal falls due in the next 12 months against ${brlM(input.balance.cash)} of cash: ${liquidityCoverage12.toFixed(2)}x coverage. ${tight ? "Cash does not cover the year's principal: without refinancing or generation above history, the company does not reach the end of the period on its own means, and the raise has to be sized for that." : "It covers, but without room for working-capital seasonality: part of the cash that pays the debt is the cash that buys inventory, and the desk needs the monthly flow before treating refinancing as optional."}`,
      values: {maturing12: maturing12.toFixed(2), cash: d(input.balance.cash).toFixed(2), coverage: liquidityCoverage12.toFixed(4)},
      inputs: ["debt.maturity_profile", "debt.instruments", "interim_financials.cash"],
    });
  }

  if (scheduleGap.abs().gt(totalOnBalance.times("0.02"))) {
    findings.push({
      id: "stack-vs-balance",
      severity: "critical",
      pt: `O mapa de dívida soma ${brlM(totalSchedule)} e o balanço reconhece ${brlM(totalOnBalance)}: há ${brlM(scheduleGap.abs())} de dívida ${scheduleGap.gt(0) ? "fora do mapa" : "a mais no mapa"}. Antes de qualquer estrutura, a mesa precisa saber o que é, tipicamente arrendamento ou fiança não listada.`,
      en: `The debt schedule sums to ${brlM(totalSchedule)} while the balance sheet recognises ${brlM(totalOnBalance)}: ${brlM(scheduleGap.abs())} of debt sits ${scheduleGap.gt(0) ? "outside the schedule" : "in the schedule only"}. The desk needs to know what it is before structuring, typically leases or unlisted guarantees.`,
      values: {schedule: totalSchedule.toFixed(2), onBalance: totalOnBalance.toFixed(2), gap: scheduleGap.toFixed(2)},
      inputs: ["debt.total_gross", "historical_financials.gross_debt"],
    });
  }

  const unpriceable = lines.filter((line, index) => line.effectiveAnnual === null && Boolean(input.debt[index]?.rate));
  if (unpriceable.length > 0) {
    findings.push({
      id: "unparsed-rates",
      severity: "medium",
      pt: `${unpriceable.length} linha(s) do mapa têm custo que não pôde ser posto no eixo comum (taxa ilegível ou índice sem nível informado) (${unpriceable.map((line) => line.lender).join(", ")}); o custo médio do stack está calculado sem elas.`,
      en: `${unpriceable.length} schedule line(s) carry a cost that could not be normalised (unreadable rate or index without a stated level) (${unpriceable.map((line) => line.lender).join(", ")}); the weighted cost excludes them.`,
      values: {count: String(unpriceable.length)},
      inputs: unpriceable.map((line) => `debt.instruments.${lines.indexOf(line) + 1}.rate`),
    });
  }

  // ---- leverage and covenants, pre and post ---------------------------------------------------
  const ebitda = d(input.audited.ebitda);
  const netDebtPre = totalOnBalance.minus(input.balance.cash);
  const preTurns = netDebtPre.div(ebitda);

  const scenarios = input.request.amounts.map((amount) => ({
    amount: d(amount.value).toFixed(2),
    source: amount.source,
    postTurns: netDebtPre.plus(amount.value).div(ebitda).toFixed(4),
  }));

  const covenants = [
    ...lines.filter((line) => line.covenant !== null).map((line) => ({lender: line.lender, covenant: line.covenant!})),
    ...(input.covenants ?? [])
      .map((entry) => ({lender: entry.scope, covenant: parseCovenant(entry.text)}))
      .filter((entry): entry is {lender: string; covenant: ParsedCovenant} => entry.covenant !== null),
  ];
  const tightest = covenants.length > 0
    ? covenants.reduce((min, entry) => (d(entry.covenant.maximum).lt(min.covenant.maximum) ? entry : min))
    : null;

  // ---- interest coverage: what the operation earns against what the debt costs ---------------
  const expenses = input.audited.financialExpenses ? d(input.audited.financialExpenses).abs() : null;
  const interestCoverage = expenses && expenses.gt(0) && ebitda.gt(0) ? ebitda.div(expenses) : null;
  const askAmount = scenarios.length > 0 ? scenarios.reduce((max, s) => (d(s.amount).gt(max) ? d(s.amount) : max), ZERO) : ZERO;
  const askRateParsed = parseRate(input.request.rateAsk);
  const askCostRaw = askRateParsed ? effectiveAnnualCost(askRateParsed, input.indexLevels) : null;
  const askCost = askCostRaw ? d(askCostRaw) : weightedCost;
  const interestCoveragePost = interestCoverage && expenses && askCost ? ebitda.div(expenses.plus(askAmount.times(askCost))) : null;
  if (interestCoveragePost && interestCoveragePost.lt("2")) {
    findings.push({
      id: "thin-interest-coverage",
      severity: interestCoveragePost.lt("1.5") ? "critical" : "high",
      pt: `Cobertura de juros de ${interestCoverage!.toFixed(1).replace(".", ",")}x hoje e ${interestCoveragePost.toFixed(1).replace(".", ",")}x com a operação (juros do pedido a ${pctAA(askCost!)}${askCostRaw ? ", a taxa pedida" : ", o custo médio do estoque"}). Abaixo de 2x a operação consome a maior parte do que a companhia gera antes de amortizar um real; abaixo de 1,5x o serviço depende de refinanciamento contínuo.`,
      en: `Interest coverage of ${interestCoverage!.toFixed(1)}x today and ${interestCoveragePost.toFixed(1)}x with the deal (the ask's interest at ${pctAA(askCost!)}${askCostRaw ? ", the rate asked" : ", the stack's weighted cost"}). Under 2x the operation consumes most of what the company generates before amortising a real; under 1.5x service depends on continuous refinancing.`,
      values: {coverage: interestCoverage!.toFixed(4), coveragePost: interestCoveragePost.toFixed(4), askCost: askCost!.toFixed(6)},
      inputs: ["historical_financials.ebitda", "historical_financials.financial_expenses", "transaction.requested_amount", "debt.instruments"],
    });
  }

  // Leverage over a negative EBITDA is a number with no meaning, and a covenant test on it is
  // a sentence with no meaning. The cash-burning company is read through its runway instead.
  const burning = ebitda.lte(0);

  let maxNewDebt: Decimal | null = null;
  if (tightest && !burning) {
    maxNewDebt = d(tightest.covenant.maximum).times(ebitda).minus(netDebtPre);
    const worst = scenarios.reduce((max, s) => (d(s.postTurns).gt(max.postTurns) ? s : max), scenarios[0]!);
    if (scenarios.some((s) => d(s.postTurns).gt(tightest.covenant.maximum))) {
      // Already above the ceiling before the deal is a different sentence from "the deal breaks
      // it": the first is a fact about the company today, and new money can only enter as a swap.
      const alreadyAbove = preTurns.gt(tightest.covenant.maximum);
      findings.push({
        id: "covenant-breach-day-one",
        severity: "critical",
        pt: alreadyAbove
          ? `A companhia já está acima do covenant antes da operação: ${turns(preTurns)} contra o teto de ${turns(tightest.covenant.maximum)} (${tightest.lender}), excesso de ${brlM(maxNewDebt.abs())} de dívida líquida. Não cabe dívida nova por cima do estoque; a operação só existe como troca de passivo (resgate de linhas dentro do tíquete) ou com renegociação do covenant, e a trajetória até a próxima medição é o que a mesa precisa mostrar.`
          : `A operação como solicitada rompe covenant existente no dia um: a alavancagem sai de ${turns(preTurns)} para ${turns(worst.postTurns)} contra o teto de ${turns(tightest.covenant.maximum)} (${tightest.lender}). Nos números atuais cabem ${brlM(Decimal.max(maxNewDebt, 0))} de dívida nova antes do covenant, não ${brlM(worst.amount)}. Isso muda a natureza da operação: ou o pedido inclui quitação/renegociação das linhas com covenant, ou o tíquete cai, ou não há operação.`,
        en: alreadyAbove
          ? `The company is already above the covenant before the deal: ${turns(preTurns)} against the ${turns(tightest.covenant.maximum)} ceiling (${tightest.lender}), ${brlM(maxNewDebt.abs())} of net debt in excess. No new debt fits on top of the stock; the deal exists only as a liability swap (lines repaid inside the ticket) or with a renegotiated covenant, and the trajectory to the next test is what the desk has to show.`
          : `The transaction as asked breaches an existing covenant on day one: leverage moves from ${turns(preTurns)} to ${turns(worst.postTurns)} against the ${turns(tightest.covenant.maximum)} ceiling (${tightest.lender}). The current numbers admit ${brlM(Decimal.max(maxNewDebt, 0))} of new debt before the covenant, not ${brlM(worst.amount)}. That changes the nature of the deal: either the ask includes repaying or renegotiating the covenanted lines, or the ticket comes down, or there is no deal.`,
        values: {pre: preTurns.toFixed(4), post: worst.postTurns, ceiling: tightest.covenant.maximum, maxNewDebt: maxNewDebt.toFixed(2)},
        inputs: ["debt.covenants", "historical_financials.gross_debt", "historical_financials.cash", "historical_financials.ebitda", "transaction.requested_amount"],
      });
    }
  }

  if (maturing24.gt(0) && totalSchedule.gt(0)) {
    const share = Decimal.min(maturing24.div(totalSchedule), 1);
    if (share.gte("0.4")) {
      findings.push({
        id: "maturity-wall",
        severity: "high",
        pt: `${brlM(maturing24)} (${share.times(100).toFixed(0)}% do mapa) vencem em até 24 meses. A operação disputa caixa com uma parede de refinanciamento, e o desenho tem que dizer o que acontece com essas linhas.`,
        en: `${brlM(maturing24)} (${share.times(100).toFixed(0)}% of the schedule) matures within 24 months. The transaction competes with a refinancing wall, and the structure has to say what happens to those lines.`,
        values: {maturing24: maturing24.toFixed(2), share: share.toFixed(4)},
        inputs: ["debt.instruments"],
      });
    }
  }

  // ---- runway: the axis a venture lender actually reads ---------------------------------------
  //
  // Months of cash before the deal, months the ticket buys, and months it buys once it has to
  // pay its own interest out of the same cash. The third number is the honest one: a loan that
  // buys eight months and costs two of them back buys six, and the founder's letter will have
  // quoted the first figure.
  let runway: RunwayAnalysis | null = null;
  const venture = input.venture;
  if (venture?.monthlyBurn && d(venture.monthlyBurn).gt(0)) {
    const burn = d(venture.monthlyBurn);
    const cashNow = d(input.balance.cash);
    const ask = scenarios.length > 0 ? scenarios.reduce((max, s) => (d(s.amount).gt(max) ? d(s.amount) : max), ZERO) : ZERO;
    const askRate = parseRate(input.request.rateAsk);
    const askCost = askRate ? effectiveAnnualCost(askRate, input.indexLevels) : null;
    // Venture practice when the ask names no rate: CDI plus six, before the warrant.
    const assumedRate = askCost ? d(askCost) : cdi.plus("0.06");
    const monthsPre = cashNow.div(burn);
    const monthsPost = cashNow.plus(ask).div(burn);
    const monthlyInterest = ask.times(assumedRate).div(12);
    const monthsPostAfterService = cashNow.plus(ask).div(burn.plus(monthlyInterest));
    const arr = venture.arr ? d(venture.arr) : null;
    const debtToArr = arr && arr.gt(0) ? totalOnBalance.plus(ask).div(arr) : null;
    const nrr = venture.nrr ? d(venture.nrr) : null;
    const topShare = venture.topCustomerShare ? d(venture.topCustomerShare) : null;
    runway = {
      monthlyBurn: burn.toFixed(2),
      cash: cashNow.toFixed(2),
      monthsPre: monthsPre.toFixed(1),
      monthsPost: monthsPost.toFixed(1),
      monthsPostAfterService: monthsPostAfterService.toFixed(1),
      assumedRate: assumedRate.toFixed(6),
      arr: arr ? arr.toFixed(2) : null,
      debtToArr: debtToArr ? debtToArr.toFixed(4) : null,
      nrr: nrr ? nrr.toFixed(4) : null,
      topCustomerShare: topShare ? topShare.toFixed(4) : null,
    };
    const months = (value: Decimal) => value.toFixed(1).replace(".", ",");

    if (monthsPre.lt(12)) {
      findings.push({
        id: "runway-short",
        severity: monthsPre.lt(9) ? "critical" : "high",
        pt: `Runway de ${months(monthsPre)} meses antes da operação (caixa de ${brlM(cashNow)} sobre queima de ${brlM(burn)} por mês). ${monthsPre.lt(9) ? "Abaixo de nove meses não é venture debt, é ponte de equity: o credor entraria para financiar a própria saída." : "Abaixo de doze meses o credor vai exigir que a rodada esteja encaminhada antes do desembolso, não depois."}`,
        en: `Runway of ${monthsPre.toFixed(1)} months before the deal (${brlM(cashNow)} of cash over ${brlM(burn)} of monthly burn). ${monthsPre.lt(9) ? "Under nine months this is not venture debt but an equity bridge: the lender would be funding its own exit." : "Under twelve months the lender will want the round in motion before disbursement, not after."}`,
        values: {monthsPre: monthsPre.toFixed(2), cash: cashNow.toFixed(2), burn: burn.toFixed(2)},
        inputs: ["interim_financials.cash", "interim_financials.monthly_burn"],
      });
    }
    if (venture.runwayMonthsStated && d(venture.runwayMonthsStated).minus(monthsPre).abs().gt("1.5")) {
      findings.push({
        id: "runway-stated-vs-computed",
        severity: "high",
        pt: `A companhia declara ${d(venture.runwayMonthsStated).toFixed(0)} meses de runway; o caixa sobre a queima média dá ${months(monthsPre)}. A diferença é a queima escolhida (melhor mês contra média do trimestre), e o credor usa a média.`,
        en: `The company states ${d(venture.runwayMonthsStated).toFixed(0)} months of runway; cash over average burn gives ${monthsPre.toFixed(1)}. The difference is the burn chosen (best month versus quarterly average), and the lender uses the average.`,
        values: {stated: d(venture.runwayMonthsStated).toFixed(2), computed: monthsPre.toFixed(2)},
        inputs: ["company.runway_months", "interim_financials.cash", "interim_financials.monthly_burn"],
      });
    }
    if (ask.gt(0)) {
      findings.push({
        id: "runway-bought",
        severity: "info",
        pt: `A captação de ${brlM(ask)} leva o runway de ${months(monthsPre)} para ${months(monthsPost)} meses antes do serviço, e para ${months(monthsPostAfterService)} com os juros pagos do mesmo caixa (${pctAA(assumedRate)} assumido${askCost ? ", a taxa pedida" : ", prática de venture debt quando o pedido não nomeia taxa"}). O que a operação compra é ${months(monthsPostAfterService.minus(monthsPre))} meses, não ${months(monthsPost.minus(monthsPre))}.`,
        en: `The ${brlM(ask)} raise takes runway from ${monthsPre.toFixed(1)} to ${monthsPost.toFixed(1)} months before service, and to ${monthsPostAfterService.toFixed(1)} with interest paid from the same cash (${pctAA(assumedRate)} assumed${askCost ? ", the rate asked" : ", venture-debt practice when the ask names no rate"}). What the deal buys is ${monthsPostAfterService.minus(monthsPre).toFixed(1)} months, not ${monthsPost.minus(monthsPre).toFixed(1)}.`,
        values: {monthsPre: monthsPre.toFixed(2), monthsPost: monthsPost.toFixed(2), monthsPostAfterService: monthsPostAfterService.toFixed(2), assumedRate: assumedRate.toFixed(6)},
        inputs: ["transaction.requested_amount", "interim_financials.cash", "interim_financials.monthly_burn"],
      });
    }
    if (debtToArr && debtToArr.gt("0.35")) {
      findings.push({
        id: "debt-to-arr",
        severity: "high",
        pt: `Dívida total pós-operação de ${brlM(totalOnBalance.plus(ask))} sobre ARR de ${brlM(arr!)}: ${debtToArr.times(100).toFixed(0)}% do ARR. A prática de venture debt fica entre 20% e 35%; acima disso o credor está financiando a queima, não a tração.`,
        en: `Total post-deal debt of ${brlM(totalOnBalance.plus(ask))} over ARR of ${brlM(arr!)}: ${debtToArr.times(100).toFixed(0)}% of ARR. Venture practice sits between 20% and 35%; above that the lender is funding burn, not traction.`,
        values: {debtToArr: debtToArr.toFixed(4), arr: arr!.toFixed(2), debtPost: totalOnBalance.plus(ask).toFixed(2)},
        inputs: ["interim_financials.arr", "debt.total_gross", "transaction.requested_amount"],
      });
    }
    if (nrr && nrr.lt(1)) {
      findings.push({
        id: "nrr-below-par",
        severity: "high",
        pt: `Retenção líquida de receita de ${nrr.times(100).toFixed(0)}%: a base encolhe sem venda nova. Em venture debt a base é a garantia; abaixo de 100% o credor precifica churn, não crescimento.`,
        en: `Net revenue retention of ${nrr.times(100).toFixed(0)}%: the base shrinks without new sales. In venture debt the base is the collateral; under 100% the lender prices churn, not growth.`,
        values: {nrr: nrr.toFixed(4)},
        inputs: ["company.net_revenue_retention"],
      });
    }
    if (topShare && topShare.gt("0.20")) {
      findings.push({
        id: "customer-concentration",
        severity: "high",
        pt: `O maior cliente responde por ${topShare.times(100).toFixed(0)}% do MRR. Acima de 20% a perda de um contrato move o runway em meses, e o credor vai pedir o contrato e uma cláusula de vencimento antecipado ligada a ele.`,
        en: `The largest customer is ${topShare.times(100).toFixed(0)}% of MRR. Above 20% losing one contract moves runway by months, and the lender will ask for the contract and an acceleration clause tied to it.`,
        values: {topCustomerShare: topShare.toFixed(4)},
        inputs: ["customers.top_customers.1.share_pct"],
      });
    }
  }

  // ---- working capital: the cycle and what growth absorbs -------------------------------------
  const revenue = d(input.audited.revenue);
  const cogs = input.audited.cogs ? d(input.audited.cogs) : null;
  const dso = revenue.gt(0) ? d(input.balance.receivables).div(revenue).times(365) : null;
  const dio = cogs && input.balance.inventory ? d(input.balance.inventory).div(cogs).times(365) : null;
  const dpo = cogs && input.balance.suppliers ? d(input.balance.suppliers).div(cogs).times(365) : null;
  const cycle = dso && dio && dpo ? dso.plus(dio).minus(dpo) : null;

  let growthAbsorption: Decimal | null = null;
  if (cycle && input.projectedNextYear) {
    const growth = d(input.projectedNextYear.revenue).minus(revenue);
    if (growth.gt(0)) {
      growthAbsorption = growth.times(cycle).div(365);
      if (input.request.workingCapitalAsk) {
        const ask = d(input.request.workingCapitalAsk);
        if (ask.gt(growthAbsorption.times(2))) {
          findings.push({
            id: "wc-ask-vs-need",
            severity: "high",
            pt: `O crescimento projetado (${brlM(growth)} de receita) absorve ${brlM(growthAbsorption)} de capital de giro ao ciclo atual de ${cycle.toFixed(0)} dias, mas o pedido rotula ${brlM(ask)} como giro, ${ask.div(growthAbsorption).toFixed(1).replace(".", ",")} vezes a necessidade incremental. A diferença financia outra coisa (alongamento de ciclo, recomposição de caixa ou substituição de linhas), e a mesa precisa nomear o quê, porque o fundo vai perguntar.`,
            en: `Projected growth (${brlM(growth)} of revenue) absorbs ${brlM(growthAbsorption)} of working capital at the current ${cycle.toFixed(0)}-day cycle, yet the ask labels ${brlM(ask)} as working capital, ${ask.div(growthAbsorption).toFixed(1)} times the incremental need. The difference funds something else, and the desk has to name it, because the fund will ask.`,
            values: {need: growthAbsorption.toFixed(2), ask: ask.toFixed(2), cycleDays: cycle.toFixed(1)},
            inputs: ["projections.revenue", "historical_financials.revenue", "transaction.use_of_proceeds"],
          });
        }
      }
    }
  }

  // ---- encumbrance: how free is the asset being offered ---------------------------------------
  const receivablesBase = d(input.interim?.receivables ?? input.balance.receivables);
  let encumbered = ZERO;
  for (const [index, line] of input.debt.entries()) {
    const coverage = parseReceivablesCoverage(line.collateral);
    if (coverage) encumbered = encumbered.plus(d(line.balance).times(coverage));
    else if (isReceivablesCession(line.collateral)) encumbered = encumbered.plus(line.balance);
    void index;
  }
  const free = Decimal.max(receivablesBase.minus(encumbered), 0);
  let askAgainstFree: Decimal | null = null;
  if (input.request.workingCapitalAsk && free.gt(0)) {
    askAgainstFree = d(input.request.workingCapitalAsk).div(free);
    if (askAgainstFree.gte("0.8")) {
      findings.push({
        id: "receivables-encumbrance",
        severity: "high",
        pt: `Dos ${brlM(receivablesBase)} de recebíveis, ${brlM(encumbered)} já estão comprometidos com as linhas atuais (coberturas de 125% a 130% e cessões). Sobram ${brlM(free)} livres, e o pedido de giro de ${brlM(input.request.workingCapitalAsk)} consome ${askAgainstFree.times(100).toFixed(0)}% disso. Garantia para dinheiro novo é escassa, e qualquer estrutura vai disputar colateral com os bancos incumbentes.`,
        en: `Of ${brlM(receivablesBase)} in receivables, ${brlM(encumbered)} is already committed to the current lines (125% to 130% coverages and cessions). ${brlM(free)} remains free, and the ${brlM(input.request.workingCapitalAsk)} working-capital ask consumes ${askAgainstFree.times(100).toFixed(0)}% of it. Collateral for new money is scarce, and any structure will compete with incumbent banks for it.`,
        values: {base: receivablesBase.toFixed(2), encumbered: encumbered.toFixed(2), free: free.toFixed(2), askShare: askAgainstFree.toFixed(4)},
        inputs: ["debt.instruments", "interim_financials.receivables"],
      });
    }
  }

  // ---- the ask against the room's own numbers -------------------------------------------------
  const distinctAmounts = [...new Set(input.request.amounts.map((a) => d(a.value).toFixed(2)))];
  if (distinctAmounts.length > 1) {
    const described = input.request.amounts.map((a) => `${brlM(a.value)} (${a.source})`).join(" e ");
    findings.push({
      id: "amount-divergence",
      severity: "high",
      pt: `A sala pede dois valores diferentes: ${described}. Nenhuma fonte manda na outra; é pergunta para a empresa antes de qualquer material ir a mercado.`,
      en: `The room asks for two different amounts: ${described}. Neither source outranks the other; it is a question for the company before any material goes to market.`,
      values: Object.fromEntries(input.request.amounts.map((a, i) => [`amount_${i + 1}`, d(a.value).toFixed(2)])),
      inputs: ["transaction.requested_amount"],
    });
  }

  const rateAsk = parseRate(input.request.rateAsk);
  const rateAskAnnual = rateAsk ? effectiveAnnualCost(rateAsk, input.indexLevels) : null;
  if (rateAskAnnual && weightedCost && tightest) {
    const worstPost = scenarios.reduce((max, s) => Decimal.max(max, s.postTurns), ZERO);
    if (d(rateAskAnnual).lte(weightedCost.plus("0.005")) && worstPost.gt(preTurns)) {
      findings.push({
        id: "rate-ask-vs-stack",
        severity: "high",
        pt: `A empresa pede ${pctAA(rateAskAnnual)} (com CDI a ${pctAA(cdi)}) para dinheiro novo que leva a alavancagem a ${turns(worstPost)}, enquanto o stack atual, contratado à alavancagem menor de ${turns(preTurns)}, já custa ${pctAA(weightedCost)} na média. Dinheiro novo, mais alavancado e mais junior não sai mais barato que o estoque; a expectativa de taxa precisa ser recalibrada antes da conversa com fundos.`,
        en: `The company asks ${pctAA(rateAskAnnual)} (CDI at ${pctAA(cdi)}) for new money that takes leverage to ${turns(worstPost)}, while the current stack, written at lower leverage, already averages ${pctAA(weightedCost)}. Newer, more levered, more junior money does not price below the stock; the rate expectation needs recalibrating before any fund conversation.`,
        values: {ask: rateAskAnnual, stackAverage: weightedCost.toFixed(6), postTurns: worstPost.toFixed(4)},
        inputs: ["transaction.expected_rate", "debt.instruments"],
      });
    }
  }

  if (input.request.graceMonths !== undefined && input.project?.operationDate) {
    const graceEndsBy = monthsBetween(input.referenceDate, input.project.operationDate) - input.request.graceMonths;
    if (graceEndsBy > 0) {
      findings.push({
        id: "grace-vs-project",
        severity: "medium",
        pt: `Com desembolso na data de referência, a carência de ${input.request.graceMonths} meses termina ${graceEndsBy} meses antes de o projeto entrar em operação (${input.project.operationDate}). A amortização começa antes da receita incremental existir, e o serviço desse intervalo sai do caixa da operação atual.`,
        en: `Disbursed at the reference date, the ${input.request.graceMonths}-month grace ends ${graceEndsBy} months before the project starts operating (${input.project.operationDate}). Amortisation begins before the incremental revenue exists, and that interval is served by the current operation's cash.`,
        values: {gapMonths: String(graceEndsBy)},
        inputs: ["transaction.desired_grace_months", "project.operation_date"],
      });
    }
  }

  // Severity order, so a reader meets the deal-changers first.
  const order = {critical: 0, high: 1, medium: 2, info: 3};
  findings.sort((a, b) => order[a.severity] - order[b.severity]);

  return {
    assumptions: {cdi: cdi.toFixed(6), referenceDate: input.referenceDate},
    stack: {
      lines,
      totalSchedule: totalSchedule.toFixed(2),
      totalOnBalance: totalOnBalance.toFixed(2),
      scheduleGap: scheduleGap.toFixed(2),
      weightedCost: weightedCost ? weightedCost.toFixed(6) : null,
      weightedSpreadOverCdi: weightedSpread ? weightedSpread.toFixed(6) : null,
      unpriceableLines: unpriceable.length,
      maturingWithin24Months: maturing24.toFixed(2),
      maturingWithin12Months: maturing12.toFixed(2),
      liquidityCoverage12: liquidityCoverage12 ? liquidityCoverage12.toFixed(4) : null,
    },
    leverage: {
      netDebtPre: netDebtPre.toFixed(2),
      ebitda: ebitda.toFixed(2),
      preTurns: preTurns.toFixed(4),
      scenarios,
      tightestCovenant: tightest ? {lender: tightest.lender, maximum: tightest.covenant.maximum} : null,
      maxNewDebtUnderCovenants: maxNewDebt ? maxNewDebt.toFixed(2) : null,
      interestCoverage: interestCoverage ? interestCoverage.toFixed(4) : null,
      interestCoveragePost: interestCoveragePost ? interestCoveragePost.toFixed(4) : null,
    },
    workingCapital: {
      dso: dso ? dso.toFixed(1) : null,
      dio: dio ? dio.toFixed(1) : null,
      dpo: dpo ? dpo.toFixed(1) : null,
      cycleDays: cycle ? cycle.toFixed(1) : null,
      growthAbsorption: growthAbsorption ? growthAbsorption.toFixed(2) : null,
    },
    encumbrance: {
      receivablesBase: receivablesBase.toFixed(2),
      encumbered: encumbered.toFixed(2),
      free: free.toFixed(2),
      askAgainstFree: askAgainstFree ? askAgainstFree.toFixed(4) : null,
    },
    profile: burning ? "cash_burning" : "cash_generative",
    runway,
    findings,
  };
}

packages/credit-analysis/src/trajectory..content:
import Decimal from "decimal.js";

import type {Finding} from "./analyze";

/**
 * The leverage trajectory: how the deal actually gets done.
 *
 * The static battery says the transaction as asked breaches the Itaú covenant on day one, and
 * that is a fact about the closing date, not a verdict on the deal. The founder's correction
 * was the desk's correction: the project's EBITDA has not arrived yet, and no company in this
 * position walks away, it structures. The instruments of that structure are exactly three, and
 * this module computes all of them instead of asserting them:
 *
 *   1. **Liability management.** The covenanted lines are refinanced inside the ticket, so the
 *      contract that would have tripped no longer exists. What binds afterwards is the new
 *      instrument's covenant, which is written to the trajectory rather than to the past.
 *   2. **The trajectory itself.** Net debt year by year (new money amortising SAC after grace,
 *      existing lines running to their own schedules) over EBITDA year by year as the project
 *      ramps. Peak leverage, and the year it crosses back under each threshold, on the
 *      company's numbers and on a stated haircut of them, because a fund underwrites the
 *      haircut case.
 *   3. **Covenant design.** A step-down schedule derived from the stressed trajectory plus a
 *      stated cushion, which is how the covenant is actually negotiated: wide at the peak,
 *      tightening as the project earns, never tighter than the base case can breathe.
 *
 * And one computation that reframes everything: principal falling due each year against the
 * EBITDA available to pay it. Aurora's existing schedule demands more amortisation in the next
 * eighteen months than the whole company generates, which means the refinancing is not a
 * choice the desk is making, it is a fact the current stack already contains.
 */

export type TrajectoryDebtLine = {
  lender: string;
  balance: string;
  /** ISO date. Absent → treated as beyond the horizon (held flat). */
  maturity?: string;
  /** Text from the schedule. "mensal"/"sac" amortises linearly to maturity; otherwise bullet. */
  amortization?: string;
  /** Whether this line carries a covenant, for the liability-management arithmetic. */
  hasCovenant?: boolean;
};

export type TrajectoryInput = {
  referenceDate: string;
  /**
   * Gross debt as the balance sheet states it, when it differs from the schedule's total.
   *
   * Camil measured why this matters: the debt map sums to R$ 5.742,5M and the balance sheet
   * recognises R$ 5.670,2M, a gap of R$ 72,3M in leases the map never lists. Sizing the
   * operation off the map and publishing leverage off the balance made a pure liability swap
   * read as 4,71x against a pre of 4,63x: the operation appeared to add leverage while adding
   * no debt at all. Post-transaction leverage is stated on the same base as the pre.
   */
  balanceGrossDebt?: string;
  /** Held flat across the horizon; stated as an assumption in the output. */
  cash: string;
  existing: TrajectoryDebtLine[];
  newDebt: {
    amount: string;
    termMonths: number;
    graceMonths: number;
    /**
     * Existing debt the proceeds repay at disbursement, when the room says so
     * (`transaction.refinancing`). Netted off the existing stack pro rata: the desk knows how
     * much is being taken out before it knows which contracts, and the leverage arithmetic
     * needs only the amount.
     */
    refinancing?: string;
  };
  /**
   * True when the projection is not the company's but the desk's fallback (EBITDA held at the
   * audited level), so the narrative says so instead of describing a ramp nobody promised.
   */
  ebitdaHeldFlat?: boolean;
  /** Most recent audited EBITDA, the base the haircut anchors on. */
  auditedEbitda: string;
  /** Projected EBITDA per calendar year, the company's own ramp. */
  projectedEbitda: Array<{year: number; ebitda: string}>;
  /**
   * Haircut applied to the *growth* over the audited base, not to the base itself: the company
   * already proved the base, the ramp is the part underwritten with suspicion. 0.25 = the fund
   * believes three quarters of the promised growth.
   */
  growthHaircut?: string;
  /** Cushion added to the stressed trajectory when proposing covenant step-downs. */
  covenantCushion?: string;
  /**
   * The tightest covenant the proposal will ever suggest. Mechanically the trajectory reaches
   * 0,25x by 2030, and no desk writes that: below a floor the covenant stops being a tripwire
   * for deterioration and becomes a tripwire for ordinary volatility. 2,5x is the
   * middle-market convention and the default.
   */
  covenantFloor?: string;
  /** Existing ceilings, for crossing years and the liability-management case. */
  existingCovenants: Array<{lender: string; maximum: string}>;
};

export type TrajectoryYear = {
  year: number;
  existingDebt: string;
  newDebt: string;
  netDebt: string;
  ebitdaBase: string;
  ebitdaStressed: string;
  leverageBase: string;
  leverageStressed: string;
  /** Principal contractually due in the year, existing schedule plus the new loan. */
  principalDue: string;
  /** principalDue / ebitdaBase: above 1 the schedule outruns the whole operation. */
  scheduleStrain: string;
};

export type LiabilityManagement = {
  covenantedBalance: string;
  netNewMoney: string;
  postLeverageAfterRefi: string;
  lendersTakenOut: string[];
};

export type CovenantStep = {year: number; maximum: string};

export type Trajectory = {
  assumptions: {cashHeldFlat: string; growthHaircut: string; covenantCushion: string; disbursement: string; ebitdaHeldFlat: boolean; refinancing: string};
  years: TrajectoryYear[];
  peak: {year: number; leverageBase: string; leverageStressed: string};
  crossings: Array<{maximum: string; yearBase: number | null; yearStressed: number | null}>;
  liabilityManagement: LiabilityManagement | null;
  covenantProposal: CovenantStep[];
  findings: Finding[];
};

const d = (value: string | number): Decimal => new Decimal(value);
const brlM = (value: Decimal.Value): string => `R$ ${new Decimal(value).div(1_000_000).toFixed(1).replace(".", ",")}M`;
const turns = (value: Decimal.Value): string => `${new Decimal(value).toFixed(2).replace(".", ",")}x`;

const yearMonth = (iso: string): number => {
  const [year, month] = iso.split("-").map(Number);
  return year! * 12 + (month! - 1);
};

/** Outstanding balance of an existing line at a year-end, on its own schedule. */
const existingAt = (line: TrajectoryDebtLine, referenceYm: number, atYm: number): Decimal => {
  if (atYm <= referenceYm) return d(line.balance);
  if (!line.maturity) return d(line.balance);
  const maturityYm = yearMonth(line.maturity);
  if (atYm >= maturityYm) return new Decimal(0);
  const amortizes = /mensal|sac|price/i.test(line.amortization ?? "");
  if (!amortizes) return d(line.balance);
  const total = maturityYm - referenceYm;
  const elapsed = atYm - referenceYm;
  return d(line.balance).times(total - elapsed).div(total);
};

/** Outstanding of the new loan at a year-end: flat through grace, SAC afterwards. */
const newDebtAt = (amount: Decimal, disbursementYm: number, graceMonths: number, termMonths: number, atYm: number): Decimal => {
  if (atYm <= disbursementYm) return amount;
  const amortMonths = termMonths - graceMonths;
  const amortised = Math.min(Math.max(atYm - disbursementYm - graceMonths, 0), amortMonths);
  return amount.times(amortMonths - amortised).div(amortMonths);
};

export function projectLeverageTrajectory(input: TrajectoryInput): Trajectory {
  const findings: Finding[] = [];
  const referenceYm = yearMonth(input.referenceDate);
  const cash = d(input.cash);
  const amount = d(input.newDebt.amount);
  const haircut = d(input.growthHaircut ?? "0.25");
  const cushion = d(input.covenantCushion ?? "0.5");
  const floor = d(input.covenantFloor ?? "2.5");
  const audited = d(input.auditedEbitda);

  // Proceeds that repay existing debt leave the stack on day one, nearest maturity first.
  //
  // Pro rata was the wrong model and it made every operation untestable: a refinancing that
  // takes out the parcels due in the next twelve months would also shrink the line maturing in
  // 2030 by the same factor, so the schedule after the operation looked better everywhere and
  // the desk could not say what the money actually bought. Nobody redeems pro rata. A company
  // pays down what is about to fall due, which is why it is raising in the first place.
  const existingTotalAtStart = input.existing.reduce((sum, line) => sum.plus(line.balance), new Decimal(0));
  const refinancing = Decimal.min(d(input.newDebt.refinancing ?? "0"), existingTotalAtStart);
  const byMaturity = [...input.existing].sort((a, b) => (a.maturity ?? "9999-12-31").localeCompare(b.maturity ?? "9999-12-31"));
  let toRedeem = refinancing;
  const redeemed = new Map<TrajectoryDebtLine, Decimal>();
  for (const line of byMaturity) {
    if (toRedeem.lte(0)) break;
    const take = Decimal.min(toRedeem, d(line.balance));
    redeemed.set(line, take);
    toRedeem = toRedeem.minus(take);
  }
  const existing: TrajectoryDebtLine[] = input.existing.map((line) => ({
    ...line,
    balance: d(line.balance).minus(redeemed.get(line) ?? 0).toFixed(2),
  }));

  const years: TrajectoryYear[] = input.projectedEbitda.map(({year, ebitda}) => {
    const atYm = year * 12 + 11; // December of the year.
    const prevYm = (year - 1) * 12 + 11;

    const existingNow = existing.reduce((sum, line) => sum.plus(existingAt(line, referenceYm, atYm)), new Decimal(0));
    const existingPrev = existing.reduce((sum, line) => sum.plus(existingAt(line, referenceYm, Math.max(prevYm, referenceYm))), new Decimal(0));
    const newNow = newDebtAt(amount, referenceYm, input.newDebt.graceMonths, input.newDebt.termMonths, atYm);
    const newPrev = newDebtAt(amount, referenceYm, input.newDebt.graceMonths, input.newDebt.termMonths, Math.max(prevYm, referenceYm));

    const netDebt = existingNow.plus(newNow).minus(cash);
    const base = d(ebitda);
    const stressed = audited.plus(Decimal.max(base.minus(audited), 0).times(new Decimal(1).minus(haircut)));
    const principalDue = existingPrev.minus(existingNow).plus(newPrev.minus(newNow));

    return {
      year,
      existingDebt: existingNow.toFixed(2),
      newDebt: newNow.toFixed(2),
      netDebt: netDebt.toFixed(2),
      ebitdaBase: base.toFixed(2),
      ebitdaStressed: stressed.toFixed(2),
      leverageBase: netDebt.div(base).toFixed(4),
      leverageStressed: netDebt.div(stressed).toFixed(4),
      principalDue: principalDue.toFixed(2),
      scheduleStrain: principalDue.div(base).toFixed(4),
    };
  });

  const peakYear = years.reduce((max, row) => (d(row.leverageStressed).gt(max.leverageStressed) ? row : max), years[0]!);

  const ceilings = [...new Set(input.existingCovenants.map((c) => d(c.maximum).toFixed(4)))].sort((a, b) => d(a).minus(b).toNumber());
  const crossings = ceilings.map((maximum) => ({
    maximum,
    yearBase: years.find((row) => d(row.leverageBase).lte(maximum))?.year ?? null,
    yearStressed: years.find((row) => d(row.leverageStressed).lte(maximum))?.year ?? null,
  }));

  // ---- liability management: take out the covenanted lines inside the ticket ------------------
  const covenanted = input.existing.filter((line) => line.hasCovenant);
  let liabilityManagement: LiabilityManagement | null = null;
  if (covenanted.length === 0 && refinancing.gt(0)) {
    // No single contract to take out: the covenant binds the whole stack and the room states how
    // much of it the proceeds repay. The arithmetic is the same, the lenders are "the schedule".
    const netNewMoney = amount.minus(refinancing);
    const grossPre = input.balanceGrossDebt ? d(input.balanceGrossDebt) : existingTotalAtStart;
    const postDebt = grossPre.plus(netNewMoney);
    const postLeverage = postDebt.minus(cash).div(audited);
    liabilityManagement = {
      covenantedBalance: refinancing.toFixed(2),
      netNewMoney: netNewMoney.toFixed(2),
      postLeverageAfterRefi: postLeverage.toFixed(4),
      lendersTakenOut: [],
    };
    findings.push({
      id: "refinancing-inside-ticket",
      severity: "high",
      pt: `A captação é, em ${brlM(refinancing)}, troca de passivo: esse valor resgata dívida existente no desembolso e sobra ${brlM(netNewMoney)} de dinheiro efetivamente novo. A alavancagem pós-operação é ${turns(postLeverage)} sobre o EBITDA reportado, não a soma ingênua do tíquete ao estoque. O que a operação compra é prazo e carência, e é contra isso que o fundo precifica.`,
      en: `${brlM(refinancing)} of the raise is a liability swap: it repays existing debt at disbursement, leaving ${brlM(netNewMoney)} of genuinely new money. Post-transaction leverage is ${turns(postLeverage)} on reported EBITDA, not the naive sum of ticket and stock. What the deal buys is tenor and grace, and that is what the fund prices.`,
      values: {refinancing: refinancing.toFixed(2), netNewMoney: netNewMoney.toFixed(2), postLeverage: postLeverage.toFixed(4)},
      inputs: ["transaction.refinancing", "transaction.requested_amount", "debt.instruments"],
    });
  }
  if (covenanted.length > 0) {
    const covenantedBalance = covenanted.reduce((sum, line) => sum.plus(line.balance), new Decimal(0));
    const netNewMoney = amount.minus(covenantedBalance);
    const existingTotal = input.existing.reduce((sum, line) => sum.plus(line.balance), new Decimal(0));
    const postDebt = existingTotal.minus(covenantedBalance).plus(amount);
    const postLeverage = postDebt.minus(cash).div(audited);
    liabilityManagement = {
      covenantedBalance: covenantedBalance.toFixed(2),
      netNewMoney: netNewMoney.toFixed(2),
      postLeverageAfterRefi: postLeverage.toFixed(4),
      lendersTakenOut: covenanted.map((line) => line.lender),
    };

    findings.push({
      id: "liability-management",
      severity: "high",
      pt: `A estrutura que destrava a operação é quitar as linhas com covenant dentro do tíquete: ${covenanted.map((line) => `${line.lender} (${brlM(line.balance)})`).join(" e ")}, ${brlM(covenantedBalance)} no total. O rompimento no dia um deixa de existir porque o contrato que testaria deixa de existir; sobra ${brlM(netNewMoney)} de dinheiro efetivamente novo, a alavancagem pós fica em ${turns(postLeverage)} sobre o EBITDA reportado, e quem passa a testar é o covenant do novo instrumento, desenhado sobre a trajetória abaixo. É assim que uma empresa nesta posição capta: reestruturação e dinheiro novo no mesmo instrumento, não dinheiro novo por cima do estoque.`,
      en: `The structure that unlocks the deal is refinancing the covenanted lines inside the ticket: ${covenanted.map((line) => `${line.lender} (${brlM(line.balance)})`).join(" and ")}, ${brlM(covenantedBalance)} in total. The day-one breach ceases to exist because the contract that would test it does; ${brlM(netNewMoney)} of genuinely new money remains, post leverage stands at ${turns(postLeverage)} on reported EBITDA, and what binds is the new instrument's covenant, written to the trajectory below. That is how a company in this position raises: restructuring and new money in one instrument, not new money on top of the stock.`,
      values: {covenantedBalance: covenantedBalance.toFixed(2), netNewMoney: netNewMoney.toFixed(2), postLeverage: postLeverage.toFixed(4)},
      inputs: ["debt.instruments", "debt.covenants", "transaction.requested_amount"],
    });
  }

  // ---- the schedule the current stack already demands -----------------------------------------
  const strained = years.filter((row) => d(row.scheduleStrain).gt("0.8"));
  if (strained.length > 0) {
    const worst = strained.reduce((max, row) => (d(row.scheduleStrain).gt(max.scheduleStrain) ? row : max));
    findings.push({
      id: "amortization-outruns-cash",
      severity: "critical",
      pt: `O cronograma contratado exige ${brlM(worst.principalDue)} de amortização em ${worst.year}, ${d(worst.scheduleStrain).times(100).toFixed(0)}% do EBITDA projetado do ano, antes de juros e de qualquer investimento. Esse ano não se paga com o caixa da operação, então ele será rolado: a pergunta não é se rola, é a que preço e com que prazo. Alongar resolve e custa spread e garantia; dimensionar a captação para cobrir ${worst.year} agora custa tíquete maior e alavancagem de pico mais alta. As duas saídas são defensáveis, e a escolha entre elas é o que o material precisa mostrar ao investidor.`,
      en: `The contracted schedule demands ${brlM(worst.principalDue)} of amortisation in ${worst.year}, ${d(worst.scheduleStrain).times(100).toFixed(0)}% of that year's projected EBITDA, before interest and any investment. That year will not be paid out of operating cash, so it will be rolled: the question is not whether, but at what price and tenor. Terming it out works and costs spread and security; sizing the raise to cover ${worst.year} now costs a larger ticket and a higher peak leverage. Both are defensible, and choosing between them is what the material has to show the investor.`,
      values: {year: String(worst.year), principalDue: worst.principalDue, strain: worst.scheduleStrain},
      inputs: ["debt.instruments", "projections.ebitda"],
    });
  }

  // ---- trajectory and the covenant that follows it --------------------------------------------
  const covenantProposal: CovenantStep[] = years.map((row) => {
    const stepped = d(row.leverageStressed).plus(cushion);
    const rounded = stepped.times(4).ceil().div(4); // to the nearest upper quarter turn
    return {year: row.year, maximum: Decimal.max(rounded, floor).toFixed(2)};
  });

  const back = crossings.find((crossing) => d(crossing.maximum).eq(ceilings[0] ?? "3"));
  findings.push({
    id: "leverage-trajectory",
    severity: "info",
    pt: `Trajetória${input.ebitdaHeldFlat ? " (sem projeção da companhia: EBITDA mantido no nível do último exercício, premissa da mesa)" : ""}: pico de ${turns(peakYear.leverageBase)} (${turns(peakYear.leverageStressed)} no cenário com corte de ${haircut.times(100).toFixed(0)}% do crescimento) em ${peakYear.year}, desalavancando pela amortização SAC${input.ebitdaHeldFlat ? "" : " e pela rampa do projeto"}${back && back.yearStressed ? `, e voltando abaixo de ${turns(back.maximum)} em ${back.yearStressed} mesmo no cenário cortado` : ""}. Covenant proposto para o novo instrumento, com folga de ${cushion.toFixed(2).replace(".", ",")}x sobre o cenário cortado e teste anual: ${covenantProposal.map((step) => `${step.year} ≤ ${step.maximum.replace(".", ",")}x`).join("; ")}. Primeira aferição no primeiro exercício completo após o desembolso.`,
    en: `Trajectory${input.ebitdaHeldFlat ? " (no company projection: EBITDA held at the latest audited level, a desk assumption)" : ""}: peak of ${turns(peakYear.leverageBase)} (${turns(peakYear.leverageStressed)} with ${haircut.times(100).toFixed(0)}% of the growth cut) in ${peakYear.year}, deleveraging through SAC amortisation${input.ebitdaHeldFlat ? "" : " and the project ramp"}${back && back.yearStressed ? `, and back under ${turns(back.maximum)} by ${back.yearStressed} even in the cut scenario` : ""}. Proposed covenant for the new instrument, ${cushion.toFixed(2)}x of cushion over the cut scenario, tested annually: ${covenantProposal.map((step) => `${step.year} ≤ ${step.maximum}x`).join("; ")}. First test at the first full year after disbursement.`,
    values: {peakBase: peakYear.leverageBase, peakStressed: peakYear.leverageStressed, peakYear: String(peakYear.year)},
    inputs: ["projections.ebitda", "debt.instruments", "transaction.requested_amount"],
  });

  const order = {critical: 0, high: 1, medium: 2, info: 3};
  findings.sort((a, b) => order[a.severity] - order[b.severity]);

  return {
    assumptions: {
      cashHeldFlat: cash.toFixed(2),
      growthHaircut: haircut.toFixed(4),
      covenantCushion: cushion.toFixed(4),
      disbursement: input.referenceDate,
      ebitdaHeldFlat: input.ebitdaHeldFlat ?? false,
      refinancing: refinancing.toFixed(2),
    },
    years,
    peak: {year: peakYear.year, leverageBase: peakYear.leverageBase, leverageStressed: peakYear.leverageStressed},
    crossings,
    liabilityManagement,
    covenantProposal,
    findings,
  };
}

packages/credit-analysis/src/from-facts..content:
import type {DebtLineInput, DeskInput} from "./analyze";
import type {TrajectoryInput} from "./trajectory";

/**
 * From reconciled facts to desk inputs.
 *
 * The extractor speaks the ontology's field paths (`debt.instruments.3.rate`,
 * `historical_financials.2025.ebitda`), and the battery speaks structured input. This is the
 * bridge, and it is deliberately dumb: it groups, it picks the latest year, it never fills a
 * hole with a guess. What cannot be built is reported in `missing`, in field-path language,
 * so the gap surfaces as a question to the company instead of as a silently absent analysis.
 */

export type Fact = {fieldPath: string; value: string};

export type DeskInputsOptions = {
  referenceDate: string;
  /** A market assumption of the analysis, stated by the caller, never invented here. */
  indexLevels: {cdi: string; tlp?: string; ipca?: string; selic?: string; tr?: string};
  /** What the company stated in the product itself, alongside what the documents say. */
  statedRequest?: {amount?: string; termMonths?: number; graceMonths?: number; expectedRate?: string};
};

export type DeskInputs = {
  desk: DeskInput | null;
  trajectory: TrajectoryInput | null;
  /** What kept either analysis from being built, as field paths a reviewer recognises. */
  missing: string[];
};

const indexed = (facts: Fact[], prefix: string): Map<number, Map<string, string>> => {
  const groups = new Map<number, Map<string, string>>();
  const pattern = new RegExp(`^${prefix.replace(/\./g, "\\.")}\\.(\\d+)\\.([a-z_]+)$`);
  for (const fact of facts) {
    const match = fact.fieldPath.match(pattern);
    if (!match) continue;
    const index = Number(match[1]);
    if (!groups.has(index)) groups.set(index, new Map());
    groups.get(index)!.set(match[2]!, fact.value);
  }
  return groups;
};

export function buildDeskInputs(facts: Fact[], options: DeskInputsOptions): DeskInputs {
  const missing: string[] = [];
  const byPath = new Map(facts.map((fact) => [fact.fieldPath, fact.value]));
  const value = (path: string): string | undefined => byPath.get(path);

  // ---- the latest audited year ---------------------------------------------------------------
  const years = [...new Set(
    facts
      .map((fact) => fact.fieldPath.match(/^historical_financials\.(\d{4})\./)?.[1])
      .filter((year): year is string => Boolean(year)),
  )].map(Number).sort((a, b) => b - a);
  const latest = years[0];

  const revenue = latest ? value(`historical_financials.${latest}.revenue`) : undefined;
  const ebitda = latest ? value(`historical_financials.${latest}.ebitda`) : undefined;
  if (!revenue) missing.push("historical_financials.{ano}.revenue");
  if (!ebitda) missing.push("historical_financials.{ano}.ebitda");

  const cash = latest ? value(`historical_financials.${latest}.cash`) : undefined;
  const receivables = latest ? value(`historical_financials.${latest}.receivables`) : undefined;
  const grossDebt = latest ? value(`historical_financials.${latest}.gross_debt`) : undefined;
  if (!cash) missing.push("historical_financials.{ano}.cash");
  if (!grossDebt) missing.push("historical_financials.{ano}.gross_debt");

  // ---- debt lines ----------------------------------------------------------------------------
  const debtGroups = indexed(facts, "debt.instruments");
  const covenantGroups = indexed(facts, "debt.covenants");
  const covenantTexts = [...covenantGroups.values()]
    .map((group) => {
      const metric = group.get("metric");
      const threshold = group.get("threshold");
      return metric && threshold ? `${metric} <= ${threshold.replace(".", ",")}x` : null;
    })
    .filter((text): text is string => text !== null);

  const debt: DebtLineInput[] = [...debtGroups.entries()]
    .sort(([a], [b]) => a - b)
    .flatMap(([, group]) => {
      const lender = group.get("lender");
      const balance = group.get("balance");
      if (!lender || !balance) return [];
      return [{
        lender,
        balance,
        ...(group.get("instrument_type") !== undefined ? {instrumentType: group.get("instrument_type")!} : {}),
        ...(group.get("rate") !== undefined ? {rate: group.get("rate")!} : {}),
        ...(group.get("maturity") !== undefined ? {maturity: group.get("maturity")!} : {}),
        ...(group.get("amortization") !== undefined ? {amortization: group.get("amortization")!} : {}),
        ...(group.get("collateral") !== undefined ? {collateral: group.get("collateral")!} : {}),
        ...(group.get("covenants") !== undefined ? {covenant: group.get("covenants")!} : {}),
      }];
    });
  if (debt.length === 0) missing.push("debt.instruments");

  // Covenants stated as a table rather than per line bind the company, not one lender. A
  // listed company's note says "os principais instrumentos" and names nobody; pinning that
  // ceiling on whichever line happens to be first would invent a contract. They go in as
  // company-level covenants, labelled by their scope.
  const companyCovenants = covenantTexts.map((text) => ({scope: "escrituras e contratos da companhia", text}));

  // ---- interim -------------------------------------------------------------------------------
  // The most recent balance sheet wins as the anchor for stock figures. A schedule dated May
  // against a balance dated February reads as R$ 750M of phantom debt; the stack, the cash and
  // the receivables must be read on the same date, and that date is the latest one the room has.
  const interimPeriods = [...new Set(
    facts
      .map((fact) => fact.fieldPath.match(/^interim_financials\.(\d{4}_\d{2})\./)?.[1])
      .filter((period): period is string => Boolean(period)),
  )].sort().reverse();
  const period = interimPeriods[0];
  let interim: DeskInput["interim"];
  if (period) {
    const [year, month] = period.split("_").map(Number);
    const find = (metric: string) =>
      facts.find((fact) => new RegExp(`^interim_financials\\.${period}\\.${metric}(_\\d+m|_ytd|_ltm)?$`).test(fact.fieldPath))?.value;
    const interimRevenue = find("revenue");
    if (interimRevenue) {
      interim = {
        periodEnd: `${year}-${String(month).padStart(2, "0")}-28`,
        months: month!,
        revenue: interimRevenue,
        ...(find("ebitda") !== undefined ? {ebitda: find("ebitda")!} : {}),
        ...(find("receivables") !== undefined ? {receivables: find("receivables")!} : {}),
        ...(find("cash") !== undefined ? {cash: find("cash")!} : {}),
      };
    }
  }

  const interimCash = period ? facts.find((fact) => fact.fieldPath === `interim_financials.${period}.cash`)?.value : undefined;
  const interimGrossDebt = period ? facts.find((fact) => fact.fieldPath === `interim_financials.${period}.gross_debt`)?.value : undefined;
  const interimReceivables = period ? facts.find((fact) => fact.fieldPath === `interim_financials.${period}.receivables`)?.value : undefined;
  const interimInventory = period ? facts.find((fact) => fact.fieldPath === `interim_financials.${period}.inventory`)?.value : undefined;
  const interimPayables = period ? facts.find((fact) => fact.fieldPath === `interim_financials.${period}.payables`)?.value : undefined;
  const anchorOnInterim = Boolean(period && interimCash && interimGrossDebt && interimReceivables);
  const balanceCash = anchorOnInterim ? interimCash : cash;
  const balanceGrossDebt = anchorOnInterim ? interimGrossDebt : grossDebt;
  const balanceReceivables = anchorOnInterim ? interimReceivables : receivables;
  const balanceInventory = anchorOnInterim ? interimInventory : latest ? value(`historical_financials.${latest}.inventory`) : undefined;
  const balancePayables = anchorOnInterim ? interimPayables : latest ? value(`historical_financials.${latest}.payables`) : undefined;
  const balancePeriodEnd = anchorOnInterim ? interim?.periodEnd ?? `${period!.replace("_", "-")}-28` : `${latest}-12-31`;

  // ---- the request: documents and the product's own form, side by side -----------------------
  const amounts: Array<{value: string; source: string}> = [];
  const fromDocuments = value("transaction.requested_amount");
  if (fromDocuments) amounts.push({value: fromDocuments, source: "documentos"});
  const stated = options.statedRequest?.amount;
  if (stated && (!fromDocuments || stated !== fromDocuments)) {
    amounts.push({value: stated, source: "informado pela empresa"});
  }
  if (amounts.length === 0) missing.push("transaction.requested_amount");

  const uses = indexed(facts, "transaction.use_of_proceeds");
  const workingCapitalAsk = [...uses.values()].find((group) => /giro|working capital/i.test(group.get("item") ?? ""))?.get("amount");

  const termMonths = options.statedRequest?.termMonths ?? numberOf(value("transaction.desired_term_months"));
  const graceMonths = options.statedRequest?.graceMonths ?? numberOf(value("transaction.desired_grace_months"));
  const rateAsk = options.statedRequest?.expectedRate ?? value("transaction.expected_rate");
  const refinancing = value("transaction.refinancing");

  // ---- projections ---------------------------------------------------------------------------
  const projectionYears = [...new Set(
    facts
      .map((fact) => fact.fieldPath.match(/^projections\.(\d{4})\.ebitda$/)?.[1])
      .filter((year): year is string => Boolean(year)),
  )].map(Number).sort((a, b) => a - b);
  const companyProjections = projectionYears.map((year) => ({year, ebitda: value(`projections.${year}.ebitda`)!}));
  // No projection from the company is a question for the company, not a reason to have no
  // trajectory: the desk runs it on EBITDA held flat and says so. A listed company rarely
  // sends a model; a desk never waits for one to know whether the schedule is serviceable.
  const ebitdaHeldFlat = companyProjections.length === 0 && latest !== undefined && ebitda !== undefined;
  const projectedEbitda = ebitdaHeldFlat
    ? Array.from({length: 5}, (_, offset) => ({year: latest! + 1 + offset, ebitda: ebitda!}))
    : companyProjections;
  const nextRevenue = latest ? value(`projections.${latest + 1}.revenue`) : undefined;

  // ---- the amortisation profile, by window ---------------------------------------------------
  const profileGroups = indexed(facts, "debt.maturity_profile");
  const maturityProfile = [...profileGroups.entries()]
    .sort(([a], [b]) => a - b)
    .flatMap(([, group]) => {
      const window = group.get("window");
      const amount = group.get("amount");
      if (!window || !amount) return [];
      const endsOn = windowEnd(window);
      return [{window, amount, ...(endsOn ? {endsOn} : {})}];
    });

  // ---- what a venture lender reads -----------------------------------------------------------
  const latestOf = (metric: string): string | undefined =>
    facts
      .filter((fact) => new RegExp(`^(historical|interim)_financials\\.\\d{4}(_\\d{2})?\\.${metric}(_\\d+m|_ytd|_ltm)?$`).test(fact.fieldPath))
      .sort((a, b) => b.fieldPath.localeCompare(a.fieldPath))[0]?.value;
  const ventureEntries: Array<[string, string | undefined]> = [
    ["arr", latestOf("arr")],
    ["mrr", latestOf("mrr")],
    ["monthlyBurn", latestOf("monthly_burn")],
    ["runwayMonthsStated", value("company.runway_months")],
    ["lastEquityRoundAmount", value("company.last_equity_round.amount")],
    ["lastEquityRoundDate", value("company.last_equity_round.date")],
    ["nrr", value("company.net_revenue_retention")],
    ["monthlyChurn", value("company.monthly_churn_pct")],
    ["topCustomerShare", value("customers.top_customers.1.share_pct")],
  ];
  const venture = Object.fromEntries(ventureEntries.filter((entry): entry is [string, string] => entry[1] !== undefined)) as NonNullable<DeskInput["venture"]>;
  const hasVenture = Object.keys(venture).length > 0;

  // ---- assemble, honestly --------------------------------------------------------------------
  const canDesk = Boolean(revenue && ebitda && balanceCash && balanceGrossDebt && balanceReceivables && amounts.length > 0);
  const desk: DeskInput | null = canDesk
    ? {
        indexLevels: options.indexLevels,
        referenceDate: options.referenceDate,
        audited: {
          year: latest!,
          revenue: revenue!,
          ebitda: ebitda!,
          ...(latest && value(`historical_financials.${latest}.cogs`) !== undefined
            ? {cogs: value(`historical_financials.${latest}.cogs`)!}
            : {}),
          ...(latest && value(`historical_financials.${latest}.financial_expenses`) !== undefined
            ? {financialExpenses: value(`historical_financials.${latest}.financial_expenses`)!}
            : {}),
        },
        balance: {
          periodEnd: balancePeriodEnd,
          cash: balanceCash!,
          receivables: balanceReceivables!,
          grossDebt: balanceGrossDebt!,
          ...(balanceInventory !== undefined ? {inventory: balanceInventory} : {}),
          ...(balancePayables !== undefined ? {suppliers: balancePayables} : {}),
        },
        ...(interim ? {interim} : {}),
        debt,
        ...(companyCovenants.length > 0 ? {covenants: companyCovenants} : {}),
        ...(hasVenture ? {venture} : {}),
        ...(maturityProfile.length > 0 ? {maturityProfile} : {}),
        request: {
          amounts,
          ...(termMonths !== undefined ? {termMonths} : {}),
          ...(graceMonths !== undefined ? {graceMonths} : {}),
          ...(rateAsk !== undefined ? {rateAsk} : {}),
          ...(workingCapitalAsk !== undefined ? {workingCapitalAsk} : {}),
        },
        ...(nextRevenue && latest ? {projectedNextYear: {year: latest + 1, revenue: nextRevenue}} : {}),
      }
    : null;

  // A leverage trajectory over a negative EBITDA is arithmetic without meaning; the cash-burning
  // company is read through its runway, inside the desk analysis.
  const canTrajectory = Boolean(
    desk && ebitda && Number(ebitda) > 0 && projectedEbitda.length > 0 && amounts.length > 0 && termMonths !== undefined && graceMonths !== undefined,
  );
  // Still asked for, even when the trajectory ran on the fallback: the company's own ramp is
  // the number the fund will underwrite, and the desk's flat line is a placeholder, not an answer.
  if (desk && companyProjections.length === 0) missing.push("projections.{ano}.ebitda");
  if (desk && !canTrajectory) {
    if (termMonths === undefined) missing.push("transaction.desired_term_months");
    if (graceMonths === undefined) missing.push("transaction.desired_grace_months");
  }
  const trajectory: TrajectoryInput | null = canTrajectory
    ? {
        referenceDate: options.referenceDate,
        cash: balanceCash!,
        ...(balanceGrossDebt !== undefined ? {balanceGrossDebt} : {}),
        existing: debt.map((line) => ({
          lender: line.lender,
          balance: line.balance,
          ...(line.maturity !== undefined ? {maturity: line.maturity} : {}),
          ...(line.amortization !== undefined ? {amortization: line.amortization} : {}),
          ...(line.covenant !== undefined ? {hasCovenant: true} : {}),
        })),
        // The larger stated amount, because sizing against the smaller one understates the risk
        // the fund will price, and the divergence itself is already a finding.
        newDebt: {
          amount: amounts.map((entry) => entry.value).sort((a, b) => Number(b) - Number(a))[0]!,
          termMonths: termMonths!,
          graceMonths: graceMonths!,
          ...(refinancing !== undefined ? {refinancing} : {}),
        },
        auditedEbitda: ebitda!,
        projectedEbitda,
        ...(ebitdaHeldFlat ? {ebitdaHeldFlat: true} : {}),
        existingCovenants: [
          ...debt
            .filter((line) => line.covenant !== undefined)
            .map((line) => {
              const match = line.covenant!.match(/([\d.,]+)\s*x/);
              return match ? {lender: line.lender, maximum: match[1]!.replace(",", ".")} : null;
            })
            .filter((entry): entry is {lender: string; maximum: string} => entry !== null),
          ...companyCovenants
            .map((entry) => {
              const match = entry.text.match(/([\d.,]+)\s*x/);
              return match ? {lender: entry.scope, maximum: match[1]!.replace(",", ".")} : null;
            })
            .filter((entry): entry is {lender: string; maximum: string} => entry !== null),
        ],
      }
    : null;

  return {desk, trajectory, missing};
}

const MONTHS: Record<string, number> = {jan: 1, fev: 2, feb: 2, mar: 3, abr: 4, apr: 4, mai: 5, may: 5, jun: 6, jul: 7, ago: 8, aug: 8, set: 9, sep: 9, out: 10, oct: 10, nov: 11, dez: 12, dec: 12};

/**
 * The last month of a window as a note writes it: "Jun/26 a Mai/27" → 2027-05-31, "2028" →
 * 2028-12-31, "Jun/28 a Mai/29" → 2029-05-31. "Após Jun/31" has no end and returns undefined,
 * which keeps it out of every "within N months" sum, as it should be.
 */
export const windowEnd = (window: string): string | undefined => {
  const text = window.trim().toLowerCase();
  if (/^(após|apos|after|a partir)/.test(text)) return undefined;
  const monthYear = [...text.matchAll(/([a-zç]{3})[a-zç]*\.?\/?\s*(\d{2,4})/g)];
  const last = monthYear.at(-1);
  if (last && MONTHS[last[1]!]) {
    const year = last[2]!.length === 2 ? 2000 + Number(last[2]) : Number(last[2]);
    return `${year}-${String(MONTHS[last[1]!]).padStart(2, "0")}-28`;
  }
  const year = text.match(/(20\d{2})(?!.*20\d{2})/);
  if (year) return `${year[1]}-12-31`;
  return undefined;
};

const numberOf = (raw: string | undefined): number | undefined => {
  if (raw === undefined) return undefined;
  const parsed = Number(raw);
  return Number.isFinite(parsed) ? parsed : undefined;
};

packages/credit-analysis/src/questions.t.content:
import Decimal from "decimal.js";

import type {DeskAnalysis} from "./analyze";
import type {Trajectory} from "./trajectory";

/**
 * The questions the desk asks the company, generated from what the numbers exposed.
 *
 * "Envie mais documentos" is what a portal says. A desk asks the question the analysis opened,
 * with the numbers in it, and each question here carries the finding it came from, so the
 * conversation with the company is the analysis continuing rather than a checklist beside it.
 * The order is the meeting's order: what changes the deal first.
 */

export type ClientQuestion = {
  /** The finding or gap this question exists because of. */
  findingId: string;
  severity: "critical" | "high" | "medium";
  pt: string;
  en: string;
};

const brlM = (value: Decimal.Value): string => `R$ ${new Decimal(value).div(1_000_000).toFixed(1).replace(".", ",")}M`;

export function questionsForCompany(
  desk: DeskAnalysis | null,
  trajectory: Trajectory | null,
  missing: readonly string[] = [],
): ClientQuestion[] {
  const questions: ClientQuestion[] = [];
  if (!desk) {
    return missing.map((path) => ({
      findingId: `missing:${path}`,
      severity: "high" as const,
      pt: `A análise de crédito não pôde ser montada sem ${path}. Consegue enviar o documento que traz essa informação?`,
      en: `The credit analysis could not be assembled without ${path}. Can you send the document that carries it?`,
    }));
  }

  const has = (id: string) => desk.findings.some((finding) => finding.id === id);
  const finding = (id: string) => desk.findings.find((entry) => entry.id === id);

  if (has("amount-divergence")) {
    const values = finding("amount-divergence")!.values;
    const amounts = Object.values(values).map((value) => brlM(value)).join(" e ");
    questions.push({
      findingId: "amount-divergence",
      severity: "critical",
      pt: `A documentação pede dois valores diferentes: ${amounts}. Qual é o valor da operação? Nenhum material vai a mercado antes dessa resposta.`,
      en: `The documentation asks for two different amounts: ${amounts}. Which is the transaction size? No material goes to market before this answer.`,
    });
  }

  if (has("covenant-breach-day-one")) {
    const values = finding("covenant-breach-day-one")!.values;
    questions.push({
      findingId: "covenant-breach-day-one",
      severity: "critical",
      pt: new Decimal(values.maxNewDebt!).lt(0)
        ? `A alavancagem já está acima do covenant (${values.pre ? `${new Decimal(values.pre).toFixed(2).replace(".", ",")}x` : ""} contra ${new Decimal(values.ceiling!).toFixed(2).replace(".", ",")}x). Qual é o plano até a próxima medição: geração de caixa sazonal, venda de ativos, resgate de linhas com a captação, ou waiver já negociado com os credores? A resposta define se a operação é troca de passivo ou dinheiro novo.`
        : `Do jeito pedido, a operação rompe covenant existente no primeiro dia (${brlM(values.maxNewDebt!)} caberiam; o pedido é maior). O desenho natural é quitar as linhas com covenant dentro da captação. A companhia está aberta a incluir essa quitação na operação, ou prefere renegociar os covenants com os bancos atuais?`,
      en: new Decimal(values.maxNewDebt!).lt(0)
        ? `Leverage is already above the covenant (${values.pre ? `${new Decimal(values.pre).toFixed(2)}x` : ""} against ${new Decimal(values.ceiling!).toFixed(2)}x). What is the plan to the next test: seasonal cash generation, asset sales, lines repaid with the raise, or a waiver already agreed with creditors? The answer decides whether this deal is a liability swap or new money.`
        : `As asked, the transaction breaches an existing covenant on day one (${brlM(values.maxNewDebt!)} would fit; the ask is larger). The natural structure takes out the covenanted lines inside the raise. Is the company open to including that takeout, or would it rather renegotiate the covenants with the incumbent banks?`,
    });
  }

  if (has("short-term-principal-vs-cash")) {
    const values = finding("short-term-principal-vs-cash")!.values;
    questions.push({
      findingId: "short-term-principal-vs-cash",
      severity: new Decimal(values.coverage!).lt(1) ? "critical" : "high",
      pt: `${brlM(values.maturing12!)} de principal vencem em 12 meses contra ${brlM(values.cash!)} de caixa. Qual é o fluxo de caixa mensal projetado para esse período, com a sazonalidade de compras, e quais dessas parcelas já têm renovação acertada com o credor?`,
      en: `${brlM(values.maturing12!)} of principal falls due within 12 months against ${brlM(values.cash!)} of cash. What is the projected monthly cash flow for that period, with purchasing seasonality, and which of those instalments already have a renewal agreed with the lender?`,
    });
  }

  if (has("runway-short")) {
    const values = finding("runway-short")!.values;
    questions.push({
      findingId: "runway-short",
      severity: "critical",
      pt: `O runway atual é de ${new Decimal(values.monthsPre!).toFixed(1).replace(".", ",")} meses. Qual é o plano de caixa mês a mês até a próxima rodada, e o que é cortado se ela atrasar um trimestre? Os fundos atuais já confirmaram por escrito a reserva para acompanhar?`,
      en: `Current runway is ${new Decimal(values.monthsPre!).toFixed(1)} months. What is the month-by-month cash plan to the next round, and what gets cut if it slips a quarter? Have the current funds confirmed follow-on reserves in writing?`,
    });
  }

  if (has("runway-stated-vs-computed")) {
    const values = finding("runway-stated-vs-computed")!.values;
    questions.push({
      findingId: "runway-stated-vs-computed",
      severity: "high",
      pt: `A carta fala em ${new Decimal(values.stated!).toFixed(0)} meses de runway e o extrato dá ${new Decimal(values.computed!).toFixed(1).replace(".", ",")}. Qual queima mensal a companhia usa, e o que muda nela nos próximos seis meses?`,
      en: `The letter says ${new Decimal(values.stated!).toFixed(0)} months of runway and the statement gives ${new Decimal(values.computed!).toFixed(1)}. Which monthly burn does the company use, and what changes in it over the next six months?`,
    });
  }

  if (has("debt-to-arr")) {
    const values = finding("debt-to-arr")!.values;
    questions.push({
      findingId: "debt-to-arr",
      severity: "high",
      pt: `Com a captação, a dívida chega a ${new Decimal(values.debtToArr!).times(100).toFixed(0)}% do ARR. A companhia aceita um tíquete menor em tranches liberadas contra marcos de ARR, ou prefere manter o valor e oferecer warrant maior?`,
      en: `With the raise, debt reaches ${new Decimal(values.debtToArr!).times(100).toFixed(0)}% of ARR. Would the company take a smaller ticket in tranches released against ARR milestones, or keep the amount and offer a larger warrant?`,
    });
  }

  if (has("customer-concentration")) {
    const values = finding("customer-concentration")!.values;
    questions.push({
      findingId: "customer-concentration",
      severity: "high",
      pt: `O maior cliente é ${new Decimal(values.topCustomerShare!).times(100).toFixed(0)}% do MRR. Qual é o prazo e a cláusula de rescisão do contrato, e quando foi a última renovação?`,
      en: `The largest customer is ${new Decimal(values.topCustomerShare!).times(100).toFixed(0)}% of MRR. What are the contract's term and termination clause, and when was it last renewed?`,
    });
  }

  if (has("nrr-below-par")) {
    questions.push({
      findingId: "nrr-below-par",
      severity: "high",
      pt: "A retenção líquida está abaixo de 100%. Qual é a análise de coortes dos últimos 12 meses, separando contração, churn e expansão, e o que explica cada uma?",
      en: "Net revenue retention is below 100%. What is the cohort analysis for the last 12 months, splitting contraction, churn and expansion, and what explains each?",
    });
  }

  if (has("stack-vs-balance")) {
    const values = finding("stack-vs-balance")!.values;
    questions.push({
      findingId: "stack-vs-balance",
      severity: "critical",
      pt: new Decimal(values.gap!).gte(0)
        ? `O balanço reconhece ${brlM(values.gap!)} de dívida que o mapa não lista. O que compõe essa diferença? Se for arrendamento mercantil, precisamos dos contratos ou da nota explicativa detalhada.`
        : `O mapa de dívida soma ${brlM(new Decimal(values.gap!).abs())} a mais do que o balanço reconhece na data-base. O mapa inclui juros apropriados, custo de transação ou linhas de controladas que o balanço apresenta em outra rubrica? Precisamos da conciliação mapa × balanço na mesma data.`,
      en: new Decimal(values.gap!).gte(0)
        ? `The balance sheet recognises ${brlM(values.gap!)} of debt the schedule does not list. What makes up the difference? If it is leasing, we need the contracts or the detailed note.`
        : `The debt schedule sums to ${brlM(new Decimal(values.gap!).abs())} more than the balance sheet recognises at the reference date. Does the schedule include accrued interest, transaction costs or subsidiary lines the balance sheet presents elsewhere? We need the schedule-to-balance reconciliation on the same date.`,
    });
  }

  if (has("wc-ask-vs-need")) {
    const values = finding("wc-ask-vs-need")!.values;
    questions.push({
      findingId: "wc-ask-vs-need",
      severity: "high",
      pt: `O crescimento projetado absorve ${brlM(values.need!)} de capital de giro, mas o pedido rotula ${brlM(values.ask!)} como giro. O que a diferença financia: alongamento do ciclo, recomposição de caixa, substituição de linhas? O fundo vai perguntar, e a resposta muda a estrutura.`,
      en: `Projected growth absorbs ${brlM(values.need!)} of working capital, yet the ask labels ${brlM(values.ask!)} as working capital. What does the difference fund: a longer cycle, cash rebuild, line replacement? The fund will ask, and the answer changes the structure.`,
    });
  }

  if (has("rate-ask-vs-stack")) {
    questions.push({
      findingId: "rate-ask-vs-stack",
      severity: "high",
      pt: `A taxa esperada está abaixo do custo médio do estoque atual, para dinheiro mais alavancado e mais junior. Antes da conversa com fundos: a expectativa comporta revisão, ou existe âncora (garantia adicional, aval, recebível específico) que justifique o nível pedido?`,
      en: `The expected rate sits below the current stack's average cost, for more levered, more junior money. Before any fund conversation: is the expectation open to revision, or is there an anchor (extra collateral, guarantees, a specific receivable) that supports the level asked?`,
    });
  }

  if (has("receivables-encumbrance")) {
    const values = finding("receivables-encumbrance")!.values;
    questions.push({
      findingId: "receivables-encumbrance",
      severity: "high",
      pt: `Dos recebíveis, ${brlM(values.free!)} estão livres e o pedido consome quase tudo. Existe outra base de garantia disponível (imóveis, frota livre, estoque), ou a operação deve liberar as duplicatas hoje caucionadas quitando as linhas correspondentes?`,
      en: `Of the receivables, ${brlM(values.free!)} is free and the ask consumes nearly all of it. Is another collateral base available (property, unencumbered fleet, inventory), or should the transaction free today's pledged receivables by taking out the corresponding lines?`,
    });
  }

  if (has("grace-vs-project")) {
    const values = finding("grace-vs-project")!.values;
    questions.push({
      findingId: "grace-vs-project",
      severity: "medium",
      pt: `A carência pedida termina ${values.gapMonths} meses antes de o projeto operar, e esse intervalo é servido pelo caixa atual. A companhia prefere carência maior (com custo), ou demonstra a folga de caixa do intervalo nas projeções?`,
      en: `The requested grace ends ${values.gapMonths} months before the project operates, and that interval is served by current cash. Does the company prefer longer grace (at a cost), or will it evidence the interval's cash headroom in the projections?`,
    });
  }

  for (const path of missing) {
    questions.push({
      findingId: `missing:${path}`,
      severity: "medium",
      pt: `Falta ${path} para completar a análise. Consegue enviar o documento que traz essa informação?`,
      en: `${path} is missing from the analysis. Can you send the document that carries it?`,
    });
  }

  void trajectory;
  const order = {critical: 0, high: 1, medium: 2};
  return questions.sort((a, b) => order[a.severity] - order[b.severity]);
}

packages/credit-analysis/src/rating.ts.content:
import Decimal from "decimal.js";

import type {DeskAnalysis} from "./analyze";
import type {Trajectory} from "./trajectory";

/**
 * The internal rating: the first thing a committee asks for, written down as arithmetic.
 *
 * Ten grades, from 1 (the strongest credit this desk sees) to 10 (a credit it would not take
 * to market), built from seven factors a head of credit reads in this order: leverage,
 * interest coverage, liquidity against the next twelve months, the direction of the numbers,
 * concentration, the quality of the evidence, and, for a company that burns cash, runway in
 * place of the first two. Every factor carries its value, the band it fell in, the points it
 * earned and the sentence that says why, so the grade can be argued line by line instead of
 * trusted.
 *
 * The scale is the desk's, not an agency's. It is deliberately written as data a credit
 * professional can disagree with: change a threshold here and every case is re-rated the same
 * way, which is the whole point of writing it down.
 */

export type RatingFactor = {
  id: "leverage" | "coverage" | "liquidity" | "trend" | "concentration" | "evidence" | "runway";
  labels: {pt: string; en: string};
  /** The number the factor read, as a decimal string, or null when the room did not carry it. */
  value: string | null;
  /** 0 (worst) to 4 (best); null when not assessable. */
  points: number | null;
  weight: number;
  rationale: {pt: string; en: string};
};

export type InternalRating = {
  /** 1 (strongest) to 10 (weakest). */
  grade: number;
  /** 0 to 100: weighted points over the maximum the assessable factors allowed. */
  score: number;
  /** Coverage of the scale: factors the room let the desk assess, over the seven. */
  assessed: number;
  factors: RatingFactor[];
  /** The band a lender reads the grade in. */
  band: "strong" | "adequate" | "watch" | "weak" | "distressed";
  summary: {pt: string; en: string};
};

export type RatingInput = {
  desk: DeskAnalysis;
  trajectory: Trajectory | null;
  /** Interest expense of the latest audited year, when the room states it. */
  financialExpenses?: string;
  /** EBITDA of the year before, when known, for the trend. */
  priorEbitda?: string;
  /** Share of revenue (or MRR) in the largest customer, as a fraction. */
  topCustomerShare?: string;
  /** Weighted evidence rank of the material facts the analysis stands on: 1 audited to 7 company statement. */
  evidenceRank?: string;
};

const d = (value: string | number): Decimal => new Decimal(value);
const fmt = (value: Decimal, digits = 2) => value.toFixed(digits).replace(".", ",");

type Band = {max: string; points: number};
/** Points from the value against ascending ceilings: the first ceiling the value is under wins. */
const pointsUnder = (value: Decimal, bands: readonly Band[], otherwise: number): number => {
  for (const band of bands) if (value.lte(band.max)) return band.points;
  return otherwise;
};
/** Points from the value against ascending floors: the last floor the value clears wins. */
const pointsOver = (value: Decimal, bands: readonly {min: string; points: number}[], otherwise: number): number => {
  let points = otherwise;
  for (const band of bands) if (value.gte(band.min)) points = band.points;
  return points;
};

export function rateCredit(input: RatingInput): InternalRating {
  const {desk, trajectory} = input;
  const burning = desk.profile === "cash_burning";
  const factors: RatingFactor[] = [];

  // ---- leverage: net debt over EBITDA, post-transaction when a trajectory says what it becomes
  if (!burning) {
    const post = trajectory?.liabilityManagement?.postLeverageAfterRefi ?? desk.leverage.scenarios[0]?.postTurns ?? null;
    const value = d(post ?? desk.leverage.preTurns);
    const points = pointsUnder(value, [{max: "1.5", points: 4}, {max: "2.5", points: 3}, {max: "3.5", points: 2}, {max: "4.5", points: 1}], 0);
    factors.push({
      id: "leverage", weight: 3, value: value.toFixed(4), points,
      labels: {pt: "Alavancagem pós-operação", en: "Post-transaction leverage"},
      rationale: {
        pt: `Dívida líquida sobre EBITDA de ${fmt(value)}x após a operação (${post ? "com a estrutura proposta" : "sem trajetória, pré-operação"}). Faixas: até 1,5x forte; até 2,5x adequada; até 3,5x atenção; até 4,5x fraca; acima, crítica.`,
        en: `Net debt over EBITDA of ${value.toFixed(2)}x after the transaction (${post ? "with the proposed structure" : "no trajectory, pre-transaction"}). Bands: up to 1.5x strong; up to 2.5x adequate; up to 3.5x watch; up to 4.5x weak; above, critical.`,
      },
    });
  }

  // ---- coverage: EBITDA over interest expense
  if (!burning) {
    const expenses = input.financialExpenses ? d(input.financialExpenses).abs() : null;
    const value = expenses && expenses.gt(0) ? d(desk.leverage.ebitda).div(expenses) : null;
    const points = value ? pointsOver(value, [{min: "1.5", points: 1}, {min: "2.5", points: 2}, {min: "4", points: 3}, {min: "6", points: 4}], 0) : null;
    factors.push({
      id: "coverage", weight: 2, value: value ? value.toFixed(4) : null, points,
      labels: {pt: "Cobertura de juros", en: "Interest coverage"},
      rationale: value
        ? {pt: `EBITDA cobre a despesa financeira ${fmt(value, 1)} vezes. Faixas: acima de 6x forte; de 4x adequada; de 2,5x atenção; de 1,5x fraca; abaixo, crítica.`, en: `EBITDA covers interest expense ${value.toFixed(1)} times. Bands: above 6x strong; from 4x adequate; from 2.5x watch; from 1.5x weak; below, critical.`}
        : {pt: "Não avaliada: a sala não traz a despesa financeira do último exercício.", en: "Not assessed: the room does not carry the latest year's interest expense."},
    });
  }

  // ---- liquidity: cash over the principal due in twelve months
  {
    const coverage = desk.stack.liquidityCoverage12 ? d(desk.stack.liquidityCoverage12) : null;
    const nothingDue = d(desk.stack.maturingWithin12Months).lte(0);
    const points = nothingDue ? 4 : coverage ? pointsOver(coverage, [{min: "0.5", points: 1}, {min: "1", points: 2}, {min: "1.5", points: 3}, {min: "2.5", points: 4}], 0) : null;
    factors.push({
      id: "liquidity", weight: 2, value: coverage ? coverage.toFixed(4) : nothingDue ? "n/a" : null, points,
      labels: {pt: "Liquidez contra os próximos 12 meses", en: "Liquidity against the next 12 months"},
      rationale: nothingDue
        ? {pt: "Nenhum principal vence nos próximos 12 meses segundo o mapa e o perfil de vencimentos.", en: "No principal falls due in the next 12 months per the schedule and the maturity profile."}
        : coverage
          ? {pt: `Caixa cobre ${fmt(coverage)}x o principal dos próximos 12 meses. Faixas: acima de 2,5x forte; de 1,5x adequada; de 1x atenção; de 0,5x fraca; abaixo, crítica.`, en: `Cash covers ${coverage.toFixed(2)}x the principal due in the next 12 months. Bands: above 2.5x strong; from 1.5x adequate; from 1x watch; from 0.5x weak; below, critical.`}
          : {pt: "Não avaliada: sem vencimentos datados nem perfil de amortização.", en: "Not assessed: no dated maturities and no amortisation profile."},
    });
  }

  // ---- trend: EBITDA against the year before
  {
    const prior = input.priorEbitda ? d(input.priorEbitda) : null;
    const current = d(desk.leverage.ebitda);
    const growth = prior && !prior.isZero() ? current.minus(prior).div(prior.abs()) : null;
    const points = growth ? pointsOver(growth, [{min: "-0.2", points: 1}, {min: "-0.05", points: 2}, {min: "0.05", points: 3}, {min: "0.15", points: 4}], 0) : null;
    factors.push({
      id: "trend", weight: 1, value: growth ? growth.toFixed(4) : null, points,
      labels: {pt: "Tendência do EBITDA", en: "EBITDA trend"},
      rationale: growth
        ? {pt: `EBITDA variou ${fmt(growth.times(100), 1)}% contra o exercício anterior. Faixas: acima de 15% forte; de 5% adequada; de -5% estável; de -20% fraca; abaixo, crítica.`, en: `EBITDA moved ${growth.times(100).toFixed(1)}% against the prior year. Bands: above 15% strong; from 5% adequate; from -5% stable; from -20% weak; below, critical.`}
        : {pt: "Não avaliada: a sala traz um único exercício.", en: "Not assessed: the room carries a single year."},
    });
  }

  // ---- concentration: the largest customer
  {
    const share = input.topCustomerShare ? d(input.topCustomerShare) : desk.runway?.topCustomerShare ? d(desk.runway.topCustomerShare) : null;
    const points = share ? pointsUnder(share, [{max: "0.1", points: 4}, {max: "0.2", points: 3}, {max: "0.3", points: 2}, {max: "0.5", points: 1}], 0) : null;
    factors.push({
      id: "concentration", weight: 1, value: share ? share.toFixed(4) : null, points,
      labels: {pt: "Concentração no maior cliente", en: "Largest-customer concentration"},
      rationale: share
        ? {pt: `O maior cliente responde por ${fmt(share.times(100), 1)}% da receita. Faixas: até 10% forte; até 20% adequada; até 30% atenção; até 50% fraca; acima, crítica.`, en: `The largest customer is ${share.times(100).toFixed(1)}% of revenue. Bands: up to 10% strong; up to 20% adequate; up to 30% watch; up to 50% weak; above, critical.`}
        : {pt: "Não avaliada: a sala não traz concentração de clientes.", en: "Not assessed: the room carries no customer concentration."},
    });
  }

  // ---- evidence: how good is what the grade stands on
  {
    const rank = input.evidenceRank ? d(input.evidenceRank) : null;
    const points = rank ? pointsUnder(rank, [{max: "1.5", points: 4}, {max: "3", points: 3}, {max: "4.5", points: 2}, {max: "6", points: 1}], 0) : null;
    factors.push({
      id: "evidence", weight: 1, value: rank ? rank.toFixed(2) : null, points,
      labels: {pt: "Qualidade da evidência", en: "Evidence quality"},
      rationale: rank
        ? {pt: `Rank médio de evidência dos fatos materiais: ${fmt(rank, 1)} (1 auditado, 7 declaração da empresa). Até 1,5 forte; até 3 adequada; até 4,5 atenção; até 6 fraca.`, en: `Mean evidence rank of the material facts: ${rank.toFixed(1)} (1 audited, 7 company statement). Up to 1.5 strong; up to 3 adequate; up to 4.5 watch; up to 6 weak.`}
        : {pt: "Não avaliada: rank de evidência não informado.", en: "Not assessed: evidence rank not provided."},
    });
  }

  // ---- runway, in place of leverage and coverage for a company that burns cash
  if (burning) {
    const months = desk.runway ? d(desk.runway.monthsPostAfterService) : null;
    const points = months ? pointsOver(months, [{min: "6", points: 1}, {min: "12", points: 2}, {min: "18", points: 3}, {min: "24", points: 4}], 0) : null;
    factors.push({
      id: "runway", weight: 5, value: months ? months.toFixed(1) : null, points,
      labels: {pt: "Runway após a operação, com o serviço", en: "Runway after the deal, with service"},
      rationale: months
        ? {pt: `${fmt(months, 1)} meses de caixa após a captação, pagando os juros dela. Faixas: acima de 24 forte; de 18 adequada; de 12 atenção; de 6 fraca; abaixo, crítica.`, en: `${months.toFixed(1)} months of cash after the raise, paying its interest. Bands: above 24 strong; from 18 adequate; from 12 watch; from 6 weak; below, critical.`}
        : {pt: "Não avaliada: sem queima mensal na sala.", en: "Not assessed: no monthly burn in the room."},
    });
  }

  const assessable = factors.filter((factor) => factor.points !== null);
  const earned = assessable.reduce((sum, factor) => sum + factor.points! * factor.weight, 0);
  const possible = assessable.reduce((sum, factor) => sum + 4 * factor.weight, 0);
  const score = possible > 0 ? Math.round((earned / possible) * 100) : 0;
  // 100 → grade 1, 0 → grade 10, in equal steps; a critical leverage or runway floors the grade.
  let grade = Math.min(10, Math.max(1, 10 - Math.floor(score / 11.2)));
  const floorFactor = factors.find((factor) => (factor.id === "leverage" || factor.id === "runway") && factor.points === 0);
  if (floorFactor) grade = Math.max(grade, 8);
  const band = grade <= 2 ? "strong" : grade <= 4 ? "adequate" : grade <= 6 ? "watch" : grade <= 8 ? "weak" : "distressed";
  const bandPt = {strong: "forte", adequate: "adequado", watch: "atenção", weak: "fraco", distressed: "crítico"}[band];

  return {
    grade,
    score,
    assessed: assessable.length,
    factors,
    band,
    summary: {
      pt: `Rating interno ${grade} de 10 (${bandPt}), ${score} pontos em 100 sobre ${assessable.length} de ${factors.length} fatores avaliáveis${floorFactor ? `; piso em 8 por ${floorFactor.labels.pt.toLowerCase()} crítica` : ""}.`,
      en: `Internal rating ${grade} of 10 (${band}), ${score} points out of 100 over ${assessable.length} of ${factors.length} assessable factors${floorFactor ? `; floored at 8 by critical ${floorFactor.labels.en.toLowerCase()}` : ""}.`,
    },
  };
}

packages/credit-analysis/src/stress.ts.content:
import Decimal from "decimal.js";

import type {DeskAnalysis} from "./analyze";

/**
 * The stress table a committee reads before it prices.
 *
 * Four shocks every credit committee in Brazil applies, standardised so two cases can be
 * compared: EBITDA down 20% and 30%, CDI up 300 bps, the cash cycle 15 days longer, and the
 * largest customer gone. Each shock is recomputed from the desk's own numbers, never from a
 * model, and says what it does to leverage, to the interest bill, to working capital and to
 * the headroom under the tightest covenant. A shock that needs a number the room does not
 * carry says so instead of guessing.
 */

export type StressScenario = {
  id: "ebitda_minus_20" | "ebitda_minus_30" | "cdi_plus_300" | "cycle_plus_15" | "top_customer_lost";
  labels: {pt: string; en: string};
  /** Leverage after the shock, post-transaction on reported EBITDA, or null when not computable. */
  leverage: string | null;
  /** Interest cost after the shock at the stated index levels, or null. */
  annualInterest: string | null;
  /** Working capital the shock absorbs, or null. */
  workingCapitalNeed: string | null;
  /** New money still admitted by the tightest covenant after the shock, or null. */
  covenantHeadroom: string | null;
  /** Whether the shocked leverage breaks the tightest covenant. */
  breachesCovenant: boolean | null;
  assumptions: {pt: string; en: string};
};

export type StressInput = {
  desk: DeskAnalysis;
  /** The transaction amount the stress is run on; the larger stated amount when absent. */
  amount?: string;
  /** Annual revenue, for the cycle shock; the audited year when absent. */
  revenue?: string;
  /** Share of revenue in the largest customer, as a fraction. */
  topCustomerShare?: string;
  /** Contribution margin lost with that customer, as a fraction of its revenue; 0.35 by default. */
  lostCustomerMargin?: string;
};

const d = (value: string | number): Decimal => new Decimal(value);
const ZERO = new Decimal(0);

export function stressTable(input: StressInput): StressScenario[] {
  const {desk} = input;
  const ebitda = d(desk.leverage.ebitda);
  const amount = input.amount ? d(input.amount) : desk.leverage.scenarios.reduce((max, s) => (d(s.amount).gt(max) ? d(s.amount) : max), ZERO);
  const netDebtPost = d(desk.leverage.netDebtPre).plus(amount);
  const grossDebtPost = d(desk.stack.totalOnBalance).plus(amount);
  const ceiling = desk.leverage.tightestCovenant ? d(desk.leverage.tightestCovenant.maximum) : null;
  const cdi = d(desk.assumptions.cdi);
  const weightedCost = desk.stack.weightedCost ? d(desk.stack.weightedCost) : null;
  const cycleDays = desk.workingCapital.cycleDays ? d(desk.workingCapital.cycleDays) : null;
  const revenue = input.revenue ? d(input.revenue) : null;

  const leverageOf = (e: Decimal) => (e.gt(0) ? netDebtPost.div(e) : null);
  const headroomOf = (e: Decimal) => (ceiling && e.gt(0) ? ceiling.times(e).minus(netDebtPost) : null);
  const interestAt = (cost: Decimal | null) => (cost ? grossDebtPost.times(cost) : null);

  const scenario = (
    id: StressScenario["id"], labels: {pt: string; en: string}, shockedEbitda: Decimal, cost: Decimal | null,
    workingCapitalNeed: Decimal | null, assumptions: {pt: string; en: string},
  ): StressScenario => {
    const leverage = leverageOf(shockedEbitda);
    const headroom = headroomOf(shockedEbitda);
    return {
      id, labels,
      leverage: leverage ? leverage.toFixed(4) : null,
      annualInterest: interestAt(cost)?.toFixed(2) ?? null,
      workingCapitalNeed: workingCapitalNeed ? workingCapitalNeed.toFixed(2) : null,
      covenantHeadroom: headroom ? headroom.toFixed(2) : null,
      breachesCovenant: leverage && ceiling ? leverage.gt(ceiling) : null,
      assumptions,
    };
  };

  const base = {pt: "Dívida líquida pós-operação sobre o EBITDA reportado; juros ao custo médio do estoque, com o novo papel ao mesmo custo.", en: "Post-transaction net debt over reported EBITDA; interest at the stack's weighted cost, the new paper at the same cost."};

  return [
    scenario("ebitda_minus_20", {pt: "EBITDA -20%", en: "EBITDA -20%"}, ebitda.times("0.8"), weightedCost, null, base),
    scenario("ebitda_minus_30", {pt: "EBITDA -30%", en: "EBITDA -30%"}, ebitda.times("0.7"), weightedCost, null, base),
    scenario("cdi_plus_300", {pt: "CDI +300 bps", en: "CDI +300 bps"}, ebitda, weightedCost ? weightedCost.plus("0.03") : null, null, {
      pt: `CDI de ${cdi.times(100).toFixed(2).replace(".", ",")}% para ${cdi.plus("0.03").times(100).toFixed(2).replace(".", ",")}%, repassado integralmente ao estoque pós-fixado. EBITDA inalterado.`,
      en: `CDI from ${cdi.times(100).toFixed(2)}% to ${cdi.plus("0.03").times(100).toFixed(2)}%, passed fully to the floating stack. EBITDA unchanged.`,
    }),
    scenario("cycle_plus_15", {pt: "Ciclo de caixa +15 dias", en: "Cash cycle +15 days"}, ebitda, weightedCost, revenue ? revenue.times(15).div(365) : null, {
      pt: cycleDays ? `Ciclo de ${cycleDays.toFixed(0)} para ${cycleDays.plus(15).toFixed(0)} dias; o capital de giro absorvido é 15/365 da receita anual.` : "Ciclo de caixa não calculado; o capital de giro absorvido é 15/365 da receita anual.",
      en: cycleDays ? `Cycle from ${cycleDays.toFixed(0)} to ${cycleDays.plus(15).toFixed(0)} days; the working capital absorbed is 15/365 of annual revenue.` : "Cash cycle not computed; the working capital absorbed is 15/365 of annual revenue.",
    }),
    (() => {
      const share = input.topCustomerShare ? d(input.topCustomerShare) : null;
      const margin = d(input.lostCustomerMargin ?? "0.35");
      const lost = share && revenue ? revenue.times(share).times(margin) : null;
      return scenario("top_customer_lost", {pt: "Perda do maior cliente", en: "Largest customer lost"}, lost ? ebitda.minus(lost) : ebitda, weightedCost, null, {
        pt: share ? `O maior cliente (${share.times(100).toFixed(1).replace(".", ",")}% da receita) sai; o EBITDA perde a margem de contribuição dessa receita (${margin.times(100).toFixed(0)}% assumido).` : "Concentração de clientes não informada; cenário não aplicado ao EBITDA.",
        en: share ? `The largest customer (${share.times(100).toFixed(1)}% of revenue) leaves; EBITDA loses that revenue's contribution margin (${margin.times(100).toFixed(0)}% assumed).` : "Customer concentration not stated; scenario not applied to EBITDA.",
      });
    })(),
  ];
}

