import {z} from "zod";
import {componentIdSchema, componentVersionSchema, contentHashSchema, methodComponentSchema, type MethodValueType} from "./method-component";
import {methodContentHash} from "./procedure-compiler";

export const methodOverrideSchema = z.object({
  componentId: componentIdSchema,
  pointId: componentIdSchema,
  version: componentVersionSchema,
  scope: z.enum(["organization", "unit", "work_type"]),
  scopeId: z.string().min(1).max(120),
  rationale: z.string().trim().min(5).max(2000),
  source: z.object({versionId: z.uuid(), fingerprint: contentHashSchema}).strict(),
  value: z.json(),
}).strict();
export type MethodOverride = z.infer<typeof methodOverrideSchema>;
const lexical = (a: string, b: string) => a < b ? -1 : a > b ? 1 : 0;
const precedence = {organization: 0, unit: 1, work_type: 2} as const;

/** Values are typed parameters, never patches to code, authority or protected components. */
export function matchesMethodValue(type: MethodValueType, value: unknown): boolean {
  switch (type.type) {
    case "null": return value === null;
    case "union": return type.variants.some((variant) => matchesMethodValue(variant, value));
    case "string": return typeof value === "string";
    case "decimal_string": return typeof value === "string" && /^-?\d+(\.\d+)?$/.test(value);
    case "boolean": return typeof value === "boolean";
    case "integer": return typeof value === "number" && Number.isSafeInteger(value);
    case "date": return typeof value === "string" && /^\d{4}-\d{2}-\d{2}$/.test(value) && Number.isFinite(Date.parse(value)) && new Date(value).toISOString().slice(0, 10) === value;
    case "enum": return typeof value === "string" && type.values.includes(value);
    case "array": return Array.isArray(value) && value.every((item) => matchesMethodValue(type.items, item));
    case "map": {
      if (!value || typeof value !== "object" || Array.isArray(value)) return false;
      if (![Object.prototype, null].includes(Object.getPrototypeOf(value))) return false;
      return Object.entries(value).every(([key, entry]) => key.length > 0 && key.length <= 300
        && !["__proto__", "prototype", "constructor"].includes(key) && matchesMethodValue(type.values, entry));
    }
    case "object": {
      if (!value || typeof value !== "object" || Array.isArray(value)) return false;
      const record = value as Record<string, unknown>;
      return Object.keys(record).every((key) => Object.hasOwn(type.fields, key))
        && Object.entries(type.fields).every(([key, field]) => Object.hasOwn(record, key) ? matchesMethodValue(field.value, record[key]) : !field.required);
    }
  }
}

/** A reproducible proposal. Only the database's human publication command grants a release. */
export function composeMethod(input: {
  baseManifestHash: string;
  components: unknown[];
  overrides: unknown[];
  context: {organizationId: string; unitId: string | null; workType: string};
}) {
  const baseManifestHash = contentHashSchema.parse(input.baseManifestHash);
  const components = input.components.map((component) => methodComponentSchema.parse(component));
  const byId = new Map(components.map((component) => [component.id, component]));
  if (byId.size !== components.length) throw new Error("method_component_duplicate");
  const applicable = input.overrides.map((value) => methodOverrideSchema.parse(value));
  const seen = new Set<string>();
  for (const override of applicable) {
    const expected = override.scope === "organization" ? input.context.organizationId : override.scope === "unit" ? input.context.unitId : input.context.workType;
    if (override.scopeId !== expected) throw new Error("method_override_scope_conflict");
    const component = byId.get(override.componentId);
    const point = component?.overridePoints.find((entry) => entry.id === override.pointId);
    if (!component || !point || component.kind === "quality_gate" || component.kind === "formula"
      || (component.kind === "rule" && ["law", "contract"].includes(component.authority))) throw new Error("method_protected_override");
    if (!matchesMethodValue(point.contract.value, override.value)) throw new Error("method_override_contract_conflict");
    const key = `${override.componentId}:${override.pointId}:${override.scope}`;
    if (seen.has(key)) throw new Error("method_override_ambiguous");
    seen.add(key);
  }
  const ordered = [...applicable].sort((a, b) => precedence[a.scope] - precedence[b.scope] || lexical(a.componentId, b.componentId) || lexical(a.pointId, b.pointId));
  const selected = new Map<string, MethodOverride>();
  for (const override of ordered) selected.set(`${override.componentId}:${override.pointId}`, override);
  const parameters = [...selected.values()].sort((a, b) => lexical(a.componentId, b.componentId) || lexical(a.pointId, b.pointId));
  const payload = {schemaVersion: "method-composition.v1", baseManifestHash, context: {...input.context}, components, overrides: ordered, parameters, grantsExecution: false as const};
  return {...payload, manifestHash: methodContentHash(payload)};
}

packages/credit-playbook/src/material-fi.content:
import type {ArchetypeId} from "./types";

/**
 * One economic requirement may be stated under more than one canonical path.
 *
 * Current gross debt is the clearest example: a debt schedule can state it as
 * `debt.total_gross`, while financial statements state it under a dated historical or interim
 * path. Requiring one spelling would turn a complete case into a false gap. The requirement is
 * therefore named once and discharged by any of its accepted patterns.
 */
export type MaterialFieldRequirement = {
  id: string;
  anyOf: readonly string[];
};

const requirement = (id: string, ...anyOf: string[]): MaterialFieldRequirement => ({id, anyOf});

const common: readonly MaterialFieldRequirement[] = [
  requirement("company_legal_name", "company.legal_name"),
  requirement("requested_amount", "transaction.requested_amount"),
  requirement(
    "current_gross_debt",
    "debt.total_gross",
    "interim_financials.*.gross_debt",
    "historical_financials.*.gross_debt",
  ),
];

const perArchetype: Readonly<Record<ArchetypeId, readonly MaterialFieldRequirement[]>> = {
  growth_expansion: [
    requirement("project_total_cost", "project.total_cost"),
    requirement("project_investment", "project.investments.*.amount"),
    requirement("desired_term", "transaction.desired_term_months"),
    requirement("collateral_capacity", "collateral.total_capacity"),
    requirement("minimum_dscr", "projections.minimum_dscr"),
  ],
  working_capital: [
    requirement("receivables_capacity", "collateral.receivables_capacity"),
    requirement("customer_concentration", "customers.top_customers.*.share_pct"),
  ],
  refinance: [
    requirement("debt_maturity", "debt.instruments.*.maturity"),
    requirement("debt_rate", "debt.instruments.*.rate"),
  ],
  acquisition: [
    requirement("post_transaction_leverage", "leverage.post_transaction_net_debt_ebitda"),
  ],
  equipment_finance: [
    requirement("project_total_cost", "project.total_cost"),
    requirement("asset_appraisal", "collateral.assets.*.appraisal_value"),
  ],
  venture_debt: [
    requirement("runway", "company.runway_months"),
    requirement("net_revenue_retention", "company.net_revenue_retention"),
    requirement("last_equity_round", "company.last_equity_round.amount"),
  ],
  other: [],
};

export function materialFieldRequirements(archetypeId: ArchetypeId): MaterialFieldRequirement[] {
  return [...common, ...perArchetype[archetypeId]];
}

const regexpFor = (pattern: string): RegExp => {
  const escaped = pattern.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/\\\*/g, "[^.]+");
  return new RegExp(`^${escaped}$`);
};

export function fieldMatchesPattern(fieldPath: string, pattern: string): boolean {
  return regexpFor(pattern).test(fieldPath);
}

export function requirementIsSatisfied(
  requirement: MaterialFieldRequirement,
  availableFieldPaths: ReadonlySet<string>,
): boolean {
  return requirement.anyOf.some((pattern) =>
    [...availableFieldPaths].some((fieldPath) => fieldMatchesPattern(fieldPath, pattern)),
  );
}

export function fieldsForRequirement<T extends {key: {fieldPath: string}}>(
  requirement: MaterialFieldRequirement,
  facts: readonly T[],
): T[] {
  return facts.filter((fact) => requirement.anyOf.some((pattern) => fieldMatchesPattern(fact.key.fieldPath, pattern)));
}

packages/credit-playbook/src/method-comp.content:
import {z} from "zod";

export const componentIdSchema = z.string().regex(/^[a-z][a-z0-9_.-]{2,119}$/);
export const componentVersionSchema = z.string().regex(/^\d{4}\.\d{2}\.\d{2}-v\d+$/);
export const contentHashSchema = z.string().regex(/^[a-f0-9]{64}$/);

/** Deliberately closed vocabulary: an object/array must describe its children. */
export type MethodValueType =
  | {type: "string" | "decimal_string" | "boolean" | "integer" | "date" | "null"}
  | {type: "enum"; values: string[]}
  | {type: "array"; items: MethodValueType}
  | {type: "map"; values: MethodValueType}
  | {type: "union"; variants: MethodValueType[]}
  | {type: "object"; fields: Record<string, {required: boolean; value: MethodValueType}>};
// Field names describe executor data, not component identities (for example `id`).
const fieldNameSchema = z.string().regex(/^[A-Za-z_][A-Za-z0-9_.-]{0,119}$/)
  .refine((name) => !["__proto__", "prototype", "constructor"].includes(name), "unsafe field name");
function canonicalType(value: MethodValueType): string {
  if (value.type === "object") return JSON.stringify({type: value.type, fields: Object.entries(value.fields).sort(([a], [b]) => a < b ? -1 : a > b ? 1 : 0).map(([key, field]) => [key, field.required, canonicalType(field.value)])});
  if (value.type === "map") return JSON.stringify({type: value.type, values: canonicalType(value.values)});
  if (value.type === "array") return JSON.stringify({type: value.type, items: canonicalType(value.items)});
  if (value.type === "union") return JSON.stringify({type: value.type, variants: value.variants.map(canonicalType).sort()});
  if (value.type === "enum") return JSON.stringify({type: value.type, values: [...value.values].sort()});
  return JSON.stringify(value);
}
export const methodValueTypeSchema: z.ZodType<MethodValueType> = z.lazy(() => z.discriminatedUnion("type", [
  z.object({type: z.enum(["string", "decimal_string", "boolean", "integer", "date", "null"])}).strict(),
  z.object({type: z.literal("enum"), values: z.array(z.string().min(1)).min(1)}).strict(),
  z.object({type: z.literal("array"), items: methodValueTypeSchema}).strict(),
  z.object({type: z.literal("map"), values: methodValueTypeSchema}).strict(),
  z.object({type: z.literal("union"), variants: z.array(methodValueTypeSchema).min(2).refine((variants) => new Set(variants.map(canonicalType)).size === variants.length, "duplicate union variant")}).strict(),
  z.object({type: z.literal("object"), fields: z.record(fieldNameSchema, z.object({required: z.boolean(), value: methodValueTypeSchema}).strict()).refine((fields) => Object.keys(fields).length > 0, "object fields must be typed")}).strict(),
]));
export const methodDataContractSchema = z.object({
  id: componentIdSchema,
  version: componentVersionSchema,
  value: methodValueTypeSchema,
}).strict();
export const componentReferenceSchema = z.object({id: componentIdSchema, version: componentVersionSchema}).strict();
export const methodExecutorSchema = z.object({
  module: z.string().regex(/^@offroad\/[a-z][a-z0-9-]+$/),
  exportName: z.string().regex(/^[A-Za-z_$][A-Za-z0-9_$]*$/),
  version: componentVersionSchema,
}).strict();
export const methodBudgetSchema = z.object({
  maxModelCalls: z.number().int().nonnegative().safe(),
  maxDurationMs: z.number().int().positive().safe(),
  maxCostMinorUnits: z.number().int().nonnegative().safe(),
  currency: z.string().regex(/^[A-Z]{3}$/),
}).strict();
export const protectedMethodInvariants = ["law", "contractual_definition", "traceability", "verification", "access_barriers", "deterministic_financial_math"] as const;
const common = {
  id: componentIdSchema,
  version: componentVersionSchema,
  title: z.string().min(1),
  inputs: methodDataContractSchema,
  outputs: methodDataContractSchema,
  dependencies: z.array(componentReferenceSchema),
  tools: z.array(componentIdSchema),
  effect: z.enum(["none", "propose_state", "commit", "external"]),
  budget: methodBudgetSchema,
  rights: z.object({
    inheritSourceRestrictions: z.literal(true),
    purposes: z.array(componentIdSchema).min(1),
    sourceClasses: z.array(componentIdSchema).min(1),
  }).strict(),
  /** Competencies of the method, never roles or access privileges of a user. */
  competencies: z.array(componentIdSchema).min(1),
  invariants: z.array(z.enum(protectedMethodInvariants)).refine((values) => protectedMethodInvariants.every((value) => values.includes(value)), "all protected invariants must remain"),
  overridePoints: z.array(z.object({
    id: componentIdSchema,
    target: z.enum(["narrative", "template", "assumption"]),
    contract: methodDataContractSchema,
    requiresRationale: z.literal(true),
  }).strict()),
  evidence: z.array(z.string().min(1)),
};
export const methodComponentSchema = z.discriminatedUnion("kind", [
  z.object({...common, kind: z.literal("narrative"), text: z.string().min(1)}).strict(),
  z.object({...common, kind: z.literal("formula"), expression: z.string().min(1), executor: methodExecutorSchema,
    conventions: z.object({unit: z.string().min(1), period: z.string().min(1), rounding: z.string().min(1), traceRequired: z.literal(true)}).strict()}).strict(),
  z.object({...common, kind: z.literal("rule"), authority: z.enum(["law", "contract", "house", "market", "heuristic"]), statement: z.string().min(1), executor: methodExecutorSchema}).strict(),
  z.object({...common, kind: z.literal("workflow"), orchestration: z.enum(["deterministic_pipeline", "dependency_graph"]), steps: z.array(componentReferenceSchema).min(1)}).strict(),
  z.object({...common, kind: z.literal("template"), format: z.enum(["markdown", "json"]), body: z.string().min(1)}).strict(),
  z.object({...common, kind: z.literal("quality_gate"), executor: methodExecutorSchema, failure: z.enum(["block", "disclose_gap"])}).strict(),
]).superRefine((component, context) => {
