    ["availability.performance_deductions", "availability.counterparty_payment_delay"], "specified.availability.payment_review", ["mandate.payment_counterparty_and_deductions"], "availability_deductions_and_payment_risk_map"),
];

packages/credit-playbook/src/preview/cor.content:
/**
 * Frozen corpora the preview may analyse. A company the person names resolves to one of these or
 * to nothing: a company without a frozen base never receives another company's objects, and the
 * router says so instead of guessing. The registry is data; adding a case is adding an entry.
 */
import {case01EvidenceManifest} from "../cases/gc01";

export type PreviewCorpus = {
  caseId: string;
  /** The frozen source pack shipped with the worker image (`SOURCE_PACKS_DIR/<id>/source-pack.json`). */
  sourcePackId: string;
  company: {legalName: string; shortName: string; aliases: string[]; cnpj?: string};
  /** What the base holds, for the reply and the brief. */
  basis: string;
  version: string;
};

export const previewCorpora: PreviewCorpus[] = [
  {
    caseId: case01EvidenceManifest.caseId,
    sourcePackId: "camil",
    company: {
      legalName: "Camil Alimentos S.A.",
      shortName: "Camil",
      aliases: ["camil", "camil alimentos", "camil alimentos s.a.", "camil alimentos sa", "caml3"],
    },
    basis: case01EvidenceManifest.basis,
    version: case01EvidenceManifest.version,
  },
];

/** Lowercase, no accents, no punctuation, single spaces: the form aliases and mentions are compared in. */
export function normalizeMention(value: string): string {
  return value
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

export type CorpusResolution =
  | {kind: "resolved"; corpus: PreviewCorpus; mention: string; alias: string}
  | {kind: "unknown"; mentions: string[]}
  | {kind: "none"};

/**
 * Resolves the companies a turn names to a frozen corpus. A mention matches an alias as a whole
 * word sequence, never as a substring, so "Camila Ferreira" is not Camil. Several mentions with
 * one resolvable company resolve to it; mentions with none resolvable are unknown.
 */
export function resolvePreviewCorpus(mentions: string[]): CorpusResolution {
  const cleaned = mentions.map((mention) => mention.trim()).filter((mention) => mention.length > 0);
  if (cleaned.length === 0) return {kind: "none"};
  for (const mention of cleaned) {
    const normalized = normalizeMention(mention);
    if (!normalized) continue;
    for (const corpus of previewCorpora) {
      for (const alias of corpus.company.aliases) {
        const normalizedAlias = normalizeMention(alias);
        if (normalized === normalizedAlias || ` ${normalized} `.includes(` ${normalizedAlias} `)) {
          return {kind: "resolved", corpus, mention, alias};
        }
      }
    }
  }
  return {kind: "unknown", mentions: cleaned};
}

export function corpusByCaseId(caseId: string): PreviewCorpus | null {
  return previewCorpora.find((corpus) => corpus.caseId === caseId) ?? null;
}

packages/credit-playbook/src/preview/gap.content:
/**
 * The gaps the signed objects declare: what an executor could not prove, cover or reconcile.
 * Questions to the person are generated from these and from nothing else, so a question that
 * names no gap of the base is refused before it reaches the brief.
 */
import type {PreviewStepOutput} from "./run";
import {case01PreviewSteps} from "./workflow";

export const previewGapKeys = [
  "block_reasons", "incomplete_reasons", "unsupported", "unproven_conditions", "legal_conditions",
  "uncovered_terms", "uncovered_series", "assumptions", "open_divergences",
] as const;
export type PreviewGapKey = (typeof previewGapKeys)[number];

export type PreviewGap = {
  /** `<taskId>.<key>[<index>]`, the id a question cites. */
  id: string;
  taskId: string;
  methodId: string;
  objectLabel: string;
  key: PreviewGapKey;
  text: string;
};

function isRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function gapText(item: unknown): string {
  if (typeof item === "string") return item;
  if (isRecord(item)) {
    const head = [item.id, item.series_id, item.rowId, item.field, item.text, item.question].find((value) => typeof value === "string");
    const tail = [item.reason, item.condition, item.detail, item.note, item.state].find((value) => typeof value === "string");
    return [head, tail].filter(Boolean).join(": ") || JSON.stringify(item).slice(0, 200);
  }
  return String(item);
}

/** Every declared gap of every object in the run, in workflow order, bounded per object. */
export function extractPreviewGaps(outputs: Map<string, PreviewStepOutput>, locale: "pt-BR" | "en-US" = "pt-BR", perObjectLimit = 12): PreviewGap[] {
  const gaps: PreviewGap[] = [];
  for (const step of case01PreviewSteps) {
    if (step.stage === "material") continue;
    const output = outputs.get(step.taskId);
    if (!output) continue;
    let count = 0;
    for (const key of previewGapKeys) {
      const value = (output as Record<string, unknown>)[key];
      if (!Array.isArray(value)) continue;
      for (const [index, item] of value.entries()) {
        if (count >= perObjectLimit) break;
        gaps.push({id: `${step.taskId}.${key}[${index}]`, taskId: step.taskId, methodId: step.methodId, objectLabel: step.label[locale === "en-US" ? "en" : "pt"], key, text: gapText(item).slice(0, 300)});
        count += 1;
      }
    }
    const state = (output as Record<string, unknown>).state;
    if (typeof state === "string" && ["blocked", "incomplete", "partial", "conditioned"].includes(state) && count === 0) {
      gaps.push({id: `${step.taskId}.state`, taskId: step.taskId, methodId: step.methodId, objectLabel: step.label[locale === "en-US" ? "en" : "pt"], key: "incomplete_reasons", text: `state ${state} without an itemised reason`});
    }
  }
  return gaps;
}

packages/credit-playbook/src/preview/run.content:
/**
 * Execution of one preview step: which executor runs, on which input, with which premises, and
 * what the artifact records. Every number comes from the executor; this module only binds inputs,
 * applies the declared premises of the turn and derives the facts the material planner may cite,
 * each one read back from the signed output it points to.
 */
import {createHash} from "node:crypto";
import Decimal from "decimal.js";
import {z} from "zod";

import {case01Evidence, case01EvidenceManifest, type Case01Evidence} from "../cases/gc01";
import * as executors from "../executors";
import type {BriefInput} from "../executors/plan-meeting-brief";
import {synthesisSkeleton, type SynthesisOutput} from "./synthesis";
import {case01PreviewSteps, previewStepByTask, type PreviewComposition, type PreviewWorkflowStep} from "./workflow";

export const previewPremisesSchema = z.object({
  /** Annual rate of the new debt of every alternative that raises one, as a decimal ("0.1425"). */
  newDebtAnnualRate: z.string().regex(/^\d+(\.\d+)?$/).optional(),
  newDebtTermMonths: z.number().int().positive().max(360).optional(),
  newDebtGraceMonths: z.number().int().nonnegative().max(120).optional(),
}).strict();
export type PreviewPremises = z.infer<typeof previewPremisesSchema>;

export type PreviewStepOutput = Record<string, unknown> & {state?: string; trace?: {inputFingerprint?: string; outputFingerprint?: string}};

const compare = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
/** The same canonical form the meeting brief executor uses to sign object content. */
export const stableStringify = (value: unknown): string => JSON.stringify(value, (_key, inner: unknown) => (inner && typeof inner === "object" && !Array.isArray(inner) ? Object.fromEntries(Object.entries(inner as Record<string, unknown>).sort(([a], [b]) => compare(a, b))) : inner));
export const fingerprintOf = (value: unknown): string => createHash("sha256").update(stableStringify(value)).digest("hex");

export type PreviewRequest = {
  turn: number;
  composition: PreviewComposition;
  audience: {primary: string; others?: string[]} | null;
  form: BriefInput["request"]["form"];
  pages: number | null;
  sponsorInstruction: string | null;
  undefinedAspects: BriefInput["request"]["undefinedAspects"];
};

export type PreviewRunContext = {
  evidence: Case01Evidence;
  premises: PreviewPremises;
  /** Outputs of the steps already executed in this run or replayed from prior artifacts, by TaskSpec id. */
  outputs: Map<string, PreviewStepOutput>;
  request: PreviewRequest;
  /** The prior meeting brief, when one was planned before: its output and the fingerprints of the objects it saw, so the new plan names what changed. */
  previousBrief: {output: PreviewStepOutput; objectFingerprints: Record<string, string>} | null;

  /** Questions generated from the objects' gaps for the brief planner; when absent, the fixed alignment points of the first readout. */
  candidateQuestions?: BriefInput["candidateQuestions"];
  /** Answers the person gave to earlier questions, carried into the sponsor instruction the planner reads. */
  answers?: Array<{questionId: string; answer: string}>;
  /** The previous synthesis, so the new one names what changed. */
  previousSynthesis?: SynthesisOutput | null;
};

/** Which premises a step consumes: they enter its input fingerprint, so a changed premise recomputes exactly the steps it touches. */
export function premisesFor(step: PreviewWorkflowStep, premises: PreviewPremises): Partial<PreviewPremises> {
  if (step.methodId === "compare-refinancing-before-after" || step.stage === "material") return premises;
  return {};
}

/** The input a step runs on, with the premises of the turn applied where they belong. */
export function previewStepInput(step: PreviewWorkflowStep, context: PreviewRunContext): unknown {
  const evidence = context.evidence;
  switch (step.methodId) {
    case "build-debt-ledger": return evidence["build-debt-ledger"];
    case "reconcile-financial-statements": return evidence["reconcile-financial-statements"];
    case "reconcile-covenant-definitions": return evidence["reconcile-covenant-definitions"];
    case "diagnose-maturity-wall": return evidence["diagnose-maturity-wall"];
    case "build-interest-and-indexation-schedule": return evidence["build-interest-and-indexation-schedule"];
    case "estimate-exit-cost-by-series": return evidence["estimate-exit-cost-by-series"];
    case "declare-scenarios": return evidence["declare-scenarios"];
    case "compare-refinancing-before-after": {
      const base = evidence["compare-refinancing-before-after"];
      const premises = context.premises;
      if (!premises.newDebtAnnualRate && premises.newDebtTermMonths === undefined && premises.newDebtGraceMonths === undefined) return base;
      return {
        ...base,
        alternatives: base.alternatives.map((alternative) => (alternative.newDebt ? {
          ...alternative,
          newDebt: {
            ...alternative.newDebt,
            ...(premises.newDebtAnnualRate ? {annualRate: premises.newDebtAnnualRate} : {}),
            ...(premises.newDebtTermMonths !== undefined ? {termMonths: premises.newDebtTermMonths} : {}),
            ...(premises.newDebtGraceMonths !== undefined ? {graceMonths: premises.newDebtGraceMonths} : {}),
            origin: `${alternative.newDebt.origin}; premissa alterada na conversa (integration_preview): ${describePremises(premises)}`,
          },
        } : alternative)),
      };
    }
    case "plan-meeting-brief": return meetingBriefInput(context);
    case "write-meeting-synthesis": return {outputs: context.outputs, request: context.request};
    default: throw new Error(`no input binding for method ${step.methodId}`);
  }
}

export function describePremises(premises: PreviewPremises): string {
  const parts: string[] = [];
  if (premises.newDebtAnnualRate) parts.push(`taxa da nova dívida ${new Decimal(premises.newDebtAnnualRate).times(100).toFixed(2)}% a.a.`);
  if (premises.newDebtTermMonths !== undefined) parts.push(`prazo ${premises.newDebtTermMonths} meses`);
  if (premises.newDebtGraceMonths !== undefined) parts.push(`carência ${premises.newDebtGraceMonths} meses`);
  return parts.join(", ") || "nenhuma";
}

/** Runs the executor bound to the step. Deterministic: same input, same output, same fingerprints. */
export function runPreviewStep(step: PreviewWorkflowStep, context: PreviewRunContext): {input: unknown; output: PreviewStepOutput} {
  const input = previewStepInput(step, context);
  const output = (() => {
    switch (step.methodId) {
      case "build-debt-ledger": return executors.buildDebtLedger(input as Parameters<typeof executors.buildDebtLedger>[0]);
      case "reconcile-financial-statements": return executors.reconcileFinancialStatements(input as Parameters<typeof executors.reconcileFinancialStatements>[0]);
      case "reconcile-covenant-definitions": return executors.reconcileCovenantDefinitions(input as Parameters<typeof executors.reconcileCovenantDefinitions>[0]);
      case "diagnose-maturity-wall": return executors.diagnoseMaturityWall(input as Parameters<typeof executors.diagnoseMaturityWall>[0]);
      case "build-interest-and-indexation-schedule": return executors.buildInterestAndIndexationSchedule(input as Parameters<typeof executors.buildInterestAndIndexationSchedule>[0]);
      case "estimate-exit-cost-by-series": return executors.estimateExitCostBySeries(input as Parameters<typeof executors.estimateExitCostBySeries>[0]);
      case "declare-scenarios": return executors.declareScenarios(input as Parameters<typeof executors.declareScenarios>[0]);
      case "compare-refinancing-before-after": return executors.compareRefinancingBeforeAfter(input as Parameters<typeof executors.compareRefinancingBeforeAfter>[0]);
      case "plan-meeting-brief": return executors.planMeetingBrief(input as BriefInput);
      case "write-meeting-synthesis": return synthesisSkeleton({outputs: context.outputs, request: context.request, locale: "pt-BR", objectFingerprints: briefObjectFingerprints(context.outputs), previous: context.previousSynthesis ?? null}) as unknown as PreviewStepOutput;
      default: throw new Error(`no executor bound to method ${step.methodId}`);
    }
  })();
  return {input, output: output as unknown as PreviewStepOutput};
}

const objectKindByMethod: Record<string, BriefInput["objects"][number]["kind"]> = {
  "build-debt-ledger": "debt_ledger",
  "reconcile-financial-statements": "reconciliation",
  "reconcile-covenant-definitions": "covenants",
  "diagnose-maturity-wall": "maturity_wall",
  "build-interest-and-indexation-schedule": "interest_schedule",
  "estimate-exit-cost-by-series": "exit_costs",
  "declare-scenarios": "scenarios",
  "compare-refinancing-before-after": "before_after",
};

const objectStates = ["complete", "resolved", "closes", "declared", "compared", "diagnosed", "conditioned", "incomplete", "partial", "open_divergences", "identity_failed", "blocked"] as const;
type ObjectState = (typeof objectStates)[number];

/** The state the brief planner understands, from the state the executor emitted. */
export function briefObjectState(output: PreviewStepOutput): ObjectState {
  const state = typeof output.state === "string" ? output.state : "blocked";
  return (objectStates as readonly string[]).includes(state) ? (state as ObjectState) : "blocked";
}

type Headline = NonNullable<BriefInput["objects"][number]["headlines"]>[number];

const ptNumber = (value: string): string => {
  const decimal = new Decimal(value);
  const [integer, fraction] = decimal.toFixed().replace(/^-/, "").split(".") as [string, string | undefined];
  const grouped = integer.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  return `${decimal.isNegative() ? "-" : ""}${grouped}${fraction ? `,${fraction}` : ""}`;
};
const leaf = (value: unknown, path: string): unknown => path.split(".").reduce<unknown>((current, key) => (current && typeof current === "object" ? (current as Record<string, unknown>)[key] : undefined), value);
const decimalLeaf = (value: unknown, path: string): string | null => {
  const found = leaf(value, path);
  if (typeof found !== "string" && typeof found !== "number") return null;
  try { return new Decimal(found).toFixed(); } catch { return null; }
};

/**
 * Facts the material may cite, each read back from the signed output. A fact is only emitted when
 * the field it quotes exists; nothing is restated by hand.
 */
export function headlinesFor(step: PreviewWorkflowStep, output: PreviewStepOutput, fingerprint: string): Headline[] {
  const unit = typeof output.unit === "string" ? output.unit : null;
  const headlines: Headline[] = [];
  const fact = (headline: Omit<Headline, "objectFingerprint">) => headlines.push({...headline, objectFingerprint: fingerprint} as Headline);
  switch (step.methodId) {
    case "build-debt-ledger": {
      const gross = decimalLeaf(output, "gross_debt");
      if (gross && unit) fact({text: `Dívida bruta de ${ptNumber(gross)} (${unit}) em ${String(output.reference_date ?? "")}`, stance: "neutral", unit, objectPath: "gross_debt", value: {amount: gross, unit}, stanceBasis: null});
      break;
    }
    case "reconcile-financial-statements": {
      const open = Array.isArray(output.open_divergences) ? output.open_divergences.length : 0;
      if (open > 0) fact({text: `${open} divergências ficam abertas entre demonstrações, notas e release; nenhuma foi fechada por arredondamento silencioso`, stance: "against", unit: null, objectPath: "open_divergences", value: null, stanceBasis: {path: "open_divergences", comparator: "nonempty", threshold: null, whenTrue: "against"}});
      break;
    }
    case "diagnose-maturity-wall": {
      const peakPeriod = leaf(output, "peak.period");
      const peakAmount = decimalLeaf(output, "peak.amount");
      if (typeof peakPeriod === "string" && peakAmount && unit) fact({text: `Pico de vencimentos em ${peakPeriod}: ${ptNumber(peakAmount)} (${unit})`, stance: "against", unit, objectPath: "peak", value: {amount: peakAmount, unit}, stanceBasis: {path: "walls", comparator: "nonempty", threshold: null, whenTrue: "against"}});
      break;
    }
    case "compare-refinancing-before-after": {
      const first = leaf(output, "ranking.order.0.id") ?? leaf(output, "ranking.order.0.alternative_id");
      if (typeof first === "string") fact({text: `A alternativa ${first} lidera a comparação antes e depois; o ranking vale só sobre o que foi precificado`, stance: "for", unit: null, objectPath: "ranking", value: null, stanceBasis: {path: "ranking.order", comparator: "nonempty", threshold: null, whenTrue: "for"}});
      break;
    }
    case "declare-scenarios": {
      const count = Array.isArray(output.scenarios) ? output.scenarios.length : 0;
      if (count > 0) fact({text: `${count} cenários declarados, cada um com a origem de cada premissa`, stance: "neutral", unit: null, objectPath: "scenarios", value: null, stanceBasis: null});
      break;
    }
    default:
      break;
  }
  return headlines;
}

/** The meeting brief input, built from the outputs of the other steps: signed content, states and facts. */
export function meetingBriefInput(context: PreviewRunContext): BriefInput {
  const objects = case01PreviewSteps.filter((step) => step.stage !== "material").flatMap((step) => {
    const output = context.outputs.get(step.taskId);
    if (!output) return [];
    const content = {...output};
    const fingerprint = fingerprintOf(content);
    return [{
      id: step.taskId.toLowerCase(),
      kind: objectKindByMethod[step.methodId]!,
      state: briefObjectState(output),
      fingerprint,
      content,
      unit: typeof output.unit === "string" ? output.unit : null,
      headlines: headlinesFor(step, output, fingerprint),
    }];
  });
  const documents = previewBaseDocuments();
  const previous = context.previousBrief;
  const previousOutput = previous?.output;
  const previousVersion = previous && previousOutput && typeof previousOutput.trace === "object" && previousOutput.trace && typeof previousOutput.trace.outputFingerprint === "string" && previousOutput.deliverable && typeof previousOutput.deliverable === "object"
    ? {
        outputFingerprint: previousOutput.trace.outputFingerprint,
        blocks: ((previousOutput.deliverable as Record<string, unknown>).blocks as Array<{id: string; state: "filled" | "gap"; object_ids: string[]}>).map((block) => ({id: block.id, state: block.state, objectIds: block.object_ids})),
        objectFingerprints: previous.objectFingerprints,
      }
    : null;
  const answeredIds = new Set((context.answers ?? []).map((answer) => answer.questionId));
  const carriedQuestions: BriefInput["candidateQuestions"] = previousOutput && Array.isArray(previousOutput.alignment_questions)
    ? (previousOutput.alignment_questions as Array<{id?: unknown; text?: unknown; changes_the_work?: unknown}>)
        .filter((question) => typeof question.id === "string" && typeof question.text === "string" && !answeredIds.has(question.id))
        .map((question, index) => ({id: question.id as string, text: question.text as string, changesTheWork: typeof question.changes_the_work === "string" ? question.changes_the_work : "define a forma e a profundidade do trabalho", coverage: {searched: documents, answeredBy: null, answer: null}, priority: index}))
    : [];
  const {turn, audience, form, pages, sponsorInstruction, undefinedAspects} = context.request;
  return {
    documents,
    caseId: case01EvidenceManifest.caseId,
    request: {turn, audience: audience ? {primary: audience.primary, others: audience.others ?? []} : null, form, pages, sponsorInstruction: context.answers?.length ? `${sponsorInstruction ?? ""}\n${context.answers.map((answer) => `Resposta a ${answer.questionId}: ${answer.answer}`).join("\n")}`.trim().slice(0, 4_000) : sponsorInstruction, undefinedAspects, confirmedPlanId: null},
    objects,
    // Without new questions for this run, the previous brief's unanswered questions stay open: a
    // premise change or a material request must not silently drop what the desk asked, or the
    // person's later answer has nothing to match. New model questions replace them.
    candidateQuestions: context.candidateQuestions ?? (carriedQuestions.length ? carriedQuestions : context.request.composition === "prepare_meeting" ? [
      {id: "q-angle", text: "Leitura de refinanciamento ou alternativas mais amplas?", changesTheWork: "define o universo de alternativas", coverage: {searched: documents, answeredBy: null, answer: null}, priority: 0},
      {id: "q-meeting", text: "Reunião exploratória ou produto a testar?", changesTheWork: "define profundidade e forma", coverage: {searched: documents, answeredBy: null, answer: null}, priority: 1},
      {id: "q-format", text: "Briefing interno, páginas de pitch ou análise com cenários?", changesTheWork: "define o material", coverage: {searched: documents, answeredBy: null, answer: null}, priority: 2},
    ] : []),
    previousVersion,
  };
}

/** The fingerprints the brief planner saw for each object, keyed as the planner keys them; the next turn's change note compares against these. */
export function briefObjectFingerprints(outputs: Map<string, PreviewStepOutput>): Record<string, string> {
  return Object.fromEntries(case01PreviewSteps.filter((step) => step.methodId !== "plan-meeting-brief" && step.methodId !== "write-meeting-synthesis" && outputs.has(step.taskId)).map((step) => [step.taskId.toLowerCase(), fingerprintOf({...outputs.get(step.taskId)!})]));
}

/** What the artifact of a step records around the executor's output. */
export function previewArtifactContent(step: PreviewWorkflowStep, output: PreviewStepOutput, premises: PreviewPremises): Record<string, unknown> {
  return {
    preview: {
      mode: "integration_preview",
      methodId: step.methodId,
      methodVersion: step.methodVersion,
      methodMaturity: "implemented",
      evidence: {caseId: case01EvidenceManifest.caseId, basis: case01EvidenceManifest.basis, version: case01EvidenceManifest.version, note: case01EvidenceManifest.note},
      premisesApplied: premisesFor(step, premises),
      disclaimer: "Validação interna. Método em estágio implemented, sem revisão independente aprovada; nada aqui é liberação, parecer ou aprovação.",
    },
    output,
  };
}

export {previewStepByTask};

/** The documents of the frozen base every candidate question's coverage declares as searched, whatever the composition. */
export function previewBaseDocuments(): string[] {
  return [...new Set(case01Evidence()["declare-scenarios"].documents.map((document) => document.name))].sort(compare);
}

packages/credit-playbook/src/preview/syn.content:
/**
 * The banker's synthesis of the signed objects: the prose a person reads before the meeting.
 * Two sources, one contract. Without a model the synthesis is a skeleton: every section lists
 * the headlines the objects already state, in their words, with their object paths. With a model
 * the sections carry prose, and every number in that prose is checked against the numbers the
 * objects hold: a sentence with a number the objects do not hold is removed and listed, so the
 * text never says more than the objects do. Fingerprints of the objects it read make the change
 * note of the next version deterministic.
 */
import {createHash} from "node:crypto";
import {z} from "zod";

import type {PreviewRequest, PreviewStepOutput} from "./run";
import {case01PreviewSteps} from "./workflow";

export const synthesisSectionSchema = z.object({
  id: z.string().regex(/^[a-z][a-z0-9_-]{1,40}$/),
  title: z.string().min(2).max(120),
  paragraphs: z.array(z.object({
    text: z.string().min(1).max(1_200),
    /** Object paths the paragraph draws on (`c09.covenants[0].ratio`); prose without a reference is allowed, numbers without one are not. */
    references: z.array(z.string().max(120)).max(12).default([]),
  })).min(1).max(8),
});
export type SynthesisSection = z.infer<typeof synthesisSectionSchema>;

export const synthesisOutputSchema = z.object({
  schema_version: z.literal("preview-synthesis.v1"),
  state: z.enum(["skeleton", "drafted"]),
  sections: z.array(synthesisSectionSchema).min(1).max(10),
  numbers: z.object({
    verified: z.number().int().nonnegative(),
    removed: z.array(z.object({sectionId: z.string(), sentence: z.string().max(600), numbers: z.array(z.string()).max(10)})).max(60),
  }),
  objects_read: z.record(z.string(), z.string()),
  change_note: z.array(z.string().max(200)).max(40),
  source: z.object({kind: z.enum(["skeleton", "model"]), model: z.string().nullable(), costUsd: z.number().nonnegative(), latencyMs: z.number().nonnegative(), reason: z.string().max(300).nullable()}),

  /** The fingerprint of everything above, so the synthesis is compared like every other object. */
  trace: z.object({outputFingerprint: z.string().regex(/^[a-f0-9]{64}$/)}),
});
export type SynthesisOutput = z.infer<typeof synthesisOutputSchema>;

const stable = (value: unknown): string => JSON.stringify(value, (_key, inner: unknown) => (inner && typeof inner === "object" && !Array.isArray(inner) ? Object.fromEntries(Object.entries(inner as Record<string, unknown>).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))) : inner));

/** The fingerprint of a synthesis without its trace: the same objects and the same prose give the same value. */
export function synthesisFingerprint(output: Omit<SynthesisOutput, "trace">): string {
  return createHash("sha256").update(stable(output)).digest("hex");
}

export const synthesisSectionOrder: Array<{id: string; title: {pt: string; en: string}; tasks: string[]}> = [
  {id: "situation", title: {pt: "Situação atual da dívida", en: "Current debt situation"}, tasks: ["C05", "D07"]},
  {id: "covenants", title: {pt: "Covenants e condições", en: "Covenants and conditions"}, tasks: ["C09"]},
  {id: "maturities", title: {pt: "Vencimentos, juros e custo de saída", en: "Maturities, interest and exit cost"}, tasks: ["C10", "C07", "S07"]},
  {id: "alternatives", title: {pt: "Cenários e alternativas", en: "Scenarios and alternatives"}, tasks: ["C08", "S10"]},
  {id: "next_steps", title: {pt: "Pontos a alinhar e próximos passos", en: "Points to align and next steps"}, tasks: ["A01"]},
];

type Headline = {text: string; objectPath?: string; stance?: string};

function headlinesOf(output: PreviewStepOutput | undefined): Headline[] {
  if (!output) return [];
  const record = output as Record<string, unknown>;
  const deliverable = record.deliverable;
  if (deliverable && typeof deliverable === "object" && Array.isArray((deliverable as Record<string, unknown>).blocks)) {
    return ((deliverable as Record<string, unknown>).blocks as Array<Record<string, unknown>>).flatMap((block) => Array.isArray(block.headlines) ? (block.headlines as Headline[]) : []);
  }
  return [];
}

/** Every number the objects hold, in the forms prose writes them (1234.5, 1.234,5, 1234,5, 4.72x, 4,72x, 15.5%). */
export function numberVocabulary(outputs: Map<string, PreviewStepOutput>): Set<string> {
  const vocabulary = new Set<string>();
  const add = (value: string) => {
    const trimmed = value.trim();
    if (!/^-?\d+(\.\d+)?$/.test(trimmed)) return;
    const [whole = "", fraction] = trimmed.replace("-", "").split(".");
    const grouped = whole.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
    const variants = new Set<string>([trimmed, whole, grouped]);
    if (fraction !== undefined) {
      variants.add(`${whole},${fraction}`); variants.add(`${grouped},${fraction}`);
      for (const digits of [0, 1, 2]) {
        const rounded = Number(trimmed).toFixed(digits);
        variants.add(rounded); variants.add(rounded.replace(".", ","));
        const [roundedWhole = ""] = rounded.split(".");
        variants.add(roundedWhole.replace(/\B(?=(\d{3})+(?!\d))/g, "."));
      }
      const percent = (Number(trimmed) * 100).toFixed(2);
      variants.add(`${percent}%`); variants.add(`${percent.replace(".", ",")}%`); variants.add(`${percent.replace(/\.?0+$/, "")}%`); variants.add(`${percent.replace(/\.?0+$/, "").replace(".", ",")}%`);
    }
    for (const variant of variants) { const bare = variant.replace(/^-/, ""); vocabulary.add(bare); vocabulary.add(`${bare}x`); }
  };
  const walk = (value: unknown, depth: number) => {
    if (depth > 8 || value === null || value === undefined) return;
    if (typeof value === "number") add(String(value));
    else if (typeof value === "string") add(value);
    else if (Array.isArray(value)) value.forEach((item) => walk(item, depth + 1));
    else if (typeof value === "object") Object.values(value as Record<string, unknown>).forEach((item) => walk(item, depth + 1));
  };
  for (const [taskId, output] of outputs) if (taskId !== "A02") walk(output, 0);
  return vocabulary;
}

const NUMBER_PATTERN = /\d[\d.,]*(?:%|x)?/g;
const YEAR_OR_SMALL = /^(19|20)\d{2}$|^\d{1,2}$/;

/** Sentences whose numbers the objects do not hold are removed, sentence by sentence, and listed. */
export function validateSynthesisNumbers(sections: SynthesisSection[], vocabulary: Set<string>): {sections: SynthesisSection[]; verified: number; removed: SynthesisOutput["numbers"]["removed"]} {
  const removed: SynthesisOutput["numbers"]["removed"] = [];
  let verified = 0;
  const kept = sections.map((section) => ({
    ...section,
    paragraphs: section.paragraphs.flatMap((paragraph) => {
      // Sentences end at a period, exclamation or question mark followed by a space and a capital or a digit; a thousands separator never ends one.
      const sentences = paragraph.text.split(/(?<=[.!?])\s+(?=[A-ZÁÉÍÓÚÂÊÔÃÕÇ0-9])/).map((sentence) => sentence.trim()).filter(Boolean);
      const surviving: string[] = [];
      for (const sentence of sentences) {
        const numbers = (sentence.match(NUMBER_PATTERN) ?? []).map((token) => token.replace(/[.,]$/, "")).filter((token) => !YEAR_OR_SMALL.test(token.replace(/[%x]$/, "")));
        const unverifiable = numbers.filter((token) => !vocabulary.has(token) && !vocabulary.has(token.replace(/[%x]$/, "")));
        if (unverifiable.length > 0) removed.push({sectionId: section.id, sentence: sentence.trim().slice(0, 600), numbers: unverifiable.slice(0, 10)});
        else { verified += numbers.length; surviving.push(sentence.trim()); }
      }
      const text = surviving.join(" ").trim();
      return text ? [{...paragraph, text}] : [];
    }),
  })).filter((section) => section.paragraphs.length > 0);
  return {sections: kept, verified, removed};
}

/** The skeleton: the objects' own headlines, section by section, no prose. */
export function synthesisSkeleton(input: {outputs: Map<string, PreviewStepOutput>; request: PreviewRequest; locale: "pt-BR" | "en-US"; objectFingerprints: Record<string, string>; previous: SynthesisOutput | null}): SynthesisOutput {
  const lang = input.locale === "en-US" ? "en" : "pt";
  const sections: SynthesisSection[] = [];
  for (const section of synthesisSectionOrder) {
    const paragraphs: SynthesisSection["paragraphs"] = [];
    for (const taskId of section.tasks) {
      const output = input.outputs.get(taskId);
      if (!output) continue;
      const step = case01PreviewSteps.find((candidate) => candidate.taskId === taskId);
      const state = typeof (output as Record<string, unknown>).state === "string" ? String((output as Record<string, unknown>).state) : "unknown";
      const headlines = headlinesOf(input.outputs.get("A01")).filter((headline) => headline.objectPath?.startsWith(`${taskId.toLowerCase()}.`) || headline.objectPath === taskId.toLowerCase());
      const text = headlines.length
        ? headlines.map((headline) => headline.text).join(" ")
        : lang === "pt" ? `${step?.label.pt ?? taskId}: estado ${state}; nenhum fato citável assinado por este objeto.` : `${step?.label.en ?? taskId}: state ${state}; no citable fact signed by this object.`;
      paragraphs.push({text, references: headlines.map((headline) => headline.objectPath ?? taskId.toLowerCase()).slice(0, 12)});
    }
    if (paragraphs.length) sections.push({id: section.id, title: section.title[lang], paragraphs});
  }
  const output: Omit<SynthesisOutput, "trace"> = {
    schema_version: "preview-synthesis.v1",
    state: "skeleton",
    sections: sections.length ? sections : [{id: "situation", title: synthesisSectionOrder[0]!.title[lang], paragraphs: [{text: lang === "pt" ? "Nenhum objeto disponível para a síntese." : "No object available for the synthesis.", references: []}]}],
    numbers: {verified: 0, removed: []},
    objects_read: input.objectFingerprints,
    change_note: synthesisChangeNote(input.previous?.objects_read ?? null, input.objectFingerprints, input.locale),
    source: {kind: "skeleton", model: null, costUsd: 0, latencyMs: 0, reason: null},
  };
  return {...output, trace: {outputFingerprint: synthesisFingerprint(output)}};
}

/** Which objects changed since the previous synthesis, by fingerprint, in words the reader checks against the panel. */
export function synthesisChangeNote(previous: Record<string, string> | null, current: Record<string, string>, locale: "pt-BR" | "en-US"): string[] {
  if (!previous) return [];
  const lang = locale === "en-US" ? "en" : "pt";
  const notes: string[] = [];
  for (const [taskId, fingerprint] of Object.entries(current)) {
    const step = case01PreviewSteps.find((candidate) => candidate.taskId === taskId);
    const label = step?.label[lang] ?? taskId;
    if (!(taskId in previous)) notes.push(lang === "pt" ? `${label}: objeto novo` : `${label}: new object`);
    else if (previous[taskId] !== fingerprint) notes.push(lang === "pt" ? `${label}: objeto alterado` : `${label}: object changed`);
  }
  for (const taskId of Object.keys(previous)) if (!(taskId in current)) notes.push(lang === "pt" ? `${taskId}: objeto ausente` : `${taskId}: object missing`);
  return notes;
}

