  /\b(?:no|na|nos|nas|do|da|dos|das|em seu|em sua|de seu|de sua)\s+(?:passivo|ativo|balanco patrimonial|balanco)\b[^,;]*?(?=\bmais\b|\bmenos\b|\be\b|,|;|\bcom\b|$)/g,
