  {id:"MA-26",slug:"room-hygiene",title:"Higiene da sala",product:"Relatório de duplicidade, versão, metadados e integridade",templates:["institutional-data-room-index"],method:["Detectar duplicatas, versões superadas, abas ocultas, metadados reveladores e inconsistências de nome ou hash.","Executar inspeção automatizada e amostra de mesa registrada."],verification:["Bloquear abertura com achado crítico não tratado.","Preservar originais e registrar qualquer cópia saneada como derivado."]},
