  {id:"MA-30",slug:"disclaimers",title:"Disclaimers",product:"Disclaimer vigente em todos os materiais",templates:["institutional-teaser","institutional-credit-memo","indicative-term-sheet"],method:["Inserir texto jurídico vigente sobre assessoria técnica, confidencialidade, underwriting do investidor e ausência de oferta, recomendação, parecer ou compromisso.","Ligar a versão do disclaimer ao manifesto do artefato."],verification:["Conferir presença e hash do texto em cada material aplicável.","Bloquear texto vencido, alterado ou ausente."],legal:true},
